\E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line}  \sum_{f_X, f_Z}\big\| \sqrt{T^{\line_X, \line_Z}_{f_X, f_Z}} \ot W^{x,z}_{f_X(x),f_Z(z)} \ket{\hat{\psi}}\big\|^2 
