m:qld-global-pair-error-bound}\\n2490:\\t\\\\lean{MIPStarRE.QPBT.exists_global_pair_error_bound}\\n2491:\\t\\\\leanok\\n2519:\\t\\\\leanok\\n\",\"exit_code\":0,\"status\":\"completed\"}}\nresults/telemetry/sessions/reviewer-pr400-20260909-01.jsonl:56:{\"type\":\"item.completed\",\"item\":{\"id\":\"item_27\",\"type\":\"command_execution\",\"command\":\"/bin/bash -lc \\\"sed -n '1,195p' MIPStarRE/QPBT/Combining/OverlapGap.lean\\\"\",\"aggregated_output\":\"import MIPStarRE.QPBT.Games.DistanceTheorems.Support\\nimport MIPStarRE.LDT.Preliminaries.SwitchSandwichPrep.InnerProduct\\n\\n/-!\\n# Replacing one factor of a measurement-weighted overlap\\n\\nThe scalar estimates used to combine the two Pauli bases compare averaged\\noverlaps whose left factor is one complete measurement and whose right factors\\nare operator families at small state-dependent distance.  This module records\\nthe corresponding Cauchy--Schwarz estimate.  The right-hand families are\\narbitrary, so the estimate covers an ordered product of point effects, which\\nis not itself a measurement.\\n\\n## References\\n\\nThe estimate is `lem:overlap-gap-distance` in\\n`blueprint/src/chapter/ch15_qpbt_combining.tex`; it is the Cauchy--Schwarz\\nstep at paper\\n`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1147-1166`.\\n-/\\n\\nopen scoped BigOperators Matrix MatrixOrder ComplexOrder\\n\\nnamespace MIPStarRE.QPBT\\n\\nopen MIPStarRE.LDT hiding Measurement\\nopen MIPStarRE.Quantum MIPStarRE.QPBT.DistanceCalculus\\n\\n/-- Replacing one operator family inside an overlap weighted on the left by a\\ncomplete measurement changes the average by at most the square root of the\\nstate-dependent squared distance between the two families. -/\\ntheorem abs_overlap_gap_le_sqrt_of_opFamilyDistSq {X α ι : Type*}\\n    [Fintype α] [Fintype ι] [DecidableEq ι]\\n    (μ : Distribution X) (A : X → Measurement α ι) (B C : X → α → Op ι)\\n    (ψ : EuclideanSpace ℂ ι) (hμ : μ.IsProbability) (hψ : ‖ψ‖ = 1)\\n    (ζ : ℝ) (hBC : opFamilyDistSq μ B C ψ ≤ ζ) :\\n    |avgOver μ (fun x => ∑ a : α, stateQForm ψ ((A x).effect a * B x a)) -\\n        avgOver μ (fun x => ∑ a : α, stateQForm ψ ((A x).effect a * C x a))| ≤\\n      Real.sqrt ζ := by\\n  classical\\n  have hnorm_sq : ∀ M : Op ι,\\n      ‖applyOperatorToState M ψ‖ ^ 2 = stateQForm ψ (Mᴴ * M) := by\\n    intro M\\n    rw [@norm_sq_eq_re_inner ℂ]\\n    unfold stateQForm applyOperatorToState\\n    rw [Matrix.toEuclideanLin_conjTranspose_mul_self]\\n    change (inner ℂ (Matrix.toEuclideanLin M ψ) (Matrix.toEuclideanLin M ψ)).re =\\n      (inner ℂ ψ ((Matrix.toEuclideanLin M).adjoint\\n        (Matrix.toEuclideanLin M ψ))).re\\n    rw [LinearMap.adjoint_inner_right]\\n  have hmul : ∀ M N : Op ι, Mᴴ = M →\\n      stateQForm ψ (M * N) =\\n        (inner ℂ (applyOperatorToState M ψ)\\n          (applyOperatorToState N ψ)).re := by\\n    intro M N hM\\n    have hadjoint : (Matrix.toEuclideanLin M).adjoint =\\n        Matrix.toEuclideanLin M := by\\n      rw [← Matrix.toEuclideanLin_conjTranspose_eq_adjoint, hM]\\n    calc\\n      stateQForm ψ (M * N) =\\n          (inner ℂ ψ\\n            (applyOperatorToState M (applyOperatorToState N ψ))).re := by\\n        rw [stateQForm, applyOperatorToState_mul]\\n      _ = (inner ℂ ψ ((Matrix.toEuclideanLin M).adjoint\\n            (applyOperatorToState N ψ))).re := by\\n        rw [hadjoint]\\n        rfl\\n      _ = _ := by\\n        rw [LinearMap.adjoint_inner_right]\\n        rfl\\n  have hleft : ∀ x : X,\\n      (∑ a : α, ‖applyOperatorToState ((A x).effect a) ψ‖ ^ 2) ≤ 1 := by\\n    intro x\\n    have htotal : (∑ a : α, stateQForm ψ ((A x).effect a)) = 1 := by\\n      calc\\n        (∑ a : α, stateQForm ψ ((A x).effect a)) =\\n            stateQForm ψ (∑ a : α, (A x).effect a) := by\\n          simp [stateQForm, applyOperatorToState]\\n        _ = stateQForm ψ 1 := by rw [(A x).sum_eq_one]\\n        _ = 1 := by rw [stateQForm]; simp [applyOperatorToState, hψ]\\n    calc\\n      (∑ a : α, ‖applyOperatorToState ((A x).effect a) ψ‖ ^ 2) ≤\\n          ∑ a : α, stateQForm ψ ((A x).effect a) := by\\n        refine Finset.sum_le_sum ?_\\n        intro a _\\n        rw [hnorm_sq, measurement_effect_hermitian]\\n        exact quadratic_form_mono (MIPStarRE.Quantum.sq_le_self ((A x).pos a)\\n          (measurement_effect_le_one (A x) a)) ψ\\n      _ = 1 := htotal\\n  have hgnonneg : ∀ x : X,\\n      0 ≤ ∑ a : α, ‖applyOperatorToState (B x a - C x a) ψ‖ ^ 2 :=\\n    fun x => Finset.sum_nonneg fun a _ => sq_nonneg _\\n  have hpoint : ∀ x : X,\\n      |∑ a : α, stateQForm ψ ((A x).effect a * (B x a - C x a))| ≤\\n        Real.sqrt (∑ a : α, ‖applyOperatorToState (B x a - C x a) ψ‖ ^ 2) := by\\n    intro x\\n    let u : α → EuclideanSpace ℂ ι := fun a =>\\n      applyOperatorToState ((A x).effect a) ψ\\n    let v : α → EuclideanSpace ℂ ι := fun a =>\\n      applyOperatorToState (B x a - C x a) ψ\\n    have hrw : (∑ a : α, stateQForm ψ ((A x).effect a * (B x a - C x a))) =\\n        ∑ a : α, (inner ℂ (u a) (v a)).re := by\\n      refine Finset.sum_congr rfl ?_\\n      intro a _\\n      exact hmul _ _ (measurement_effect_hermitian (A x) a)\\n    have hone : Real.sqrt (∑ a : α, ‖u a‖ ^ 2) ≤ 1 := by\\n      rw [← Real.sqrt_one]\\n      exact Real.sqrt_le_sqrt (hleft x)\\n    calc\\n      |∑ a : α, stateQForm ψ ((A x).effect a * (B x a - C x a))| =\\n          |∑ a : α, (inner ℂ (u a) (v a)).re| := by rw [hrw]\\n      _ ≤ ∑ a : α, |(inner ℂ (u a) (v a)).re| :=\\n        Finset.abs_sum_le_sum_abs _ _\\n      _ ≤ ∑ a : α, ‖u a‖ * ‖v a‖ := by\\n        refine Finset.sum_le_sum ?_\\n        intro a _\\n        exact (Complex.abs_re_le_norm _).trans (norm_inner_le_norm (u a) (v a))\\n      _ ≤ Real.sqrt (∑ a : α, ‖u a‖ ^ 2) * Real.sqrt (∑ a : α, ‖v a‖ ^ 2) := by\\n        simpa using Real.sum_mul_le_sqrt_mul_sqrt\\n          (Finset.univ : Finset α) (fun a => ‖u a‖) (fun a => ‖v a‖)\\n      _ ≤ 1 * Real.sqrt (∑ a : α, ‖v a‖ ^ 2) :=\\n        mul_le_mul_of_nonneg_right hone (Real.sqrt_nonneg _)\\n      _ = Real.sqrt (∑ a : α,\\n            ‖applyOperatorToState (B x a - C x a) ψ‖ ^ 2) := one_mul _\\n  have hdiff :\\n      avgOver μ (fun x => ∑ a : α, stateQForm ψ ((A x).effect a * B x a)) -\\n          avgOver μ (fun x => ∑ a : α,\\n            stateQForm ψ ((A x).effect a * C x a)) =\\n        avgOver μ (fun x => ∑ a : α,\\n          stateQForm ψ ((A x).effect a * (B x a - C x a))) := by\\n    rw [← avgOver_sub]\\n    refine avgOver_congr μ _ _ ?_\\n    intro x\\n    rw [← Finset.sum_sub_distrib]\\n    refine Finset.sum_congr rfl ?_\\n    intro a _\\n    simp [stateQForm, applyOperatorToState, mul_sub]\\n  rw [hdiff]\\n  refine le_trans\\n    (MIPStarRE.LDT.Preliminaries.avgOver_abs_le_sqrt_of_pointwise μ _ _\\n      hpoint hgnonneg (by rw [hμ.weight_sum_eq_one])) ?_\\n  exact Real.sqrt_le_sqrt hBC\\n\\n/-! ## The Cauchy--Schwarz inequality weighted by a positive operator -/\\n\\n/-- For a positive operator `A`, the sesquilinear form `⟨u, A v⟩` satisfies the\\nCauchy--Schwarz inequality with the two diagonal values `⟨u, A u⟩` and\\n`⟨v, A v⟩`.  This is the inequality behind the Cauchy--Schwarz steps of the\\nproofs of `lem:claim-17-2` and `lem:claim-17-3`, in which both factors carry\\nthe square root of the line effect, paper\\n`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1168-1209`. -/\\ntheorem norm_inner_applyOperatorToState_le_sqrt_mul_sqrt {ι : Type*}\\n    [Fintype ι] [DecidableEq ι] {A : Op ι} (hA : 0 ≤ A)\\n    (u v : EuclideanSpace ℂ ι) :\\n    ‖inner ℂ u (applyOperatorToState A v)‖ ≤\\n      Real.sqrt (inner ℂ u (applyOperatorToState A u)).re *\\n        Real.sqrt (inner ℂ v (applyOperatorToState A v)).re := by\\n  set R : Op ι := CFC.sqrt A with hR\\n  have hRnonneg : 0 ≤ R := CFC.sqrt_nonneg A\\n  have hRR : R * R = A := CFC.sqrt_mul_sqrt_self A hA\\n  have hRherm : Rᴴ = R :=\\n    (Matrix.nonneg_iff_posSemidef.mp hRnonneg).isHermitian.eq\\n  have hadjoint : (Matrix.toEuclideanLin R).adjoint = Matrix.toEuclideanLin R := by\\n    rw [← Matrix.toEuclideanLin_conjTranspose_eq_adjoint, hRherm]\\n  have hsplit : ∀ w z : EuclideanSpace ℂ ι,\\n      inner ℂ w (applyOperatorToState A z) =\\n        inner ℂ (applyOperatorToState R w) (applyOperatorToState R z) := by\\n    intro w z\\n    have h := LinearMap.adjoint_inner_right (Matrix.toEuclideanLin R) w\\n      (Matrix.toEuclideanLin R z)\\n    rw [hadjoint] at h\\n    rw [← hRR, applyOperatorToState_mul]\\n    exact h\\n  have hnorm : ∀ w : EuclideanSpace ℂ ι,\\n      ‖applyOperatorToState R w‖ =\\n        Real.sqrt (inner ℂ w (applyOperatorToState A w)).re := by\\n    intro w\\n    have h2 : ‖applyOperatorToState R w‖ ^ 2 =\\n        (inner ℂ (applyOperatorToState R w) (applyOperatorToState R w)).re := by\\n      rw [@norm_sq_eq_re_inner ℂ]\\n      rfl\\n    rw [hsplit, ← h2, Real.sqrt_sq (norm_nonneg _)]\\n  rw [hsplit, ← hnorm, ← hnorm]\\n  exact norm_inner_le_norm _ _\\n\\n/-- The sum over outcomes of the real parts of `⟨u a, A a (v a)⟩`, for\\npositive weights `A a`, is bounded by the product of the square roots of the\\ntwo diagonal sums. -/\\ntheorem abs_sum_re_inner_le_sqrt_mul_sqrt {α ι : Type*} [Fintype α]\\n    [Fintype ι] [DecidableEq ι] (A : α → Op ι) (hA : ∀ a, 0 ≤ A a)\\n    (u v : α → EuclideanSpace ℂ ι) :\\n    |∑ a, (inner ℂ (u a) (applyOperatorToState (A a) (v a))).re| ≤\\n      Real.sqrt (∑ a, (inner ℂ (u a) (applyOperatorToState (A a) (u a))).re) *\\n        Real.sqrt (∑ a, (inner ℂ (v a) (applyOperatorToState (A a) (v a))).re) := by\\n  have hu : ∀ a, 0 ≤ (inner ℂ (u a) (applyOperatorToState (A a) (u a))).re :=\\n\",\"exit_code\":0,\"status\":\"completed\"}}\nresults/telemetry/sessions/reviewer-pr400-20260909-01.jsonl:71:{\"type\":\"item.completed\",\"item\":{\"id\":\"item_35\",\"type\":\"command_execution\",\"command\":\"/bin/bash -lc \\\"awk '/\\\"'^diff --git/ {file=$4; sub(/''^b'\\\"\\\\\\\\//,\\\\\\\"\\\\\\\",file)} /\\\"'^'\\\"\\\\\\\\+[\\\"'^+]/ {s=substr($0,2); if(s ~ /''^'\\\"\\\\\\\\/-/) comment=1; if(comment) print file \\\\\\\": \\\\\\\" s; if(s ~ /-\\\\\\\\//) comment=0}' /home/drx/.cache/mipstarre-dev/reviews/pr400/79caf482f3bb07bf4392bccacf0f2384adf8fb8f/diff.patch\\\"\",\"aggregated_output\":\"MIPStarRE/QPBT/Combining/Claims.lean: /-- Place an Alice-side measurement on `AA'` by the current tensor\\nMIPStarRE/QPBT/Combining/Claims.lean: bipartition API. -/\\nMIPStarRE/QPBT/Combining/Claims.lean: /-- The effects of `placedAAMeasurement` are the `AA'` placements of the\\nMIPStarRE/QPBT/Combining/Claims.lean: original effects. -/\\nMIPStarRE/QPBT/Combining/Claims.lean: /-- A product-distribution average is the corresponding iterated average. -/\\nMIPStarRE/QPBT/Combining/Claims.lean: /-- The completed point measurement has zero effect at `none`. -/\\nMIPStarRE/QPBT/Combining/Claims.lean: /-- The completed point measurement agrees with the original measurement at\\nMIPStarRE/QPBT/Combining/Claims.lean: a `some` outcome. -/\\nMIPStarRE/QPBT/Combining/Claims.lean: /-- Evaluating a completed point effect through a line answer gives the\\nMIPStarRE/QPBT/Combining/Claims.lean: explicit zero-completed effect used in the claim statements. -/\\nMIPStarRE/QPBT/Combining/Claims.lean: /-- Regroup paired-line answers by their two optional evaluations. -/\\nMIPStarRE/QPBT/Combining/Claims.lean: /-- Completing both outcome coordinates with `none` does not change the\\nMIPStarRE/QPBT/Combining/Claims.lean: squared distance sum between the joint and ordered point families. -/\\nMIPStarRE/QPBT/Combining/Claims.lean: /-- On the directly indexed subline law, the real parts of the joint-point\\nMIPStarRE/QPBT/Combining/Claims.lean: and ordered `Z`-then-`X` overlaps differ by at most a square-root point error.\\nMIPStarRE/QPBT/Combining/Claims.lean: This is the auxiliary blueprint `lem:claim-17-1-direct-real`, supporting paper\\nMIPStarRE/QPBT/Combining/Claims.lean: `claim:17-1`, lines 1140--1145 of the cited mirror.\\nMIPStarRE/QPBT/Combining/Claims.lean: **Scope restriction:** The public statement uses `SubLineWitness` and real\\nMIPStarRE/QPBT/Combining/Claims.lean: parts. It does not prove the source distribution transport or the complex\\nMIPStarRE/QPBT/Combining/Claims.lean: modulus bound. These obligations and their discharge plan are recorded in\\nMIPStarRE/QPBT/Combining/Claims.lean: `docs/paper-gaps/qpbt_ld-dimension-divisibility.tex`, section\\nMIPStarRE/QPBT/Combining/Claims.lean: \\\"Scalar estimates on the auxiliary subline law\\\". -/\\nMIPStarRE/QPBT/Combining/Claims.lean: /-- On the directly indexed subline law, the real part of the `Z`-point\\nMIPStarRE/QPBT/Combining/Claims.lean: correlation is close to one with the fourth-root point and line error.\\nMIPStarRE/QPBT/Combining/Claims.lean: This is the auxiliary blueprint `lem:claim-17-3-direct-real`, supporting paper\\nMIPStarRE/QPBT/Combining/Claims.lean: `claim:17-3`, lines 1204--1209 of the cited mirror.\\nMIPStarRE/QPBT/Combining/Claims.lean: **Scope restriction:** This theorem retains the `SubLineWitness` carrier and\\nMIPStarRE/QPBT/Combining/Claims.lean: real-part conclusion. Transport to the source distribution remains open, as\\nMIPStarRE/QPBT/Combining/Claims.lean: recorded in `docs/paper-gaps/qpbt_ld-dimension-divisibility.tex`, section\\nMIPStarRE/QPBT/Combining/Claims.lean: \\\"Scalar estimates on the auxiliary subline law\\\"; the source-labelled claim is\\nMIPStarRE/QPBT/Combining/Claims.lean: not certified by this auxiliary result. -/\\nMIPStarRE/QPBT/Combining/Defs.lean: /-- Formalization-only auxiliary for `def:ith-restricted-line`: whenever a line\\nMIPStarRE/QPBT/Combining/Defs.lean: CL map keeps the shared scalar coordinate, the pre-decoding law it generates\\nMIPStarRE/QPBT/Combining/Defs.lean: against the point map gives positive mass to every coordinate-index event.  The\\nMIPStarRE/QPBT/Combining/Defs.lean: witness is the constant seed reconstructed from the index by\\nMIPStarRE/QPBT/Combining/Defs.lean: `seedOfIndexResidue`. -/\\nMIPStarRE/QPBT/Combining/Lines.lean: /-- Formalization-only auxiliary for item 3 of\\nMIPStarRE/QPBT/Combining/Lines.lean: `lem:restricted-line-mixture-bounds`: a consistency defect of two complete\\nMIPStarRE/QPBT/Combining/Lines.lean: measurements placed on opposite registers inflates by at most `4m^2` when\\nMIPStarRE/QPBT/Combining/Lines.lean: both line-point coordinates are restricted.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines.lean: `lem:restricted-line-mixture-bounds`, paper\\nMIPStarRE/QPBT/Combining/Lines.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1058-1061`. -/\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: /-!\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: # Positivity of the consistency defect on opposite placements\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: The error-inflation estimates for restricted line distributions apply to\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: nonnegative averages.  This module supplies the missing nonnegativity: the\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: integrand of `consistencyDefect` for two complete measurements placed on\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: opposite registers is a state quadratic form of a positive operator.  Indeed,\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: after separating the two placements along the corresponding tensor\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: bipartition, the off-diagonal sum is\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: `∑_a (place p₁ E_a) (place p₂ (∑_{b ≠ a} F_b))`, a sum of products of\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: positive operators supported on complementary registers.\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: ## References\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: The consistency defect is blueprint `def:consistency`, paper\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: `references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:232-248`.  The\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: placements and their bipartitions are blueprint `def:expanded-state`, paper\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:420-450`.  The\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: nonnegativity is the hypothesis of items 1 and 2 of\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: blueprint `lem:restricted-line-mixture-bounds`, paper\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1052-1058`.\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: /-- The state quadratic form of the zero operator vanishes. -/\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: /-- Reindexing an operator along an equivalence preserves positivity.\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: Formalization-only auxiliary for the placement bipartitions of blueprint\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: `def:expanded-state`, paper\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:420-450`. -/\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: /-- A register placement respects finite sums of operators. -/\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: /-- A register placement maps the zero operator to zero. -/\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: /-- Operators placed on `AA'` and `BA''` commute. -/\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: /-- Operators placed on `AB''` and `BB'` commute. -/\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: /-- Positive operators placed on `AA'` and on `BA''` have a positive product.\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: Paper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:420-450`,\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: blueprint `def:expanded-state`. -/\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: /-- Positive operators placed on `AB''` and on `BB'` have a positive product.\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: Paper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:420-450`,\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: blueprint `def:expanded-state`. -/\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: /-- Positive operators placed on a directed opposite pair of registers have a\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: positive product.  Paper\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:420-450`,\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: blueprint `def:expanded-state`. -/\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: /-! ## Nonnegativity of the pointwise consistency defect -/\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: /-- The off-diagonal outcome sum of two complete measurements placed on\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: opposite registers is a positive operator.  Formalization-only auxiliary for\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: blueprint `def:consistency`, paper\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: `references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:232-248`. -/\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: /-- The integrand of the consistency defect of two complete measurements placed\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: on opposite registers is nonnegative.  This is the positivity hypothesis needed\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: by items 1 and 2 of blueprint `lem:restricted-line-mixture-bounds`, paper\\nMIPStarRE/QPBT/Combining/Lines/ConsistencyPositivity.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1052-1058`. -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: /-!\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: # Error inflation of restricted line-point averages\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: This module records how a nonnegative average over the line-point distribution\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: transfers to one restricted component.  The line-point law places weight\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: `1 / 2` on each of its two kinds and, inside each kind, weight `1 / m` on each\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: coordinate index, so every restricted component carries mixture weight\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: `1 / (2 m)` and a nonnegative average inflates by at most `2 m`.\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: ## References\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: The estimates are items 1 and 2 of blueprint\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: `lem:restricted-line-mixture-bounds`, formalizing the unlabelled estimates at\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1052-1058`.\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: /-! ## Averages of the distribution operations -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: /-- Formalization-only auxiliary: an average against a dependent bind is the\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: iterated average.  Blueprint `lem:restricted-line-mixture-bounds`, paper\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1052-1058`. -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: /-- Formalization-only auxiliary: an average against a convex mixture is the\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: convex combination of the two averages.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: `lem:restricted-line-mixture-bounds`, paper\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1052-1058`. -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: /-- Formalization-only auxiliary: an average against a product law is the\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: iterated average.  Blueprint `lem:restricted-line-mixture-bounds`, paper\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1056-1058`. -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: /-- Formalization-only auxiliary: one component of a uniform mixture carries at\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: most the whole nonnegative average, scaled by its mixture weight.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: `lem:restricted-line-mixture-bounds`, paper\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1052-1056`. -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: /-! ## Inflation of a restricted line-point average -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: /-- Restricting a nonnegative line-point average to one kind and one coordinate\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: index inflates it by at most `2 m`.  This is the pointwise form of item 1 of\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: blueprint `lem:restricted-line-mixture-bounds`, paper\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1052-1056`. -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: /-- Restricting a nonnegative average over two independent line-point samples\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: to one kind and coordinate index in each factor inflates it by at most\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: `4 m ^ 2`.  This is the pointwise form of item 2 of\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: blueprint `lem:restricted-line-mixture-bounds`, paper\\nMIPStarRE/QPBT/Combining/Lines/RestrictedAverage.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1056-1058`. -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: /-!\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: # Uniform coordinate-index mixtures of the line-point laws\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: This module proves that the axis-parallel and diagonal line-point laws are the\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: uniform mixtures of their coordinate-index restrictions.  The identity rests on\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: the exact seed decomposition of `chiIndex`: the retained scalar seed is uniform,\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: so each of its `m` coordinate-index fibers carries mass `1 / m`, and every\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: line conditioning map keeps that seed.\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: ## References\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: The mixture assertion is the opening sentence of blueprint\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: `lem:restricted-line-mixture-bounds`, formalizing the unlabelled observation at\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1049-1051`.\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: The restricted laws are blueprint `def:ith-restricted-line`, paper lines\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: 1038--1048.\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: /-! ## Elementary rewriting of finite distributions -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: /-- Formalization-only auxiliary: the mass of a decidable event is the average\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: of its indicator.  Blueprint `lem:restricted-line-mixture-bounds`, paper\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1049-1051`. -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: /-- Formalization-only auxiliary: a push-forward commutes with a dependent\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: bind.  Blueprint `lem:restricted-line-mixture-bounds`, paper\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1049-1051`. -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: /-- Formalization-only auxiliary: a family of normalized restrictions along the\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: fibers of a classifying map recovers the original law when every fiber carries\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: the uniform mass `1 / |ι|`.  This is the mixture step of\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: blueprint `lem:restricted-line-mixture-bounds`, paper\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1049-1051`. -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: /-! ## The uniform coordinate-index law of the retained seed -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: /-- The retained scalar seed of a uniformly sampled low-degree vector is\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: uniform.  This is a public copy of the private\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: `MIPStarRE.QPBT.map_uniformDistribution_seed` in\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: `MIPStarRE/QPBT/Test/LowDegreeGameTheorems.lean`, which belongs to another\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: packet; the duplication is tracked by issue #204.  Formalization-only\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: auxiliary for blueprint `def:ith-restricted-line`, paper\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1038-1048`. -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: /-- The coordinate index of the retained seed of a uniformly sampled low-degree\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: vector is uniform.  Formalization-only auxiliary for blueprint\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: `def:ith-restricted-line`, paper\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1038-1048`. -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: /-! ## The mass of a coordinate-index event -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: /-- Every coordinate-index event of a line conditioning map that keeps the\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: shared scalar coordinate carries mass `1 / m`.  This is the equal-weight\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: statement behind blueprint `lem:restricted-line-mixture-bounds`, paper\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1049-1051`. -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: /-! ## The two source mixture identities -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: /-- The axis-parallel line-point law is the uniform mixture of its\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: coordinate-index restrictions.  This is the axis half of\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: blueprint `lem:restricted-line-mixture-bounds`, paper\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1049-1051`. -/\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: /-- The diagonal line-point law is the uniform mixture of its coordinate-index\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: restrictions.  This is the diagonal half of\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: blueprint `lem:restricted-line-mixture-bounds`, paper\\nMIPStarRE/QPBT/Combining/Lines/RestrictedMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1049-1051`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: /-!\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: # Rewriting rules for dependent mixtures of finite distributions\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: This module records the elementary rewriting rules for the dependent mixture\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: of finite distributions that the sampling procedure of the sub-line lemma\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: uses: a mixture indexed along a push-forward is the mixture indexed along the\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: original law, iterated mixtures associate, a mixture is unchanged when the\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: mixed family is changed only outside the index support, a mixture of a\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: constant family is that constant, a product with a fixed independent factor\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: distributes over a mixture, and an equal two-term mixture is the mixture\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: indexed by a uniform pair of labels.\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: ## References\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: The rewriting rules support `lem:qld-sublines` in\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: blueprint `lem:qld-sublines`, whose source is\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: The mixture, product and equal-mixture operations are those of\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: blueprint `def:line-point-dist`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: /-! ## Reindexing a dependent mixture -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: /-- Mixing along a push-forward index is mixing along the original index.\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: /-- A dependent mixture depends on the mixed family only on the index\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: support.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: /-- A dependent mixture of a constant family is that constant law.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: /-! ## Associativity of dependent mixtures -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: /-- Iterated dependent mixtures associate.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: /-! ## Products with an independent factor -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: /-- A product with a fixed independent second factor distributes over a\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: dependent mixture of the first factor.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: /-! ## The equal two-term mixture as a uniform dependent mixture -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: /-- The equal mixture of two laws is the dependent mixture indexed by a\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: uniform pair of labels.  Blueprint `def:line-point-dist`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:274-287`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineBind.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-!\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: # Independent blocks of the restricted line-point laws\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: This module isolates the independent generating blocks of the restricted\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: line-point laws used by the sampling procedure of the sub-line lemma.  A\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: uniformly sampled low-degree vector splits into a point block and a\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: seed-direction block; the coordinate-index event constrains only the second\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: block, so conditioning on it leaves the point block uniform and independent.\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: The conditioned seed-direction block is the fresh diagonal direction pair of\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: the sub-line construction, and the uniform mixture of those pairs over the\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: coordinate index is the unconditioned law.\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: ## References\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: The generating descriptions support `lem:qld-sublines` in\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: blueprint `lem:qld-sublines`, whose source is\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: The restricted laws themselves are `def:ith-restricted-line`, blueprint lines\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: 1209--1228, paper lines 1038--1048.\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-! ## Uniform laws on products -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-- Formalization-only auxiliary: the uniform law on a product of two finite\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: types is the product of the uniform laws.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-- Formalization-only auxiliary: the mass of an event depending only on the\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: second factor is the same under a uniform product law and under the uniform\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: law of that factor.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-! ## Conditioning one factor of a product -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-- Formalization-only auxiliary: normalized restriction depends on the\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: restricted law only through its support and weights.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-- Restricting a product law to an event depending on the second factor alone\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: leaves the first factor unchanged and independent of the conditioned second\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: factor.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-- Conditioning a uniform product law on an event of its second factor leaves\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: the first factor uniform and independent.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-! ## The block decomposition of an ambient low-degree vector -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-- Split an ambient low-degree vector into its point block and its\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: seed-direction block.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-- The coordinate-index event of `def:ith-restricted-line` read on the\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: seed-direction block of an ambient low-degree vector.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `def:ith-restricted-line`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1038-1048`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-- Decidability of the coordinate-index event on the seed-direction block. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-- Each coordinate-index event of the seed-direction block carries mass\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `1 / m` under the uniform law, because the retained seed is uniform and its\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `m` coordinate-index fibers are equal.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `lem:restricted-line-mixture-bounds`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1049-1051`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-- Every coordinate-index event of the seed-direction block has positive\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: mass.  Blueprint `def:ith-restricted-line`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1038-1048`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-! ## Fresh diagonal direction pairs -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-- The fresh diagonal direction pair at coordinate index `i`: a scalar seed\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: uniform in the fiber of `i` together with a direction block uniform on the\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: whole space.  This is the auxiliary randomness of the sampling procedure of\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-- Every fresh diagonal direction pair law has total mass one. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-- The uniform mixture over the coordinate index of the fresh diagonal\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: direction pairs is the unconditioned uniform seed-direction law.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-! ## Independence of the point block under the coordinate-index event -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-- Conditioning the uniform ambient low-degree law on the coordinate-index\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: event of its seed leaves the point block uniform and independent of the fresh\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: diagonal direction pair carried by the seed-direction block.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-! ## Generating form of the restricted line-point laws -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-- The axis-line decoder read on the block decomposition. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-- The diagonal-line decoder read on the block decomposition. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-- The `i`-th restricted axis-line law is the law of the canonical\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: axis-parallel line through a uniform point block, in the coordinate direction\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: named by an independent fresh diagonal direction pair at index `i`, together\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: with that same point.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: /-- The `i`-th restricted diagonal-line law is the law of the canonical\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: diagonal line through a uniform point block, in the prefix-projected direction\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: of an independent fresh diagonal direction pair at index `i`, together with\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: that same point.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBlocks.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-!\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: # The branch data of the sub-line sampling procedure\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: The sampling procedure of the sub-line lemma draws a line kind, a stored\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: extended coordinate, and an unrestricted extended direction, and forms from\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: them the direction of the extended line: the elementary direction at the\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: stored coordinate in the axis branch, and the extended direction with the\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: coordinates preceding the stored coordinate replaced by zero in the diagonal\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: branch.  The two source lines are then read off the two coordinate blocks.\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: This module fixes the coordinate index that each source line must carry: the\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: stored coordinate itself when it belongs to that block, the first coordinate\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: otherwise.  With that choice the source block of the extended direction always\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: lies in the line spanned by the corresponding source direction, which is the\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: incidence hypothesis of the two projection lemmas.  The module also records\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: that moving an extended point to its canonical representative does not change\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: the canonical representative of either of its source blocks.\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: ## References\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: The statements support `lem:qld-sublines` in\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: blueprint `lem:qld-sublines`, whose source is\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: The coordinate blocks are those of `def:combine-map`, blueprint lines\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: 445--480, paper lines 970--989; the prefix truncation is that of\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: blueprint `def:ld-question-distribution`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-! ## The three ranges of extended coordinates -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- Every extended coordinate is an `X`-block coordinate, a `Z`-block\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: coordinate, or one of the two scalar coordinates.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-! ## Linearity of the identification of the two scalar fields -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- The identification of the two scalar fields is additive on extended\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: points.  Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- The identification of the two scalar fields carries a scalar multiple of\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: an extended point to the multiple by the identified scalar.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-! ## The coordinate index carried by each source line -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- The first coordinate of the source space.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: `eq:chi-func`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:958-961`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- The coordinate index carried by the source `X` line of a branch: the\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: stored extended coordinate when it is an `X`-block coordinate, and the first\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: coordinate otherwise.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- The coordinate index carried by the source `Z` line of a branch: the\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: stored extended coordinate when it is a `Z`-block coordinate, and the first\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: coordinate otherwise.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- At an `X`-block coordinate the source `X` line carries that coordinate. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- At a `Z`-block coordinate the source `X` line carries the first\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: coordinate. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- At the first scalar coordinate the source `X` line carries the first\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: coordinate. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- At the second scalar coordinate the source `X` line carries the first\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: coordinate. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- At an `X`-block coordinate the source `Z` line carries the first\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: coordinate. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- At a `Z`-block coordinate the source `Z` line carries that coordinate. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- At the first scalar coordinate the source `Z` line carries the first\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: coordinate. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- At the second scalar coordinate the source `Z` line carries the first\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: coordinate. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-! ## The two directions of a branch -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- The direction of the extended line of a branch: the elementary direction\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: at the stored coordinate in the axis branch, and the extended direction with\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: the coordinates preceding the stored coordinate replaced by zero in the\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: diagonal branch.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- The direction of a source line of a branch: the elementary direction at\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: its coordinate index in the axis branch, and the given source block with the\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: coordinates preceding that index replaced by zero in the diagonal branch.\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-! ## Incidence of the two source blocks of a branch direction -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- The `X` block of the direction of the extended line of a branch lies in\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: the line spanned by the direction of its source `X` line.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- The `Z` block of the direction of the extended line of a branch lies in\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: the line spanned by the direction of its source `Z` line.  In the diagonal\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: branch at an `X`-block coordinate the `Z` block is untruncated, which is why\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: the source `Z` line carries the first coordinate there.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-! ## Canonical representatives of the two source blocks -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- Replacing an extended point by its canonical representative in the\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: direction of the extended line does not change the canonical representative\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: of its `X` block in the direction of the source `X` line, as soon as the `X`\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: block of the extended direction lies in the line spanned by the source\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: direction.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: /-- Replacing an extended point by its canonical representative in the\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: direction of the extended line does not change the canonical representative\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: of its `Z` block in the direction of the source `Z` line, as soon as the `Z`\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: block of the extended direction lies in the line spanned by the source\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: direction.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineBranch.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-!\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: # The sampling procedure of the sub-line lemma\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: This module carries out the sampling procedure of `lem:qld-sublines`.  A line\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: kind is drawn from the two kinds, an extended coordinate and an extended point\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: and direction are drawn uniformly, and two scalar seeds are drawn\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: independently in the coordinate-index fibers of the two coordinates that the\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: two source lines must carry.  The sampled triple consists of the axis or\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: diagonal line of the extended sample together with the two source lines\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: decoded from the two coordinate blocks of the extended point and direction and\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: from the two seeds.\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: The module records the elementary evaluations of that triple, the description\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: of the support of the resulting law, the three pointwise properties of a\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: sampled triple -- incidence of the two source blocks, compatibility of the\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: affine data, and closure of the axis branch -- and the identification of its\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: extended-line marginal.\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: ## References\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: The construction is the proof of `lem:qld-sublines` in\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: blueprint `lem:qld-sublines`, whose source is\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: The restricted laws are `def:ith-restricted-line`, blueprint lines\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: 1209--1228, paper lines 1038--1048.\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-! ## The auxiliary randomness of one branch -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- An extended point together with an extended direction.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The auxiliary randomness of one branch of the sampling procedure: an\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: extended point, an extended direction, and the two scalar seeds of the two\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: source lines.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The law of the scalar seed carried by a source line at a given coordinate\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: index: uniform on the coordinate-index fiber of that index.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `def:ith-restricted-line`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1038-1048`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- Every seed law of a source line has total mass one. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The auxiliary randomness law of the sampling procedure: the extended\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: coordinate is uniform, the extended point and direction are uniform and\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: independent of it, and the two seeds are independent and uniform on the\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: coordinate-index fibers of the two coordinates carried by the two source\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: lines.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The auxiliary randomness law has total mass one. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-! ## The sampled triple -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The extended line of a branch: the canonical axis or diagonal line of an\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: extended sample.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The extended line of a branch, read off the auxiliary randomness.\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- A source line of a branch: the canonical axis or diagonal line decoded\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: from a point block, a scalar seed and a direction block.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The triple sampled by one branch of the procedure: the extended line\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: together with the two source lines decoded from its two coordinate blocks and\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: from the two scalar seeds.  Blueprint `lem:qld-sublines`,\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: paper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The law of the triples sampled by one branch.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The sub-line law of `lem:qld-sublines`: the equal mixture of the two\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: branches of the sampling procedure.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-! ## Elementary evaluations of the sampled triple -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The extended line of a branch has the kind of that branch. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The direction of the extended line of a branch is the branch direction. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The base of the extended line of a branch is the canonical representative\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: of the drawn point in the branch direction. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- A source line of a branch has the kind of that branch. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The direction of a source line of a branch is the branch source direction\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: at the coordinate index named by its seed. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The base of a source line of a branch is the canonical representative of\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: its point block in its own direction. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-! ## The support of the sub-line law -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- Every triple in the support of the sub-line law is sampled by one branch\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: from auxiliary randomness whose two seeds lie in the coordinate-index fibers\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: of the two coordinates carried by the two source lines.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-! ## Pointwise properties of a sampled triple -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The direction of the source `X` line of a sampled triple is the branch\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: source direction at the coordinate carried by that line. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The direction of the source `Z` line of a sampled triple is the branch\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: source direction at the coordinate carried by that line. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The `X` block of the direction of the extended line of a sampled triple\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: lies in the line spanned by the direction of its source `X` line. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The `Z` block of the direction of the extended line of a sampled triple\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: lies in the line spanned by the direction of its source `Z` line. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The base of the source `X` line of a sampled triple is the canonical\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: representative, in its own direction, of the `X` block of the base of the\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: extended line.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The base of the source `Z` line of a sampled triple is the canonical\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: representative, in its own direction, of the `Z` block of the base of the\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: extended line.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- Every point of the extended line of a sampled triple projects onto both of\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: its source lines.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- Every sampled triple carries affine data sufficient for\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `combineLinePoly_spec`.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- An extended axis line of a sampled triple has axis-parallel source lines.\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-! ## Total mass and extended marginal -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The sub-line law has total mass one. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The index-first decomposition of an extended direct sample, read at the\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: bare extended dimension.  This is the decomposition\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `directLdSpaceIndexEquiv` of `def:ld-question-distribution` with its stored\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: coordinate typed by the bare dimension `2 m + 2`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The extended-line marginal of one branch of the sub-line law is the law of\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: the canonical line of the corresponding kind through a uniformly sampled\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: extended direct sample.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: /-- The extended-line marginal of the sub-line law is the extended-line\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: marginal of the directly indexed line-point law.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineConstruct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-!\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: # Coordinate blocks of an extended point and of an extended direct sample\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: This module records the block decomposition used by the sampling procedure of\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: the sub-line lemma on the extended dimension.  A point of the extended space\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: is the tuple consisting of its two source point blocks and its two scalar\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: coordinates, and this decomposition is a bijection carrying the uniform law to\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: the uniform law; in particular the two source blocks of a uniform extended\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: point are independent and uniform.  The decomposition is linear, so it\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: commutes with the affine parameterization of a line, and it commutes with the\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: canonical identification of the extended scalar field with the source scalar\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: field.  The stored coordinate index of an extended direct sample splits along\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: the same three coordinate ranges.\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: ## References\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: The decompositions support `lem:qld-sublines` in\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: blueprint `lem:qld-sublines`, whose source is\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: The coordinate blocks are those of `def:combine-map`, blueprint lines\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: 445--480, paper lines 970--989.\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-! ## Linearity of the coordinate blocks -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-- The `X` block of a sum of extended points is the sum of the blocks.\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-- The `Z` block of a sum of extended points is the sum of the blocks.\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-- The `X` block of a scalar multiple of an extended point is the scalar\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: multiple of the block.  Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-- The `Z` block of a scalar multiple of an extended point is the scalar\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: multiple of the block.  Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-! ## The coordinate blocks of an extended point -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-- Split an extended point into its two source point blocks and its two\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: scalar coordinates.  Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-- The first block of the decomposition is the `X` block. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-- The second block of the decomposition is the `Z` block. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-- The first scalar coordinate of the decomposition is `alpha`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-- The second scalar coordinate of the decomposition is `beta`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-- The block decomposition of an extended point carries the uniform law to\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: the uniform law.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-- The two source blocks of a uniformly sampled extended point are\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: independent and uniform.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-! ## Transport to the source scalar field -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-- The `X` block of an extended point transported to the source scalar field\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: is the transport of its `X` block.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-- The `Z` block of an extended point transported to the source scalar field\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: is the transport of its `Z` block.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-! ## The blocks of an extended direct sample -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-- The stored index, point block and direction block of a uniformly sampled\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: direct low-degree vector are independent and uniform.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-! ## Compatibility data read off the coordinate blocks -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-- An extended line is compatible with two source lines as soon as each of\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: its two point blocks is an affine reparameterization of the corresponding\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: source line: the base block is a point of the source line and the direction\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: block is a multiple of the source direction.  The two scalar coordinates of\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: the compatibility data are the `alpha` and `beta` coordinates of the extended\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: base and direction.  This supplies the domain condition preceding Equation\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: `eq:combine-lines` in blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: /-- An extended line whose two source lines carry the inherited direction\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: blocks is compatible with them, with both affine reparameterizations the\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: identity.  Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineExtended.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: /-!\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: # The projected mixtures of the sub-line law\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: This module assembles the two projected point marginals of the sub-line law of\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `lem:qld-sublines` into mixtures of the restricted product laws.  Drawing a\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: uniform point of the extended line of a mixture of line laws is the same\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: mixture of the corresponding uniform-point laws, so the two projected\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: marginals of the sub-line law are the mixtures, over the drawn kind and the\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: drawn extended coordinate, of the projected marginals of one branch at one\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: extended coordinate.  Each of those is the component law of the pair of\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: indices carried by that branch, so the mixing law is the law of the kind\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: together with the pair of indices assigned to a uniform extended coordinate.\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: ## References\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: The assembly is the last step of the proof of `lem:qld-sublines` in\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: blueprint `lem:qld-sublines`, whose source is\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: The restricted laws are `def:ith-restricted-line`, blueprint lines\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: 1209--1228, paper lines 1038--1048.\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: /-! ## The uniform point of a mixture of line laws -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: /-- Drawing a uniform point of the extended line of a mixture of line-triple\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: laws is the corresponding mixture of the uniform-point laws.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: /-! ## The projected marginals of one branch at one extended coordinate -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: /-- One branch of the sampling procedure, read at a fixed extended coordinate,\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: is the law of the triple decoded from the auxiliary randomness of that\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: coordinate.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: /-- The `X` marginal of a uniform point of the extended line of one branch at\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: one extended coordinate is the `X` component law of the pair of indices of\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: that branch.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: /-- The `Z` marginal of a uniform point of the extended line of one branch at\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: one extended coordinate is the `Z` component law of the pair of indices of\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: that branch.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: /-! ## The mixing law of the two indices -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: /-- The law of the kind and the pair of source indices assigned to a uniform\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: extended coordinate of one branch.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: /-- The mixing law of the sub-line lemma: the equal mixture over the two kinds\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: of the law of the pair of source indices of a uniform extended coordinate.\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: /-- The mixing law has total mass one. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: /-! ## The two projected marginals of one branch -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: /-- The `X` marginal of a uniform point of the extended line of one branch is\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: the mixture, along the pair of source indices of a uniform extended\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: coordinate, of the `X` component laws.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: /-- The `Z` marginal of a uniform point of the extended line of one branch is\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: the mixture, along the pair of source indices of a uniform extended\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: coordinate, of the `Z` component laws.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: /-! ## The two projected marginals of the sub-line law -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: /-- The `X` point marginal of the sub-line law is the mixture of the `X`\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: component laws along the mixing law.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: /-- The `Z` point marginal of the sub-line law is the mixture of the `Z`\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: component laws along the mixing law.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: /-- The two one-point projected marginals of the sub-line law are mixtures of\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: the restricted product laws along one common mixing law.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineMixture.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: /-!\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: # Coordinate blocks of a truncated extended direction\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: This module computes the two source blocks of the direction of an extended\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: diagonal line.  That direction is obtained from an unrestricted extended\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: vector by zeroing the coordinates that precede the stored coordinate index,\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: so each source block is again a prefix truncation: when the stored index is\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: the `i`-th coordinate of a block, that block inherits the truncation at `i`,\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: preceding blocks vanish, and later blocks remain untruncated.\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: The computation is recorded after transport to the source scalar field, since\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: the extended direction and the source line directions are presented over the\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: two identified scalar fields.\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: ## References\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: The block computations support `lem:qld-sublines` in\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: blueprint `lem:qld-sublines`, whose source is\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`.\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: The truncation is the prefix restriction of blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: `def:ld-question-distribution`; the coordinate blocks are those of\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: blueprint `def:combine-map`.\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: /-! ## Truncation at the first coordinate -/\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: /-- Zeroing the coordinates preceding the first coordinate changes nothing.\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: Blueprint `def:ld-question-distribution`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`.\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: /-! ## The `X` block of a truncated extended direction -/\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: /-- The `X` block of an extended direction truncated at an `X`-block\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: coordinate is the `X` block truncated at that coordinate of the source space.\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: /-- The `X` block of an extended direction truncated at a `Z`-block\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: coordinate vanishes.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: /-- The `X` block of an extended direction truncated at the first scalar\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: coordinate vanishes.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: /-- The `X` block of an extended direction truncated at the second scalar\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: coordinate vanishes.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: /-! ## The `Z` block of a truncated extended direction -/\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: /-- The `Z` block of an extended direction truncated at a `Z`-block\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: coordinate is the `Z` block truncated at that coordinate of the source space.\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: /-- The `Z` block of an extended direction truncated at an `X`-block\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: coordinate is the untruncated `Z` block, since every `Z`-block coordinate\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: follows every `X`-block coordinate.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: /-- The `Z` block of an extended direction truncated at the first scalar\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: coordinate vanishes.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: /-- The `Z` block of an extended direction truncated at the second scalar\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: coordinate vanishes.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLinePrefix.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: /-!\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: # Products and push-forwards of finite distributions\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: The sampling procedure of the sub-line lemma presents one law both as an\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: independent product of its generating blocks and as a dependent mixture over\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: one of those blocks.  This module records the three rewriting rules that pass\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: between the two presentations: a push-forward of the first factor of a product\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: is a push-forward of the product, a product with a probability law in the\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: second factor has the first factor as its marginal, and a push-forward of a\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: product is the dependent mixture of the push-forwards of its second factor.\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: ## References\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: The rewriting rules support `lem:qld-sublines` in\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: blueprint `lem:qld-sublines`, whose source is\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: The product and mixture operations are those of blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: `def:line-point-dist`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: /-! ## Nonemptiness of the support of a probability law -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: /-- A law of total mass one has a nonempty support.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: /-! ## Push-forward of one factor of a product -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: /-- Pushing the first factor of a product forward is pushing the product\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: forward along the map acting on that factor alone.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: /-! ## The first marginal of a product -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: /-- The first marginal of a product whose second factor is a probability law\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: is the first factor.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: /-- Reading a function of the first factor of a product whose second factor is\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: a probability law is reading it on the first factor.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: /-! ## A product as a dependent mixture -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: /-- A push-forward of a product is the dependent mixture, over the first\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: factor, of the push-forwards of the second factor.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineProduct.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: /-!\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: # The two independent blocks of a fresh diagonal direction pair\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: This module splits the fresh diagonal direction pair of the sub-line sampling\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: procedure into its two independent blocks.  The coordinate-index event\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: constrains only the scalar seed of the pair, so conditioning on it leaves the\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: direction block uniform and independent of the conditioned seed.  The\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: direction block of a fresh pair is therefore available as an unconstrained\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: uniform vector, which is what allows the sampling procedure to read it off the\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: corresponding block of the direction of the sampled extended line.\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: ## References\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: The block decomposition supports `lem:qld-sublines` in\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: blueprint `lem:qld-sublines`, whose source is\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: The coordinate-index event is that of `def:ith-restricted-line`, blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: lines 1209--1228, paper lines 1038--1048.\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: /-! ## Conditioning the first factor of a product -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: /-- Restricting a product law to an event depending on the first factor alone\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: leaves the second factor unchanged and independent of the conditioned first\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: factor.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: /-- Formalization-only auxiliary: the mass of an event depending only on the\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: first factor is the same under a uniform product law and under the uniform\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: law of that factor.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: /-- Conditioning a uniform product law on an event of its first factor leaves\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: the second factor uniform and independent.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: /-! ## The coordinate-index event on a scalar seed -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: /-- The coordinate-index event of `def:ith-restricted-line` read on a scalar\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: seed alone.  Blueprint `def:ith-restricted-line`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1038-1048`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: /-- Decidability of the coordinate-index event on a scalar seed. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: /-- Every coordinate-index event of a scalar seed has positive mass under the\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: uniform law.  Blueprint `def:ith-restricted-line`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1038-1048`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: /-! ## The blocks of a fresh diagonal direction pair -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: /-- A fresh diagonal direction pair at coordinate index `i` is a scalar seed\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: conditioned on the coordinate-index fiber of `i` together with an independent\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: uniform direction block.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: /-- The direction block of a fresh diagonal direction pair is uniform.\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSeed.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: /-!\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: # Reshuffling products of finitely supported laws\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: The sampling procedure of the sub-line lemma produces its six independent\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: generating blocks in one grouping, while the restricted line-point laws that\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: the projected marginals must match present the same six blocks in another\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: grouping.  This module records the rewriting rules that pass between two such\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: presentations: the support and the weight of a product, the fact that a\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: push-forward along a bijection is determined by the supports and weights it\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: compares, and the push-forward of the second factor of a product.\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: ## References\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: The rewriting rules support `lem:qld-sublines` in\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: blueprint `lem:qld-sublines`, whose source is\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: The product operation is that of blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: `def:line-point-dist`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: /-! ## The support and the weight of a product -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: /-- The support of a product law is the product of the supports.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: `def:line-point-dist`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:274-287`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: /-- The weight of a product law is the product of the weights.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: `def:line-point-dist`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:274-287`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: /-! ## Push-forward along a bijection -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: /-- A push-forward along a bijection is identified by the supports and the\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: weights it compares: if the map matches the two supports and carries each\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: weight to the corresponding weight, and if it has a two-sided inverse, the\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: push-forward is the target law.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: /-! ## Push-forward of the second factor of a product -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: /-- Pushing the second factor of a product forward is pushing the product\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: forward along the map acting on that factor alone.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineShuffle.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: /-!\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: # The projected marginals of the sub-line law\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: This module identifies the two projected point marginals of the sub-line law\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: of `lem:qld-sublines` as mixtures of the restricted product laws.  The two\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: source lines of a sampled triple depend on the drawn extended point only\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: through the canonical representatives of its two source blocks, and those\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: representatives are unchanged when the drawn point is replaced by any point of\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: the extended line; a uniform point of the extended line through a uniform\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: point is a uniform point, so the drawn point may be replaced throughout by the\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: point that is finally retained.  The six generating blocks of the resulting\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: law -- the two source point blocks, the two scalar seeds and the two source\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: direction blocks -- are then regrouped into the two restricted product laws\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: carried by the two indices of the branch.\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: ## References\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: The identification is the last step of the proof of `lem:qld-sublines` in\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: blueprint `lem:qld-sublines`, whose source is\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: The restricted laws are `def:ith-restricted-line`, blueprint lines\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: 1209--1228, paper lines 1038--1048.\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: /-! ## Source lines depend on the point block only through its representative -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: /-- Two source lines of the same branch with the same seed and the same source\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: direction block agree as soon as their point blocks have the same canonical\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: representative in the direction of that line.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: /-- Replacing the drawn extended point by a point of the extended line does\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: not change the canonical representative of its `X` block in the direction of\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: the source `X` line of the branch.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: /-- Replacing the drawn extended point by a point of the extended line does\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: not change the canonical representative of its `Z` block in the direction of\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: the source `Z` line of the branch.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: /-! ## Generating form of the restricted product components -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: /-- The restricted line-point law of a kind at an index is the law of the\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: source line of that kind decoded from a uniform point block, a scalar seed in\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: the coordinate-index fiber of the index and a uniform direction block,\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: together with that same point block.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: /-- The `X` component law of a pair of indices is the law of the two source\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: lines decoded from two independent restricted blocks, together with the point\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: block of the first.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: /-- The `Z` component law of a pair of indices is the law of the two source\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: lines decoded from two independent restricted blocks, together with the point\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: block of the second.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: /-! ## The joint projected marginal of one branch at one extended coordinate -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: /-- At a fixed line kind and a fixed extended coordinate, the joint law of the\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: two source lines of a sampled triple together with the two source blocks of a\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: uniform point of its extended line is the law of the two source lines decoded\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: from two independent restricted blocks together with their two point blocks.\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: /-! ## The two one-point projected marginals of one branch -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: /-- At a fixed line kind and a fixed extended coordinate, the joint law of the\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: two source lines of a sampled triple together with the source `X` block of a\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: uniform point of its extended line is the `X` component law of the two indices\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: of that branch.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: /-- At a fixed line kind and a fixed extended coordinate, the joint law of the\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: two source lines of a sampled triple together with the source `Z` block of a\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: uniform point of its extended line is the `Z` component law of the two indices\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: of that branch.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSource.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: /-!\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: # Generating laws of the restricted line-point distributions\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: This module rewrites the two restricted line-point laws of\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: `def:ith-restricted-line` as push-forwards of a single uniformly sampled\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: low-degree vector conditioned on the coordinate-index fiber of its retained\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: scalar seed.  In that form the point block, the seed and the direction block\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: of the sampled vector are visibly the independent generating data of the\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: restricted law, which is the description used by the sampling procedure of the\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: sub-line lemma: there the projected pairs are built either from a direction\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: block inherited from the extended line or from freshly sampled data, and each\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: is asserted to follow a restricted law.\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: ## References\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: The generating descriptions support `lem:qld-sublines` in\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: blueprint `lem:qld-sublines`, whose source is\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: The restricted laws themselves are `def:ith-restricted-line`, blueprint lines\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: 1209--1228, paper lines 1038--1048.\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: /-! ## Restriction of a push-forward -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: /-- Formalization-only auxiliary: restricting a push-forward distribution to a\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: decidable event is the push-forward of the restriction to the pre-image of\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: that event.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: /-! ## The coordinate-index event on a single uniform vector -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: /-- The coordinate-index event of `def:ith-restricted-line` read on the single\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: uniformly sampled low-degree vector that generates the line-point laws.\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: Blueprint `def:ith-restricted-line`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1038-1048`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: /-- Decidability of the coordinate-index event. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: /-- The coordinate-index event has positive mass under the uniform law on\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: low-degree vectors, so the conditioning below is normalized.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: `def:ith-restricted-line`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1038-1048`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: /-! ## Canonical representatives are unchanged by the conditioning maps -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: /-- Two axis-line descriptions with the same seed and the same base agree:\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: the stored proof of `def:line-representative` invariance is a proposition and\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: carries no further data.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: /-- Two diagonal-line descriptions with the same seed, the same base and the\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: same direction agree: the stored proofs of `def:line-representative`\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: invariance and of the prefix-zero condition are propositions and carry no\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: further data.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: /-- The axis-line decoder is unchanged by the axis conditioning map: the\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: canonical representative of `def:line-representative` is idempotent, so\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: decoding the conditioned vector and decoding the original vector agree.\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: /-- The diagonal-line decoder is unchanged by the diagonal conditioning map:\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: the prefix projection and the canonical representative of\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: `def:line-representative` are both idempotent.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: /-! ## Generating laws of the restricted line-point distributions -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: /-- The `i`-th restricted axis-line law is the law of the pair consisting of\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: the canonical axis-parallel line through a low-degree vector and its point\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: block, when that vector is uniform conditioned on the coordinate-index fiber\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: of its seed.  This is the generating description used in the sampling\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: procedure of blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: /-- The `i`-th restricted diagonal-line law is the law of the pair consisting\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: of the canonical diagonal line through a low-degree vector and its point\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: block, when that vector is uniform conditioned on the coordinate-index fiber\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: of its seed.  This is the generating description used in the sampling\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: procedure of blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineSupport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: /-!\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: # Uniformity under the identification of the two scalar fields\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: The extended line of the sub-line construction lives over the scalar field of\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: the directly indexed extended game, while the two source lines live over the\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: scalar field of the Pauli basis test.  The two fields are identified\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: coordinatewise by a field isomorphism, so that identification is a bijection\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: of the coordinate spaces and therefore carries uniform laws to uniform laws.\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: This module records that transport for a whole extended point and for the two\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: source blocks of an extended point, and it records the resampling rule that\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: reading a function at the point of a uniformly random affine parameter on the\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: line through the canonical representative of a uniformly random point is the\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: same as reading that function at a uniformly random point.\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: ## References\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: The statements support `lem:qld-sublines` in\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: blueprint `lem:qld-sublines`, whose source is\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: The coordinate blocks are those of `def:combine-map`, blueprint lines\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: 445--480, paper lines 970--989.\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: /-! ## The identification of the two scalar fields as a bijection -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: /-- The coordinatewise identification of the extended scalar field with the\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: source scalar field on one source block, presented as a bijection.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: /-- The coordinatewise identification of the extended scalar field with the\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: source scalar field on a whole extended point, presented as a bijection.\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: /-- The `X` block of a transported extended point is the transport of its `X`\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: block.  Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: /-- The `Z` block of a transported extended point is the transport of its `Z`\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: block.  Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: /-! ## Transport of the uniform laws -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: /-- A uniformly random extended point transported to the source scalar field\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: is uniformly random.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: /-- A uniformly random source block transported to the source scalar field is\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: uniformly random.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: /-- The two source blocks of a uniformly random extended point, read in the\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: source scalar field, are independent and uniformly random.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: /-! ## Resampling a uniform point along a line -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: /-- Reading a function at the point of a uniformly random affine parameter on\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: the line through the canonical representative, in a fixed direction, of a\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: uniformly random point is the same as reading that function at a uniformly\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: random point.  Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineTransport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-!\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: # Uniform points of a line and the blocks of a coordinate direction\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: This module records the two elementary geometric inputs of the sampling\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: procedure of the sub-line lemma. First, for independent uniform inputs `y` in\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: the ambient coordinate space and `t` in the scalar field, the point\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `lineRepMap v y + t • v` is uniform. This map on ambient-point--parameter pairs\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: has fibers of size `q`: for nonzero `v`, `y` varies over a coset of the span of\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `v`, while its canonical representative and `t` are fixed; for zero `v`, `y`\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: is fixed and `t` is free. Second, the two coordinate\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: blocks of an elementary coordinate direction of the extended space are the\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: corresponding elementary direction of the source space in the block that\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: carries the coordinate, and zero in the other block and at the two scalar\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: coordinates.\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: ## References\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: The two statements support `lem:qld-sublines` in\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: blueprint `lem:qld-sublines`, whose source is\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: The canonical representative map is blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `def:line-representative`; the coordinate blocks are those of\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: blueprint `def:combine-map`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-! ## The canonical representative for the zero direction -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- For the zero direction the canonical representative map of\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `def:line-representative` is the identity, since the span of the zero vector\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: is trivial.  Blueprint `def:line-representative`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:143-174`.\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-! ## Uniform points of a line -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- The point at a uniformly random affine parameter on the line through the\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: canonical representative of a uniformly random point is uniformly random on\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: the whole coordinate space.  Every fiber of the parameterization has exactly\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `q` elements in the ambient-point--parameter domain: for a nonzero direction\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: the parameter and canonical representative are determined, while the input\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: point varies over a coset of the span of the direction. For the zero direction\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: the input point is fixed and the parameter is free. Blueprint `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-! ## Injectivity of the two block embeddings -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- The `X`-block coordinate embedding of `def:combine-map` is injective.\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- The `Z`-block coordinate embedding of `def:combine-map` is injective.\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-! ## The blocks of an elementary coordinate direction -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- The `X` block of the elementary direction at an `X`-block coordinate is\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: the elementary direction of the source space at that coordinate.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- The `X` block of the elementary direction at a `Z`-block coordinate\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: vanishes.  Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- The `X` block of the elementary direction at the first scalar coordinate\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: vanishes.  Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- The `X` block of the elementary direction at the second scalar coordinate\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: vanishes.  Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- The `Z` block of the elementary direction at a `Z`-block coordinate is\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: the elementary direction of the source space at that coordinate.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- The `Z` block of the elementary direction at an `X`-block coordinate\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: vanishes.  Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- The `Z` block of the elementary direction at the first scalar coordinate\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: vanishes.  Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- The `Z` block of the elementary direction at the second scalar coordinate\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: vanishes.  Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-! ## The coordinates occupied by the two blocks -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- The `i`-th `X`-block coordinate of the extended space is its `i`-th\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: coordinate.  Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- The `i`-th `Z`-block coordinate of the extended space is its `(m + i)`-th\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: coordinate.  Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- The extended coordinate carrying the first scalar is the coordinate\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `2 m`.  Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- The extended coordinate carrying the second scalar is the coordinate\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `2 m + 1`.  Blueprint `def:combine-map`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:970-989`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-! ## The blocks of a point of an extended line -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- Transporting the extended scalar field to the source scalar field carries\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: a point of a line to a point of the transported line, since the transport is\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: a coordinatewise field isomorphism.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- The `X` block of a point of a line lies on the source line through the\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: canonical representative of the `X` block of the base, as soon as the `X`\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: block of the direction is a multiple of the source direction.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- The `Z` block of a point of a line lies on the source line through the\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: canonical representative of the `Z` block of the base, as soon as the `Z`\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: block of the direction is a multiple of the source direction.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-! ## Incidence of the blocks of an extended line -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- The identification of the extended scalar field with the source scalar\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: field carries an elementary coordinate direction to the elementary coordinate\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: direction at the same coordinate.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- Incidence of the `X` blocks: if a source line has as base the canonical\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: representative, in its own direction, of the `X` block of the base of an\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: extended line, and if the `X` block of the direction of the extended line\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: lies in the span of the source direction, then the `X` block of every point\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: of the extended line is a point of the source line.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: /-- Incidence of the `Z` blocks: if a source line has as base the canonical\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: representative, in its own direction, of the `Z` block of the base of an\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: extended line, and if the `Z` block of the direction of the extended line\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: lies in the span of the source direction, then the `Z` block of every point\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: of the extended line is a point of the source line.  Blueprint\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `lem:qld-sublines`, paper\\nMIPStarRE/QPBT/Combining/Lines/SubLineUniform.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1063-1116`. -/\\nMIPStarRE/QPBT/Combining/OrderedPoints.lean: /-!\\nMIPStarRE/QPBT/Combining/OrderedPoints.lean: # The ordered point product on a single placement\\nMIPStarRE/QPBT/Combining/OrderedPoints.lean: The consistency guarantees carried by the joint point measurement compare it\\nMIPStarRE/QPBT/Combining/OrderedPoints.lean: with the ordered `Z`-then-`X` product across a pair of opposite placements.\\nMIPStarRE/QPBT/Combining/OrderedPoints.lean: The scalar estimates used to combine the two Pauli bases instead need the two\\nMIPStarRE/QPBT/Combining/OrderedPoints.lean: families on one placement.  This module obtains that form by inserting the\\nMIPStarRE/QPBT/Combining/OrderedPoints.lean: joint measurement on the opposite placement and applying the squared-distance\\nMIPStarRE/QPBT/Combining/OrderedPoints.lean: triangle inequality twice.\\nMIPStarRE/QPBT/Combining/OrderedPoints.lean: ## References\\nMIPStarRE/QPBT/Combining/OrderedPoints.lean: The statement is `lem:qld-4-10-same-placement` in\\nMIPStarRE/QPBT/Combining/OrderedPoints.lean: `blueprint/src/chapter/ch15_qpbt_combining.tex`; it restates the ordered\\nMIPStarRE/QPBT/Combining/OrderedPoints.lean: `Z`-then-`X` display of `lem:qld-4-10`, paper\\nMIPStarRE/QPBT/Combining/OrderedPoints.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:689-709`.\\nMIPStarRE/QPBT/Combining/OrderedPoints.lean: -/\\nMIPStarRE/QPBT/Combining/OrderedPoints.lean: /-- Every placement has an opposite placement, and the relation is symmetric\\nMIPStarRE/QPBT/Combining/OrderedPoints.lean: between the two members of each pair. -/\\nMIPStarRE/QPBT/Combining/OrderedPoints.lean: /-- On a single placement, the joint point measurement is close to the ordered\\nMIPStarRE/QPBT/Combining/OrderedPoints.lean: `Z`-then-`X` point product, with inflation factor four. -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-!\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: # Replacing one factor of a measurement-weighted overlap\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: The scalar estimates used to combine the two Pauli bases compare averaged\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: overlaps whose left factor is one complete measurement and whose right factors\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: are operator families at small state-dependent distance.  This module records\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: the corresponding Cauchy--Schwarz estimate.  The right-hand families are\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: arbitrary, so the estimate covers an ordered product of point effects, which\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: is not itself a measurement.\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: ## References\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: The estimate is `lem:overlap-gap-distance` in\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: `blueprint/src/chapter/ch15_qpbt_combining.tex`; it is the Cauchy--Schwarz\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: step at paper\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1147-1166`.\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-- Replacing one operator family inside an overlap weighted on the left by a\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: complete measurement changes the average by at most the square root of the\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: state-dependent squared distance between the two families. -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-! ## The Cauchy--Schwarz inequality weighted by a positive operator -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-- For a positive operator `A`, the sesquilinear form `⟨u, A v⟩` satisfies the\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: Cauchy--Schwarz inequality with the two diagonal values `⟨u, A u⟩` and\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: `⟨v, A v⟩`.  This is the inequality behind the Cauchy--Schwarz steps of the\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: proofs of `lem:claim-17-2` and `lem:claim-17-3`, in which both factors carry\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: the square root of the line effect, paper\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1168-1209`. -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-- The sum over outcomes of the real parts of `⟨u a, A a (v a)⟩`, for\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: positive weights `A a`, is bounded by the product of the square roots of the\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: two diagonal sums. -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-- The averaged form of the preceding estimate: the average over a\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: distribution of the outcome sums of `Re ⟨u, A v⟩` is bounded by the product of\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: the square roots of the two averaged diagonal sums. -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-! ## Quadratic forms against projections -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-- The real quadratic form is invariant under the conjugate transpose. -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-- Conjugating an operator transfers the outer operator to the state vector. -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-- For a projection `B` commuting with `A`, the quadratic form of `A` in\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: `B ψ` is the quadratic form of `A B` in `ψ`. -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-- The quadratic form of an operator bounded by the identity is bounded by\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: the squared norm of the vector. -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-- The effects of a complete measurement have total quadratic form one on a\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: unit vector. -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-- Weighting a complete measurement by commuting projections cannot exceed\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: the total mass one. -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-! ## Replacing a factor under the weight of a measurement -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-- Cauchy--Schwarz with the measurement as weight: for projections `B`\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: commuting with the effects of `A`, the averaged overlap of `A` against the\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: product `B C` is bounded by the square roots of the averaged overlap of `A`\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: against `B` and of the averaged quadratic form of `A` in `C ψ`.  This is the\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: Cauchy--Schwarz step of the proofs of `lem:claim-17-2` and `lem:claim-17-3`,\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: paper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1168-1209`. -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-- Deficit form of the Cauchy--Schwarz estimate: for projections `B` and `C`\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: commuting with the effects of `A`, replacing the factor `C B` by `C` inside an\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: overlap weighted by the complete measurement `A` changes the average by at\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: most the square root of the deficit `1 - E Σ_a ⟨A_a B_a⟩`.  This is the\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: estimate used in the proof of `lem:claim-17-2` and, with `C = Id`, in the proof\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: of `lem:claim-17-3`, paper\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1168-1209`. -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-- The deficit form of the Cauchy--Schwarz estimate with the product family\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: `C B` supplied as one family `CB`, which is convenient when the product is\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: formed on a local space before being placed. -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-- Inserting an arbitrary operator family `W` after a projection family `R`\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: commuting with the effects of `A` costs at most the square root of the\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: averaged squared norms of `W ψ`. -/\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: /-- The mirror image of the preceding estimate: an operator family `W`\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: commuting with the effects of `A`, inserted before a commuting projection\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: family `R`, costs at most the square root of the averaged squared norms of\\nMIPStarRE/QPBT/Combining/OverlapGap.lean: `Wᴴ ψ`. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-!\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: # Placement calculus on the expanded state\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: This module records the algebra of the four register placements used by the\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: combining argument: a placement is a unital `*`-homomorphism, placements on\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: opposite register pairs commute, and the crosswise exchange of the two EPR\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: pairs of the expanded state carries the placement `AA'` to `AB''` and `BA''`\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: to `BB'` while fixing the expanded state.  The last fact transfers every\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: state-dependent distance between the two bipartition schemes of\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: `def:symmetric-equivalents` without assuming a symmetric strategy.\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: ## References\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: The placements are those of `def:symmetric-equivalents`, blueprint\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: `blueprint/src/chapter/ch14_qpbt_observables.tex:1003-1030`, paper\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:420-450`.  The\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: EPR-exchange invariance is the element `U_σ U_θ` of\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: `lem:symmetric-equivalents-transfer`, blueprint\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: `blueprint/src/chapter/ch14_qpbt_observables.tex:1032-1130`, which needs no\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: symmetry of the strategy; its use for `lem:qld-4-10` is analyzed in\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: `docs/paper-gaps/qpbt_linearity-theorem-quotation.tex`.\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-! ## Placements as reindexed tensor factors -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- The `AA'` placement is the reindexed left factor of the\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: `AA' | BA''(B'B'')` bipartition. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- The `BA''` placement is the reindexed right factor of the\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: `AA' | BA''(B'B'')` bipartition. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- The `AB''` placement is the reindexed left factor of the\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: `AB'' | BB'(A'A'')` bipartition. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- The `BB'` placement is the reindexed right factor of the\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: `AB'' | BB'(A'A'')` bipartition. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- Reindexing an operator commutes with the conjugate transpose. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- Reindexing an operator along an equivalence preserves positivity. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-! ## The placement is a unital `*`-homomorphism -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- A placement is multiplicative. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- A placement sends the local identity to the identity of the six-register\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: space. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- A placement is additive over finite sums of local operators. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- A placement commutes with the conjugate transpose. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- A placement preserves positivity. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- The placement of a local operator bounded by the identity is bounded by\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: the identity. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- The placement of a projector is a contraction. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- Operators placed on opposite register pairs commute. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- A complete measurement on a local expanded space, placed on one of the\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: four register pairs, is a complete measurement on the six-register space. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- The effects of a placed measurement are the placed effects. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- A placed projective measurement is projective. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- A placement maps the zero operator to zero. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- The completed expanded point measurement agrees with the original effect\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: at a defined outcome. -/\\nMIPStarRE/QPBT/Combining/Points/PlacementSupport.lean: /-- The completed expanded point measurement has zero effect at `none`. -/\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: /-!\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: # Sub-line averages of the Z-point overlap\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: The overlap of the paired-line measurement with the expanded `Z`-point effect\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: depends only on the two source lines and the `Z`-point. The separate Z marginal\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: of the auxiliary `SubLineWitness` law is a mixture of products of restricted\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: line-point laws, with the fresh X point unused. Summing line answers over the\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: evaluation fibers at that fresh point identifies the overlap with the\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: evaluated pair-line overlap, so the Z deficit estimates of\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: `MIPStarRE.QPBT.Combining.ZEvalDeficit` apply component by component.\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: The `_at` estimates and `zPointOverlapAt` retain arbitrary\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: opposite placements. The original overlap definitions and first-player\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: statements are unchanged. Only the separate Z marginal mixture law is used.\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: Transport of the auxiliary extended-line law to the source carrier remains\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: open; see `docs/paper-gaps/qpbt_ld-dimension-divisibility.tex`, section\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: \\\"Scalar estimates on the auxiliary subline law\\\".\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: ## References\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: The statements support the auxiliary `lem:claim-17-3-direct-real`, near\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: the source `lem:claim-17-3` in\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: `blueprint/src/chapter/ch15_qpbt_combining.tex`, paper\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1204-1239`; the\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: mixture is Property~2 of `lem:qld-sublines`.\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: -/\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: /-! ## Regrouping the line answers by their evaluations -/\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: /-- Summing a paired-line answer against a family of point effects that\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: depends on the answer only through its two evaluations is summing the\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: evaluation classes of the paired-line measurement against that family.  This\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: is the fiber regrouping of the proofs of `lem:claim-17-1`, `lem:claim-17-2`,\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: and `lem:claim-17-3` in the blueprint. -/\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: /-- The sub-line average of a function of the two source lines and the\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: `Z`-point of the sampled extended point is a mixture of averages over products\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: of two restricted line-point laws, the `Z`-point being the point of the second\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: factor.  This is the use of Property~2 of `lem:qld-sublines` in the proof of\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: `lem:claim-17-3`, blueprint `blueprint/src/chapter/ch15_qpbt_combining.tex`,\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: paper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1204-1239`. -/\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: /-! ## The two one-point overlaps -/\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: /-- The overlap of the paired-line measurement at two source lines with the\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: expanded `Z`-point effect at a point, summed over the line answers.  This is\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: the integrand of the left-hand side of `lem:claim-17-3`, as a function of the\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: two source lines and the `Z`-point alone. -/\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: /-- The original first-player specialization of the placed overlap. -/\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: /-- At a pair of line-point pairs, the `Z`-point overlap is the overlap of the\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: evaluated pair-line measurement with the completed `Z`-point measurement; the\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: `X`-point of the first pair only labels the evaluation classes. -/\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: /-- The original first-player specialization of the placed estimate. -/\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: /-- The `Z`-point overlap is nonnegative. -/\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: /-- The original first-player specialization of the placed estimate. -/\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: /-- The sub-line average of the `Z`-point overlap is at most one. -/\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: /-- The original first-player specialization of the placed estimate. -/\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: /-- The deficit of the sub-line average of the `Z`-point overlap is bounded by\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: the inflated line and point consistency errors. This is the directly indexed\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: auxiliary deficit estimate supporting `lem:claim-17-3-direct-real`, near\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: the source `lem:claim-17-3`, blueprint\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: `blueprint/src/chapter/ch15_qpbt_combining.tex`, paper\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1204-1239`. -/\\nMIPStarRE/QPBT/Combining/SubLineZDeficit.lean: /-- The original first-player specialization of the placed estimate. -/\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: /-!\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: # A uniform point of the extended space from the directly indexed sub-line law\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: The first scalar estimate in the combining argument samples an extended line\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: from the auxiliary `SubLineWitness` and then a uniform affine parameter on that line.\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: This module records that the resulting extended point is uniform and hence\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: that its two source coordinate blocks are independent uniform points. These\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: identities concern `directLinePointDist`. Transport to the source's seed-indexed\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: carrier remains open, as recorded in\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: `docs/paper-gaps/qpbt_ld-dimension-divisibility.tex`, section\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: \\\"Scalar estimates on the auxiliary subline law\\\".\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: ## References\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: These statements support `lem:claim-17-1` in\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: `blueprint/src/chapter/ch15_qpbt_combining.tex`.  The paper uses this sampling\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: fact at\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1159-1166`.\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: -/\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: /-- A dependent mixture of a constant family is the constant law. -/\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: /-- If every slice of a map of a pair carries the second uniform law to one\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: fixed law, then the map carries the uniform law of the pair to that law. -/\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: /-- Apply the shared uniform-point identity to an ambient point and an\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: independent affine parameter. This preserves the existing public name for the\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: identity supplied by `uniformDistribution_map_lineRepMap_add_smul`. -/\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: /-- Reading a point at a uniform affine parameter on the canonical line of a\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: uniform direct sample gives a uniform point of the direct coordinate space. -/\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: /-- Averaging a function at a uniform affine parameter on the canonical line\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: of a uniform direct sample is averaging it at a uniform point. -/\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: /-- A uniform point on a line drawn from the directly indexed line-point law\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: is uniform in the ambient coordinate space. -/\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: /-- Identify the directly indexed extended coordinates with the combining\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: coordinate split. -/\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: /-- Split an extended point into its two source blocks and two remaining\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: scalar coordinates. -/\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: /-- The two source blocks of a uniform extended point are independent and\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: uniform after the canonical scalar identification. -/\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: /-- Under a sub-line witness, the two source blocks of the point at a uniform\\nMIPStarRE/QPBT/Combining/UniformLinePoint.lean: affine parameter are independent uniform source points. -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-!\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: # Z-point deficits of the evaluated pair-line measurement\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: The proof of `lem:claim-17-3` bounds, after its Cauchy--Schwarz step, the\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: deficit of the overlap between the evaluated pair-line measurement and the\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: expanded `Z`-point measurement at the `Z`-point of the sample.\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: This module derives that deficit from the\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: consistency of the evaluated pair-line measurement with the completed joint\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: point measurement and from the closeness of the joint point measurement to the\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: ordered point products. The derivation inserts the joint point measurement\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: on the point side, replaces it by the ordered product whose trailing factor is\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: the retained point effect, and sums the other factor, at the cost of three\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: square roots. The deficit is first bounded over an arbitrary probability\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: law on pairs of line-point pairs and then over a product of two restricted\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: line-point laws, whose point marginal is the uniform pair.\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: The `_at` variants retain arbitrary opposite placements, including Bob at\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: `BBprime` and Alice at `ABdoubleprime`. The original statements are unchanged\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: specializations; register commutation does not assume symmetry of the state.\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: ## References\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: The Z deficit is the quantity bounded in the proof of `lem:claim-17-3`\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: in `blueprint/src/chapter/ch15_qpbt_combining.tex`, paper\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1204-1239`; the\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: consistency input is `lem:qld-xz-lines` and the ordered products are those of\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: `lem:qld-4-10`.\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-! ## Completed point pairs -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-- A sum over completed outcome pairs of a function vanishing on both `none`\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: classes is the sum over the uncompleted pairs. -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-- The completed joint measurement has the joint effect on a pair of\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: evaluations. -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-- The completed joint measurement vanishes on outcomes outside the image of\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: the completion. -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-- The completion of a projective joint measurement is projective. -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-- A placed projection is a projection. -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-- Every effect of the completed expanded point measurement is a projection,\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: the `none` effect being zero. -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-- The completed joint point measurement and a completed point product differ\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: only on outcome pairs with two evaluations, so their placed state-dependent\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: squared distance is the one of the joint point measurement and the point\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: product.  Blueprint `ch15_qpbt_combining.tex:2651-2698`. -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-- The completed `Z`-then-`X` point product vanishes on both `none` classes\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: and restricts to the ordered product on evaluated pairs. -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-! ## The abstract one-point deficit -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-- Let `A` be a complete measurement, `Q` a projective measurement, `R` a\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: family of projections and `W` a family of operators, all indexed by the same\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: outcomes, with `Q`, `R` and `W` commuting with the effects of `A` and with\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: `W R = W`.  If `A` and `Q` are consistent with defect at most `η` and `Q` is\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: within squared distance `ζ` of `Wᴴ`, then the deficit of the overlap of `A`\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: with `R` is at most `2 √η + 2 √ζ`.  The proof inserts `Q` before `R`, replaces\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: `Q R` by `W R = W`, and compares `W` with `Q`; each of the three steps is a\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: Cauchy--Schwarz estimate weighted by `A`.  This is the common estimate behind\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: the deficits in the proofs of `lem:claim-17-2` and `lem:claim-17-3`, paper\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1168-1239`. -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-! ## The two placed deficits -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-- A pair of line-point pairs of the source space: the sample type of the\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: consistency display of `lem:qld-xz-lines`. -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-- The `Z`-point deficit of the evaluated pair-line measurement over a\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: probability law on pairs of line-point pairs, from the consistency of the\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: evaluated pair-line measurement with the completed joint point measurement\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: and the closeness of the latter to the `Z`-then-`X` product.  This is the\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: deficit bounded in the proof of `lem:claim-17-3`, paper\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1204-1239`. -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-- The original first-player specialization of the opposite-placement estimate. -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-! ## The two deficits over a product of restricted line-point laws -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-- Every restricted line-point law has total mass one. -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-- The point marginal of a restricted line-point law is uniform. -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-- The pair of points of a product of two restricted line-point laws is a\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: uniform pair. -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-- A state-dependent distance between two families depending on the pair of\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: points only, averaged over a product of two restricted line-point laws, is the\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: distance averaged over a uniform pair of points. -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-- The `Z`-point deficit over a product of two restricted line-point laws,\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: with the inflation `4 m ^ 2` of the line consistency error and the inflation\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: `4` of the point consistency error. -/\\nMIPStarRE/QPBT/Combining/ZEvalDeficit.lean: /-- The original first-player specialization of the opposite-placement estimate. -/\\n\",\"exit_code\":0,\"status\":\"completed\"}}\nresults/telemetry/sessions/reviewer-pr400-20260909-01.jsonl:77:{\"type\":\"item.completed\",\"item\":{\"id\":\"item_38\",\"type\":\"command_execution\",\"command\":\"/bin/bash -lc \\\"sed -n '190,327p' MIPStarRE/QPBT/Combining/ZEvalDeficit.lean\\\"\",\"aggregated_output\":\"\\nend ProjectiveSetting\\n\\n/-! ## The abstract one-point deficit -/\\n\\n/-- Let `A` be a complete measurement, `Q` a projective measurement, `R` a\\nfamily of projections and `W` a family of operators, all indexed by the same\\noutcomes, with `Q`, `R` and `W` commuting with the effects of `A` and with\\n`W R = W`.  If `A` and `Q` are consistent with defect at most `η` and `Q` is\\nwithin squared distance `ζ` of `Wᴴ`, then the deficit of the overlap of `A`\\nwith `R` is at most `2 √η + 2 √ζ`.  The proof inserts `Q` before `R`, replaces\\n`Q R` by `W R = W`, and compares `W` with `Q`; each of the three steps is a\\nCauchy--Schwarz estimate weighted by `A`.  This is the common estimate behind\\nthe deficits in the proofs of `lem:claim-17-2` and `lem:claim-17-3`, paper\\n`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1168-1239`. -/\\ntheorem one_sub_overlap_le_of_consistencyDefect {X α ι : Type*}\\n    [Fintype X] [DecidableEq X] [Fintype α] [DecidableEq α]\\n    [Fintype ι] [DecidableEq ι]\\n    (μ : Distribution X) (A Q : X → Measurement α ι) (R W : X → α → Op ι)\\n    (ψ : EuclideanSpace ℂ ι) (hμ : μ.IsProbability) (hψ : ‖ψ‖ = 1)\\n    (hQ : ∀ x, Measurement.IsProjective (Q x)) (hR : ∀ x a, IsProj (R x a))\\n    (hAQ : ∀ x a, Commute ((A x).effect a) ((Q x).effect a))\\n    (hAR : ∀ x a, Commute ((A x).effect a) (R x a))\\n    (hAW : ∀ x a, Commute ((A x).effect a) (W x a))\\n    (hWR : ∀ x a, W x a * R x a = W x a)\\n    (hnonneg : ∀ x a, 0 ≤ stateQForm ψ ((A x).effect a * (Q x).effect a))\\n    (η ζ : ℝ)\\n    (hcons : consistencyDefect μ (fun x a => (A x).effect a)\\n      (fun x a => (Q x).effect a) ψ ≤ η)\\n    (hdist : opFamilyDistSq μ (fun x a => (Q x).effect a)\\n      (fun x a => (W x a)ᴴ) ψ ≤ ζ) :\\n    1 - avgOver μ (fun x => ∑ a, stateQForm ψ ((A x).effect a * R x a)) ≤\\n      2 * Real.sqrt η + 2 * Real.sqrt ζ := by\\n  set ovQ := avgOver μ (fun x =>\\n    ∑ a, stateQForm ψ ((A x).effect a * (Q x).effect a)) with hovQ\\n  have h1 : 1 - ovQ ≤ η := by\\n    rw [← consistencyDefect_eq_one_sub_overlap μ A Q ψ hμ hψ]\\n    exact hcons\\n  have hovQ_nonneg : 0 ≤ ovQ :=\\n    avgOver_nonneg μ _ fun x => Finset.sum_nonneg fun a _ => hnonneg x a\\n  have hovQ_le : ovQ ≤ 1 :=\\n    avgOver_sum_stateQForm_mul_le_one μ A (fun x a => (Q x).effect a) ψ hμ hψ\\n      (fun x a => hQ x a) hAQ\\n  have h1' : 1 - ovQ ≤ Real.sqrt η := by\\n    have h0 : 0 ≤ 1 - ovQ := by linarith\\n    calc 1 - ovQ = Real.sqrt ((1 - ovQ) ^ 2) := (Real.sqrt_sq h0).symm\\n      _ ≤ Real.sqrt η := Real.sqrt_le_sqrt (by nlinarith)\\n  -- comparing `Q` with `W` under the weight `A`\\n  have hWconj : ∀ x a, stateQForm ψ ((A x).effect a * W x a) =\\n      stateQForm ψ ((A x).effect a * (W x a)ᴴ) := by\\n    intro x a\\n    rw [← stateQForm_conjTranspose ψ ((A x).effect a * W x a),\\n      Matrix.conjTranspose_mul, measurement_effect_hermitian]\\n    congr 1\\n    have h := congrArg Matrix.conjTranspose (hAW x a).eq\\n    rw [Matrix.conjTranspose_mul, Matrix.conjTranspose_mul,\\n      measurement_effect_hermitian] at h\\n    exact h\\n  have h2 : |ovQ - avgOver μ (fun x =>\\n      ∑ a, stateQForm ψ ((A x).effect a * W x a))| ≤ Real.sqrt ζ := by\\n    rw [avgOver_congr μ _ _ fun x => Finset.sum_congr rfl fun a _ => hWconj x a]\\n    exact abs_overlap_gap_le_sqrt_of_opFamilyDistSq μ A\\n      (fun x a => (Q x).effect a) (fun x a => (W x a)ᴴ) ψ hμ hψ ζ hdist\\n  -- replacing `Q R` by `W R = W`\\n  have h4 : |avgOver μ (fun x =>\\n      ∑ a, stateQForm ψ ((A x).effect a * ((Q x).effect a * R x a))) -\\n        avgOver μ (fun x => ∑ a, stateQForm ψ ((A x).effect a * W x a))| ≤\\n      Real.sqrt ζ := by\\n    have hpt : ∀ x,\\n        (∑ a, stateQForm ψ ((A x).effect a * ((Q x).effect a * R x a))) -\\n          (∑ a, stateQForm ψ ((A x).effect a * W x a)) =\\n        ∑ a, stateQForm ψ ((A x).effect a * (((Q x).effect a - W x a) * R x a)) := by\\n      intro x\\n      rw [← Finset.sum_sub_distrib]\\n      refine Finset.sum_congr rfl fun a _ => ?_\\n      rw [sub_mul, hWR]\\n      simp [stateQForm, applyOperatorToState, mul_sub]\\n    rw [← avgOver_sub, avgOver_congr μ _ _ hpt]\\n    have hcs := abs_avgOver_sum_stateQForm_mul_le_sqrt_of_isProj' μ A\\n      (fun x a => (Q x).effect a - W x a) R ψ hμ hψ hR hAR\\n      (fun x a => (hAQ x a).sub_right (hAW x a))\\n    refine hcs.trans (Real.sqrt_le_sqrt ?_)\\n    have hdist' : avgOver μ (fun x =>\\n        ∑ a, ‖applyOperatorToState ((Q x).effect a - (W x a)ᴴ) ψ‖ ^ 2) ≤ ζ :=\\n      hdist\\n    refine le_of_eq_of_le ?_ hdist'\\n    refine avgOver_congr μ _ _ fun x => Finset.sum_congr rfl fun a _ => ?_\\n    rw [Matrix.conjTranspose_sub, measurement_effect_hermitian]\\n  -- inserting `Q` before `R`\\n  have h5 : |avgOver μ (fun x =>\\n      ∑ a, stateQForm ψ ((A x).effect a * ((Q x).effect a * R x a))) -\\n        avgOver μ (fun x => ∑ a, stateQForm ψ ((A x).effect a * R x a))| ≤\\n      Real.sqrt η := by\\n    have hpt : ∀ x,\\n        (∑ a, stateQForm ψ ((A x).effect a * R x a)) -\\n          (∑ a, stateQForm ψ ((A x).effect a * ((Q x).effect a * R x a))) =\\n        ∑ a, stateQForm ψ ((A x).effect a * ((1 - (Q x).effect a) * R x a)) := by\\n      intro x\\n      rw [← Finset.sum_sub_distrib]\\n      refine Finset.sum_congr rfl fun a _ => ?_\\n      simp [stateQForm, applyOperatorToState, sub_mul, mul_sub]\\n    rw [abs_sub_comm, ← avgOver_sub, avgOver_congr μ _ _ hpt]\\n    have hcs := abs_avgOver_sum_stateQForm_mul_mul_le_sqrt_mul_sqrt μ A\\n      (fun x a => 1 - (Q x).effect a) R ψ (fun x a => (hQ x a).one_sub)\\n      (fun x a => (Commute.one_right _).sub_right (hAQ x a))\\n    have hfirst : avgOver μ (fun x =>\\n        ∑ a, stateQForm ψ ((A x).effect a * (1 - (Q x).effect a))) = 1 - ovQ := by\\n      have hx : ∀ x,\\n          (∑ a, stateQForm ψ ((A x).effect a * (1 - (Q x).effect a))) =\\n            1 - ∑ a, stateQForm ψ ((A x).effect a * (Q x).effect a) := by\\n        intro x\\n        rw [← sum_stateQForm_effect_eq_one (A x) ψ hψ, ← Finset.sum_sub_distrib]\\n        refine Finset.sum_congr rfl fun a _ => ?_\\n        simp [stateQForm, applyOperatorToState, mul_sub]\\n      rw [avgOver_congr μ _ _ hx, avgOver_sub, avgOver_const_of_isProbability μ hμ]\\n    have hsecond : avgOver μ (fun x =>\\n        ∑ a, stateQForm (applyOperatorToState (R x a)