ta) :\\\\\\\\n   376\\\\\\\\t    seedFiberCompressMeasurement L (M.postprocess f) =\\\\\\\\n   377\\\\\\\\t      (seedFiberCompressMeasurement L M).postprocess f := by\\\\\\\\n   378\\\\\\\\t  letI : Nonempty (Fin (L.q / L.m)) :=\\\\\\\\n   379\\\\\\\\t    Fin.pos_iff_nonempty.mp L.seedFiberCard_pos\\\\\\\\n   380\\\\\\\\t  exact correlatedAncillaCompressMeasurement_postprocess M f\\\\\\\\n   381\\\\\\\\t\\\\\\\\n   382\\\\\\\\t/-- Compress a direct polynomial-tuple POVM from the correlated seed-residue\\\\\\\\n   383\\\\\\\\tcarrier to the corresponding seed-indexed polynomial POVM. -/\\\\\\\\n   384\\\\\\\\tnoncomputable def seedFiberCompressPolyMeasTuple\\\\\\\\n   385\\\\\\\\t    (L : LdParams) {iota : Type*} [Fintype iota] [DecidableEq iota]\\\\\\\\n   386\\\\\\\\t    (G : DirectPolyMeasTuple L.toDirectLdParams\\\\\\\\n   387\\\\\\\\t      (iota × Fin (L.q / L.m))) : PolyMeasTuple L iota := by\\\\\\\\n   388\\\\\\\\t  exact seedFiberCompressMeasurement L G\\\\\\\\n   389\\\\\\\\t\\\\\\\\n   390\\\\\\\\t@[simp] theorem seedFiberCompressPolyMeasTuple_effect\\\\\\\\n   391\\\\\\\\t    (L : LdParams) {iota : Type*} [Fintype iota] [DecidableEq iota]\\\\\\\\n   392\\\\\\\\t    (G : DirectPolyMeasTuple L.toDirectLdParams\\\\\\\\n   393\\\\\\\\t      (iota × Fin (L.q / L.m))) (g : PolyTuple L) :\\\\\\\\n   394\\\\\\\\t    (seedFiberCompressPolyMeasTuple L G).effect g =\\\\\\\\n   395\\\\\\\\t      averageDiagonalBlock (G.effect g) :=\\\\\\\\n   396\\\\\\\\t  rfl\\\\\\\\n   397\\\\\\\\t\\\\\\\\n   398\\\\\\\\t/-- Polynomial evaluation commutes exactly with compression of the correlated\\\\\\\\n   399\\\\\\\\tseed-residue carrier. -/\\\\\\\\n   400\\\\\\\\ttheorem seedFiberCompressPolyMeasTuple_evaluation\\\\\\\\n   401\\\\\\\\t    (L : LdParams) {iota : Type*} [Fintype iota] [DecidableEq iota]\\\\\\\\n   402\\\\\\\\t    (G : DirectPolyMeasTuple L.toDirectLdParams\\\\\\\\n   403\\\\\\\\t      (iota × Fin (L.q / L.m))) (u : Fin L.m → ScalarQ L) :\\\\\\\\n   404\\\\\\\\t    (seedFiberCompressPolyMeasTuple L G).postprocess (evalPolyTupleAt u) =\\\\\\\\n   405\\\\\\\\t      seedFiberCompressMeasurement L\\\\\\\\n   406\\\\\\\\t        (G.postprocess (evalDirectPolyTupleAt u)) := by\\\\\\\\n   407\\\\\\\\t  exact (seedFiberCompressMeasurement_postprocess L G\\\\\\\\n   408\\\\\\\\t    (evalDirectPolyTupleAt u)).symm\\\\\\\\n   409\\\\\\\\t\\\\\\\\n   410\\\\\\\\t/-- Block-diagonal assembly commutes with deterministic outcome\\\\\\\\n   170\\\\\\\\t  letI : Nonempty (S.ιA × S.ιB) :=\\\\\\\\n   171\\\\\\\\t    (strategyQuantumState_isNormalized S).nonempty\\\\\\\\n   172\\\\\\\\t  apply (EuclideanSpace.equiv (S.ιA × S.ιB) ℂ).injective\\\\\\\\n   173\\\\\\\\t  rfl\\\\\\\\n   174\\\\\\\\t\\\\\\\\n   175\\\\\\\\t/-- An LDT consistency relation on the density state associated with a game\\\\\\\\n   176\\\\\\\\tstrategy gives the identical QPBT defect bound on the strategy vector. -/\\\\\\\\n   177\\\\\\\\ttheorem strategyConsRel_consistencyDefect_le\\\\\\\\n   178\\\\\\\\t    {G : Game} (S : Strategy G)\\\\\\\\n   179\\\\\\\\t    {Question Outcome : Type*}\\\\\\\\n   180\\\\\\\\t    [Fintype Question] [DecidableEq Question]\\\\\\\\n   181\\\\\\\\t    [Fintype Outcome] [DecidableEq Outcome]\\\\\\\\n   182\\\\\\\\t    (mu : Distribution Question) (hmu : mu.IsProbability)\\\\\\\\n   183\\\\\\\\t    (A : Question → ProjMeas Outcome S.ιA)\\\\\\\\n   184\\\\\\\\t    (B : Question → ProjMeas Outcome S.ιB) (delta : ℝ)\\\\\\\\n   185\\\\\\\\t    (h : ConsRel (strategyQuantumState S) mu\\\\\\\\n   186\\\\\\\\t      (fun x => (A x).toSubMeas) (fun x => (B x).toSubMeas) delta) :\\\\\\\\n   187\\\\\\\\t    consistencyDefect mu\\\\\\\\n   188\\\\\\\\t      (fun x a => heteroKron ((A x).outcome a) 1)\\\\\\\\n   189\\\\\\\\t      (fun x a => heteroKron 1 ((B x).outcome a)) S.ψ ≤ delta := by\\\\\\\\n   190\\\\\\\\t  letI : Nonempty (S.ιA × S.ιB) :=\\\\\\\\n   191\\\\\\\\t    (strategyQuantumState_isNormalized S).nonempty\\\\\\\\n   192\\\\\\\\t  let pure : PureState (S.ιA × S.ιB) := strategyPureState S\\\\\\\\n   193\\\\\\\\t  have hpure :\\\\\\\\n   194\\\\\\\\t      ConsRel (pure : QuantumState (S.ιA × S.ιB)) mu\\\\\\\\n   195\\\\\\\\t        (fun x => (A x).toSubMeas) (fun x => (B x).toSubMeas) delta := by\\\\\\\\n   196\\\\\\\\t    simpa [pure, strategyQuantumState] using h\\\\\\\\n   197\\\\\\\\t  have hconverted := (consRel_iff_consistencyDefect pure mu hmu A B delta).mp hpure\\\\\\\\n   198\\\\\\\\t  have hv : pureStateEuclideanVector pure = S.ψ := by\\\\\\\\n   199\\\\\\\\t    exact gameStrategyPureState_euclideanVector S\\\\\\\\n   200\\\\\\\\t  rw [hv] at hconverted\\\\\\\\n   201\\\\\\\\t  exact hconverted\\\\\\\\n   202\\\\\\\\t\\\\\\\\n   203\\\\\\\\t@[simp] theorem directPointQuestionOf_directPointEquiv\\\\\\\\n   204\\\\\\\\t    (D : DirectLdParams) (u : Fin D.m → DirectScalarQ D) :\\\\\\\\n   205\\\\\\\\t    directPointQuestionOf D (directPointEquiv D u) =\\\\\\\\n   206\\\\\\\\t      directLdPointQuestionOf D u := by\\\\\\\\n   207\\\\\\\\t  unfold directPointQuestionOf ldtPointToDirect\\\\\\\\n   208\\\\\\\\t  rw [(directPointEquiv D).symm_apply_apply]\\\\\\\\n   209\\\\\\\\t\\\\\\\\n   210\\\\\\\\t/-- LDT points associated with direct parameters have a canonical zero\\\\\\\\n   211\\\\\\\\twitness. -/\\\\\\\\n   212\\\\\\\\tinstance directLdtPointNonempty (D : DirectLdParams) :\\\\\\\\n   213\\\\\\\\t    Nonempty (Point D.toLDTParameters) :=\\\\\\\\n   214\\\\\\\\t  ⟨fun _ => ⟨0, D.toLDTParameters.hq⟩⟩\\\\\\\\n   215\\\\\\\\t\\\\\\\\n   216\\\\\\\\t/-- The LDT scalar readout is the direct coordinate readout followed by\\\\\\\\n   217\\\\\\\\tthe scalar coding equivalence. -/\\\\\\\\n   218\\\\\\\\t@[simp] theorem directPointAnswerReadout_eq\\\\\\\\n   219\\\\\\\\t    (D : DirectLdParams) (r : Fin D.k) (answer : DirectLdAnswer D) :\\\\\\\\n   220\\\\\\\\t    letI := D.toLDTFieldModel\\\\\\\\n   221\\\\\\\\t    directPointAnswerReadout D r answer =\\\\\\\\n   222\\\\\\\\t      directScalarEquiv D (directLdPointValuesOrZero D answer r) := by\\\\\\\\n   223\\\\\\\\t  letI := D.toLDTFieldModel\\\\\\\\n   224\\\\\\\\t  cases answer <;> rfl\\\\\\\\n   225\\\\\\\\t\\\\\\\\n   226\\\\\\\\t/-- At corresponding points and scalar outcomes, the LDT point effect is\\\\\\\\n   227\\\\\\\\tthe effect of the direct point measurement followed by coordinate projection. -/\\\\\\\\n   228\\\\\\\\ttheorem directCoordinatePointMeasurement_effect_transport\\\\\\\\n   229\\\\\\\\t    (D : DirectLdParams) (S : Strategy (directLdGame D))\\\\\\\\n   230\\\\\\\\t    (hS : S.IsProjective) (r : Fin D.k)\\\\\\\\n   231\\\\\\\\t    (u : Fin D.m → DirectScalarQ D) (a : DirectScalarQ D) :\\\\\\\\n   232\\\\\\\\t    letI := D.toLDTFieldModel\\\\\\\\n   233\\\\\\\\t    (((directCoordinateProjStrat D S hS r).pointMeasurementA\\\\\\\\n   234\\\\\\\\t      (directPointEquiv D u)).outcome (directScalarEquiv D a)) =\\\\\\\\n   235\\\\\\\\t      ((S.A (directLdPointQuestionOf D u)).postprocess\\\\\\\\n   236\\\\\\\\t        (fun answer => directLdPointValuesOrZero D answer r)).effect a := by\\\\\\\\n   237\\\\\\\\t  letI := D.toLDTFieldModel\\\\\\\\n   238\\\\\\\\t  classical\\\\\\\\n   239\\\\\\\\t  simp only [directCoordinateProjStrat, directCoordinatePointMeasurement,\\\\\\\\n   240\\\\\\\\t    directLdGame,\\\\\\\\n   241\\\\\\\\t    ProjMeas.postprocess, SubMeas.postprocess_outcome,\\\\\\\\n   242\\\\\\\\t    matrixMeasurementToLDTProjMeas_outcome,\\\\\\\\n   243\\\\\\\\t    directPointQuestionOf_directPointEquiv,\\\\\\\\n   244\\\\\\\\t    MIPStarRE.Quantum.Measurement.postprocess_effect]\\\\\\\\n   245\\\\\\\\t  congr 1\\\\\\\\n   246\\\\\\\\t  ext answer\\\\\\\\n   247\\\\\\\\t  rw [Finset.mem_filter, Finset.mem_filter]\\\\\\\\n   248\\\\\\\\t  simp only [Finset.mem_univ, true_and]\\\\\\\\n   249\\\\\\\\t  simpa only [directPointAnswerReadout_eq] using\\\\\\\\n   250\\\\\\\\t    (directScalarEquiv D).injective.eq_iff\\\\\\\\n   251\\\\\\\\t\\\\\\\\n   252\\\\\\\\t/-- Bob's point effects satisfy the same direct-to-LDT readout identity. -/\\\\\\\\n   253\\\\\\\\ttheorem directCoordinatePointMeasurementB_effect_transport\\\\\\\\n   254\\\\\\\\t    (D : DirectLdParams) (S : Strategy (directLdGame D))\\\\\\\\n   255\\\\\\\\t    (hS : S.IsProjective) (r : Fin D.k)\\\\\\\\n   256\\\\\\\\t    (u : Fin D.m → DirectScalarQ D) (a : DirectScalarQ D) :\\\\\\\\n   257\\\\\\\\t    letI := D.toLDTFieldModel\\\\\\\\n   258\\\\\\\\t    (((directCoordinateProjStrat D S hS r).pointMeasurementB\\\\\\\\n   259\\\\\\\\t      (directPointEquiv D u)).outcome (directScalarEquiv D a)) =\\\\\\\\n   260\\\\\\\\t      ((S.B (directLdPointQuestionOf D u)).postprocess\\\\\\\\n   261\\\\\\\\t        (fun answer => directLdPointValuesOrZero D answer r)).effect a := by\\\\\\\\n   262\\\\\\\\t  letI := D.toLDTFieldModel\\\\\\\\n   263\\\\\\\\t  classical\\\\\\\\n   264\\\\\\\\t  simp only [directCoordinateProjStrat, directCoordinatePointMeasurement,\\\\\\\\n   265\\\\\\\\t    directLdGame,\\\\\\\\n   266\\\\\\\\t    ProjMeas.postprocess, SubMeas.postprocess_outcome,\\\\\\\\n   267\\\\\\\\t    matrixMeasurementToLDTProjMeas_outcome,\\\\\\\\n   268\\\\\\\\t    directPointQuestionOf_directPointEquiv,\\\\\\\\n   269\\\\\\\\t    MIPStarRE.Quantum.Measurement.postprocess_effect]\\\\\\\\n   270\\\\\\\\t  congr 1\\\\\\\\n   271\\\\\\\\t  ext answer\\\\\\\\n   272\\\\\\\\t  rw [Finset.mem_filter, Finset.mem_filter]\\\\\\\\n   273\\\\\\\\t  simp only [Finset.mem_univ, true_and]\\\\\\\\n   274\\\\\\\\t  simpa only [directPointAnswerReadout_eq] using\\\\\\\\n   275\\\\\\\\t    (directScalarEquiv D).injective.eq_iff\\\\\\\\n   276\\\\\\\\t\\\\\\\\n   277\\\\\\\\t/-- Alice's direct point measurement followed by projection to coordinate\\\\\\\\n   278\\\\\\\\t`r`. -/\\\\\\\\n   279\\\\\\\\tnoncomputable def directPointCoordinateMeasurementA\\\\\\\\n   280\\\\\\\\t    (D : DirectLdParams) (S : Strategy (directLdGame D))\\\\\\\\n   281\\\\\\\\t    (r : Fin D.k) (u : Fin D.m → DirectScalarQ D) :\\\\\\\\n   282\\\\\\\\t    MIPStarRE.Quantum.Measurement (DirectScalarQ D) S.ιA :=\\\\\\\\n   283\\\\\\\\t  (S.A (directLdPointQuestionOf D u)).postprocess\\\\\\\\n   284\\\\\\\\t    (fun answer => directLdPointValuesOrZero D answer r)\\\\\\\\n   285\\\\\\\\t\\\\\\\\n   286\\\\\\\\t/-- Bob's direct point measurement followed by projection to coordinate\\\\\\\\n   287\\\\\\\\t`r`. -/\\\\\\\\n   288\\\\\\\\tnoncomputable def directPointCoordinateMeasurementB\\\\\\\\n   289\\\\\\\\t    (D : DirectLdParams) (S : Strategy (directLdGame D))\\\\\\\\n   290\\\\\\\\t    (r : Fin D.k) (u : Fin D.m → DirectScalarQ D) :\\\\\\\\n   291\\\\\\\\t    MIPStarRE.Quantum.Measurement (DirectScalarQ D) S.ιB :=\\\\\\\\n   292\\\\\\\\t  (S.B (directLdPointQuestionOf D u)).postprocess\\\\\\\\n   293\\\\\\\\t    (fun answer => directLdPointValuesOrZero D answer r)\\\\\\\\n   294\\\\\\\\t\\\\\\\\n   295\\\\\\\\t/-- Evaluate a transported LDT polynomial measurement at a direct point. -/\\\\\\\\n   296\\\\\\\\tnoncomputable def directPolynomialEvaluationMeasurement\\\\\\\\n   297\\\\\\\\t    (D : DirectLdParams) :\\\\\\\\n   298\\\\\\\\t    letI := D.toLDTFieldModel\\\\\\\\n   299\\\\\\\\t    {iota : Type*} → [Fintype iota] → [DecidableEq iota] →\\\\\\\\n   300\\\\\\\\t      ProjMeas (MIPStarRE.LDT.Polynomial D.toLDTParameters) iota →\\\\\\\\n   301\\\\\\\\t        (Fin D.m → DirectScalarQ D) →\\\\\\\\n   302\\\\\\\\t          MIPStarRE.Quantum.Measurement (DirectScalarQ D) iota := by\\\\\\\\n   303\\\\\\\\t  letI := D.toLDTFieldModel\\\\\\\\n   304\\\\\\\\t  intro iota _ _ G u\\\\\\\\n   305\\\\\\\\t  exact (directPolynomialMeasurement D G).postprocess\\\\\\\\n   306\\\\\\\\t    (fun g => MvPolynomial.eval u g.1)\\\\\\\\n   307\\\\\\\\t\\\\\\\\n   308\\\\\\\\t/-- Alice's LDT point family obtained from direct coordinate `r`. -/\\\\\\\\n   309\\\\\\\\tnoncomputable def ldtCoordinatePointMeasurementA\\\\\\\\n   310\\\\\\\\t    (D : DirectLdParams) (S : Strategy (directLdGame D))\\\\\\\\n   311\\\\\\\\t    (hS : S.IsProjective) (r : Fin D.k) :\\\\\\\\n   312\\\\\\\\t    letI := D.toLDTFieldModel\\\\\\\\n   313\\\\\\\\t    IdxProjMeas (Point D.toLDTParameters) (Fq D.toLDTParameters) S.ιA := by\\\\\\\\n   314\\\\\\\\t  letI := D.toLDTFieldModel\\\\\\\\n   315\\\\\\\\t  exact (directCoordinateProjStrat D S hS r).pointMeasurementA\\\\\\\\n   316\\\\\\\\t\\\\\\\\n   317\\\\\\\\t/-- Bob's LDT point family obtained from direct coordinate `r`. -/\\\\\\\\n   318\\\\\\\\tnoncomputable def ldtCoordinatePointMeasurementB\\\\\\\\n   319\\\\\\\\t    (D : DirectLdParams) (S : Strategy (directLdGame D))\\\\\\\\n   320\\\\\\\\t    (hS : S.IsProjective) (r : Fin D.k) :\\\\\\\\n   321\\\\\\\\t    letI := D.toLDTFieldModel\\\\\\\\n   322\\\\\\\\t    IdxProjMeas (Point D.toLDTParameters) (Fq D.toLDTParameters) S.ιB := by\\\\\\\\n   323\\\\\\\\t  letI := D.toLDTFieldModel\\\\\\\\n   324\\\\\\\\t  exact (directCoordinateProjStrat D S hS r).pointMeasurementB\\\\\\\\n   325\\\\\\\\t\\\\\\\\n   326\\\\\\\\t/-- The LDT projective evaluation family associated with a global\\\\\\\\n   327\\\\\\\\tpolynomial projective measurement. -/\\\\\\\\n   328\\\\\\\\tnoncomputable def ldtPolynomialEvaluationMeasurement\\\\\\\\n   329\\\\\\\\t    (D : DirectLdParams) :\\\\\\\\n   330\\\\\\\\t    letI := D.toLDTFieldModel\\\\\\\\n   331\\\\\\\\t    {iota : Type*} → [Fintype iota] → [DecidableEq iota] →\\\\\\\\n   332\\\\\\\\t      ProjMeas (MIPStarRE.LDT.Polynomial D.toLDTParameters) iota →\\\\\\\\n   333\\\\\\\\t        IdxProjMeas (Point D.toLDTParameters) (Fq D.toLDTParameters) iota := by\\\\\\\\n   334\\\\\\\\t  letI := D.toLDTFieldModel\\\\\\\\n   335\\\\\\\\t  intro iota _ _ G u\\\\\\\\n   336\\\\\\\\t  exact ProjMeas.postprocess G (fun g => g u)\\\\\\\\n   337\\\\\\\\t\\\\\\\\n   338\\\\\\\\t/-- Left placement of Alice's LDT point family. -/\\\\\\\\n   339\\\\\\\\tnoncomputable def ldtPointAPlaced\\\\\\\\n   340\\\\\\\\t    (D : DirectLdParams) (S : Strategy (directLdGame D))\\\\\\\\n   341\\\\\\\\t    (hS : S.IsProjective) (r : Fin D.k) :\\\\\\\\n   342\\\\\\\\t    letI := D.toLDTFieldModel\\\\\\\\n   343\\\\\\\\t    Point D.toLDTParameters → Fq D.toLDTParameters → Op (S.ιA × S.ιB) := by\\\\\\\\n   344\\\\\\\\t  letI := D.toLDTFieldModel\\\\\\\\n   345\\\\\\\\t  intro u a\\\\\\\\n   346\\\\\\\\t  exact heteroKron ((ldtCoordinatePointMeasurementA D S hS r u).outcome a) 1\\\\\\\\n   347\\\\\\\\t\\\\\\\\n   348\\\\\\\\t/-- Right placement of Bob's LDT point family. -/\\\\\\\\n   349\\\\\\\\tnoncomputable def ldtPointBPlaced\\\\\\\\n   350\\\\\\\\t    (D : DirectLdParams) (S : Strategy (directLdGame D))\\\\\\\\n   351\\\\\\\\t    (hS : S.IsProjective) (r : Fin D.k) :\\\\\\\\n   352\\\\\\\\t    letI := D.toLDTFieldModel\\\\\\\\n   353\\\\\\\\t    Point D.toLDTParameters → Fq D.toLDTParameters → Op (S.ιA × S.ιB) := by\\\\\\\\n   354\\\\\\\\t  letI := D.toLDTFieldModel\\\\\\\\n   355\\\\\\\\t  intro u a\\\\\\\\n   356\\\\\\\\t  exact heteroKron 1 ((ldtCoordinatePointMeasurementB D S hS r u).outcome a)\\\\\\\\n   357\\\\\\\\t\\\\\\\\n   358\\\\\\\\t/-- Left placement of an LDT polynomial evaluation family. -/\\\\\\\\n   359\\\\\\\\tnoncomputable def ldtPolynomialEvaluationLeft\\\\\\\\n   360\\\\\\\\t    (D : DirectLdParams) {iotaA iotaB : Type*}\\\\\\\\n   361\\\\\\\\t    [Fintype iotaA] [DecidableEq iotaA]\\\\\\\\n   362\\\\\\\\t    [Fintype iotaB] [DecidableEq iotaB] :\\\\\\\\n   363\\\\\\\\t    letI := D.toLDTFieldModel\\\\\\\\n   364\\\\\\\\t    ProjMeas (MIPStarRE.LDT.Polynomial D.toLDTParameters) iotaA →\\\\\\\\n   365\\\\\\\\t      Point D.toLDTParameters → Fq D.toLDTParameters → Op (iotaA × iotaB) := by\\\\\\\\n   366\\\\\\\\t  letI := D.toLDTFieldModel\\\\\\\\n   367\\\\\\\\t  intro G u a\\\\\\\\n   368\\\\\\\\t  exact heteroKron ((ldtPolynomialEvaluationMeasurement D G u).outcome a) 1\\\\\\\\n   369\\\\\\\\t\\\\\\\\n   370\\\\\\\\t/-- Right placement of an LDT polynomial evaluation family. -/\\\\\\\\n   371\\\\\\\\tnoncomputable def ldtPolynomialEvaluationRight\\\\\\\\n   372\\\\\\\\t    (D : DirectLdParams) {iotaA iotaB : Type*}\\\\\\\\n   373\\\\\\\\t    [Fintype iotaA] [DecidableEq iotaA]\\\\\\\\n   374\\\\\\\\t    [Fintype iotaB] [DecidableEq iotaB] :\\\\\\\\n   375\\\\\\\\t    letI := D.toLDTFieldModel\\\\\\\\n   376\\\\\\\\t    ProjMeas (MIPStarRE.LDT.Polynomial D.toLDTParameters) iotaB →\\\\\\\\n   377\\\\\\\\t      Point D.toLDTParameters → Fq D.toLDTParameters → Op (iotaA × iotaB) := by\\\\\\\\n   378\\\\\\\\t  letI := D.toLDTFieldModel\\\\\\\\n   379\\\\\\\\t  intro G u a\\\\\\\\n   380\\\\\\\\t  exact heteroKron 1 ((ldtPolynomialEvaluationMeasurement D G u).outcome a)\\\\\\\\n   381\\\\\\\\t\\\\\\\\n   382\\\\\\\\t/-- Left placement of an LDT global polynomial measurement. -/\\\\\\\\n   383\\\\\\\\tnoncomputable def ldtPolynomialLeftPlaced\\\\\\\\n   384\\\\\\\\t    (D : DirectLdParams) {iotaA iotaB : Type*}\\\\\\\\n   385\\\\\\\\t    [Fintype iotaA] [DecidableEq iotaA]\\\\\\\\n   386\\\\\\\\t    [Fintype iotaB] [DecidableEq iotaB] :\\\\\\\\n   387\\\\\\\\t    letI := D.toLDTFieldModel\\\\\\\\n   388\\\\\\\\t    ProjMeas (MIPStarRE.LDT.Polynomial D.toLDTParameters) iotaA →\\\\\\\\n   389\\\\\\\\t      MIPStarRE.LDT.Polynomial D.toLDTParameters → Op (iotaA × iotaB) := by\\\\\\\\n   390\\\\\\\\t  letI := D.toLDTFieldModel\\\\\\\\n\\\\\\\",\\\\\\\"exit_code\\\\\\\":0,\\\\\\\"status\\\\\\\":\\\\\\\"completed\\\\\\\"}}\\\\n{\\\\\\\"type\\\\\\\":\\\\\\\"item.started\\\\\\\",\\\\\\\"item\\\\\\\":{\\\\\\\"id\\\\\\\":\\\\\\\"item_141\\\\\\\",\\\\\\\"type\\\\\\\":\\\\\\\"command_execution\\\\\\\",\\\\\\\"command\\\\\\\":\\\\\\\"/bin/bash -lc \\\\\\\\\\\\\\\"nl -ba blueprint/src/chapter/ch13_qpbt_test.tex | sed -n '1,190p'\\\\\\\\nnl -ba MIPStarRE/QPBT/Test/LowDegreeGame.lean | sed -n '30,180p'\\\\\\\\nnl -ba MIPStarRE/QPBT/Test/LowDegreeGame.lean | sed -n '600,675p'\\\\\\\\nrg -n 'def ldGame|ldGame ' MIPStarRE/QPBT MIPStarRE/LDT -g '*.lean'\\\\\\\\\\\\\\\"\\\\\\\",\\\\\\\"aggregated_output\\\\\\\":\\\\\\\"\\\\\\\",\\\\\\\"exit_code\\\\\\\":null,\\\\\\\"status\\\\\\\":\\\\\\\"in_progress\\\\\\\"}}\\\\n{\\\\\\\"type\\\\\\\":\\\\\\\"item.completed\\\\\\\",\\\\\\\"item\\\\\\\":{\\\\\\\"id\\\\\\\":\\\\\\\"item_141\\\\\\\",\\\\\\\"type\\\\\\\":\\\\\\\"command_execution\\\\\\\",\\\\\\\"command\\\\\\\":\\\\\\\"/bin/bash -lc \\\\\\\\\\\\\\\"nl -ba blueprint/src/chapter/ch13_qpbt_test.tex | sed -n '1,190p'\\\\\\\\nnl -ba MIPStarRE/QPBT/Test/LowDegreeGame.lean | sed -n '30,180p'\\\\\\\\nnl -ba MIPStarRE/QPBT/Test/LowDegreeGame.lean | sed -n '600,675p'\\\\\\\\nrg -n 'def ldGame|ldGame ' MIPStarRE/QPBT MIPStarRE/LDT -g '*.lean'\\\\\\\\\\\\\\\"\\\\\\\",\\\\\\\"aggregated_output\\\\\\\":\\\\\\\"     1\\\\\\\\t\\\\\\\\\\\\\\\\chapter{The Pauli basis test}\\\\\\\\n     2\\\\\\\\t\\\\\\\\\\\\\\\\label{chap:qpbt-test}\\\\\\\\n     3\\\\\\\\t% Paper label sec:pauli-verifier kept for cross-reference fidelity; it resolves to this chapter.\\\\\\\\n     4\\\\\\\\t\\\\\\\\\\\\\\\\label{sec:pauli-verifier}\\\\\\\\n     5\\\\\\\\t\\\\\\\\n     6\\\\\\\\tThis chapter defines the two testing primitives underlying the question-reduction step: the \\\\\\\\\\\\\\\\emph{classical low individual degree game}, in its simultaneous form, and the \\\\\\\\\\\\\\\\emph{Pauli basis test}, a nonlocal game built from the classical game together with the Magic Square game. We state the quantum soundness of the classical game (Theorem~\\\\\\\\\\\\\\\\ref{lem:ld-soundness}, imported, with the facts required by the identification, which remain to be proved, recorded in \\\\\\\\\\\\\\\\cite{gap:qpbt_ld-dimension-divisibility}; see Remark~\\\\\\\\\\\\\\\\ref{rem:ld-soundness-provider}), the rigidity of the Magic Square game (Theorem~\\\\\\\\\\\\\\\\ref{thm:ms-rigidity}, imported), completeness of the Pauli basis test (Lemma~\\\\\\\\\\\\\\\\ref{lem:pauli-completeness}), and the main soundness theorem for the Pauli basis test (Theorem~\\\\\\\\\\\\\\\\ref{thm:pauli}), whose proof occupies Chapters~\\\\\\\\\\\\\\\\ref{chap:qpbt-observables}--\\\\\\\\\\\\\\\\ref{chap:qpbt-extraction} and is completed in Chapter~\\\\\\\\\\\\\\\\ref{chap:qpbt-extraction} only modulo the proof obligation documented in \\\\\\\\\\\\\\\\cite{gap:qpbt_ld-dimension-divisibility}. The chapter closes with the qubit form of the soundness statement (Corollary~\\\\\\\\\\\\\\\\ref{cor:pauli-binary}) and the canonical parameter choice with its soundness bound (Definition~\\\\\\\\\\\\\\\\ref{def:introparams}, Lemma~\\\\\\\\\\\\\\\\ref{lem:delta-bound}).\\\\\\\\n     7\\\\\\\\t\\\\\\\\n     8\\\\\\\\tThroughout, the two players are denoted $\\\\\\\\\\\\\\\\mathrm A$ and $\\\\\\\\\\\\\\\\mathrm B$; for $w \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\{\\\\\\\\\\\\\\\\mathrm A,\\\\\\\\\\\\\\\\mathrm B\\\\\\\\\\\\\\\\}$ we write $\\\\\\\\\\\\\\\\overline w$ for the other player. Games, strategies, values, conditionally linear (CL) functions and distributions, typed distributions sampled from the edges of a graph, and the state-dependent approximation $\\\\\\\\\\\\\\\\approx_\\\\\\\\\\\\\\\\delta$ between families of measurement operators are as in Chapter~\\\\\\\\\\\\\\\\ref{chap:qpbt-games}; the algebraic material on lines, canonical linear maps, the low-degree encoding, and generalized Pauli observables is from Chapter~\\\\\\\\\\\\\\\\ref{chap:qpbt-algebra}.\\\\\\\\n     9\\\\\\\\t\\\\\\\\n    10\\\\\\\\t\\\\\\\\\\\\\\\\section{The classical low individual degree game}\\\\\\\\n    11\\\\\\\\t% Paper labels sec:ld-verifier and sec:ld-game kept for cross-reference fidelity.\\\\\\\\n    12\\\\\\\\t\\\\\\\\\\\\\\\\label{sec:ld-verifier}\\\\\\\\n    13\\\\\\\\t\\\\\\\\\\\\\\\\label{sec:ld-game}\\\\\\\\n    14\\\\\\\\t\\\\\\\\n    15\\\\\\\\tThe classical low individual degree game is a two-player game based on the low individual degree variant of the multilinearity test of Babai, Fortnow, and Lund. In the basic version, one player (the ``points player'') receives a uniformly random point $u \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\F_q^m$ and answers with a value $a \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\F_q$, while the other player (the ``lines player'') receives a random line through $u$ --- either axis-parallel or diagonal --- and answers with a univariate polynomial describing the restriction of a global function to that line. If the players share a polynomial $g\\\\\\\\\\\\\\\\colon \\\\\\\\\\\\\\\\F_q^m \\\\\\\\\\\\\\\\to \\\\\\\\\\\\\\\\F_q$ of individual degree at most $d$ and answer with $g(u)$ and with the restriction $g|_\\\\\\\\\\\\\\\\ell$, they win with probability $1$; the soundness theorem below states that the converse approximately holds. In the simultaneous version, the players' answers are $k$-tuples, checked coordinatewise against a $k$-tuple of low individual degree polynomials.\\\\\\\\n    16\\\\\\\\t\\\\\\\\n    17\\\\\\\\t\\\\\\\\\\\\\\\\begin{definition}[The classical low individual degree game: parameters and registers]\\\\\\\\\\\\\\\\label{def:ld-game}\\\\\\\\n    18\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\lean{MIPStarRE.QPBT.ldGame}\\\\\\\\n    19\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\leanok\\\\\\\\n    20\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:game, def:admissible-size}\\\\\\\\n    21\\\\\\\\t\\\\\\\\t% The source fixes \\\\\\\\\\\\\\\\N to be the set of positive integers\\\\\\\\n    22\\\\\\\\t\\\\\\\\t% (references/qpbt-paper/04_preliminaries.tex:6) and takes m, d, ldc in \\\\\\\\\\\\\\\\N\\\\\\\\n    23\\\\\\\\t\\\\\\\\t% (references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:33-35),\\\\\\\\n    24\\\\\\\\t\\\\\\\\t% so the positivity below is the source's implicit domain, stated explicitly.\\\\\\\\n    25\\\\\\\\t\\\\\\\\t% It is load-bearing: at d = 0 or k = 0 the prefactor a(dmk)^a of delta_ld in\\\\\\\\n    26\\\\\\\\t\\\\\\\\t% lem:ld-soundness vanishes, and at d = 0 the resulting exact conclusions fail\\\\\\\\n    27\\\\\\\\t\\\\\\\\t% (e.g. at (q,m,d,k) = (2,1,0,1) with eps = 1). The case k = 0, though it would\\\\\\\\n    28\\\\\\\\t\\\\\\\\t% hold trivially, is likewise outside the source's domain and is omitted.\\\\\\\\n    29\\\\\\\\t\\\\\\\\tThe game $\\\\\\\\\\\\\\\\mathfrak{G}^{\\\\\\\\\\\\\\\\mathrm{ld}}$ is parametrized by a tuple $\\\\\\\\\\\\\\\\mathsf{ldparams} = (q,m,d,k)$, where $m, d, k \\\\\\\\\\\\\\\\ge 1$ are integers, $q \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\N$ is an admissible field size (Definition~\\\\\\\\\\\\\\\\ref{def:admissible-size}), and $m$ divides $q$. We write $\\\\\\\\\\\\\\\\mathfrak{G}^{\\\\\\\\\\\\\\\\mathrm{ld}}_{\\\\\\\\\\\\\\\\mathsf{ldparams}}$ to emphasize the dependence on the parameter tuple. The type set of $\\\\\\\\\\\\\\\\mathfrak{G}^{\\\\\\\\\\\\\\\\mathrm{ld}}$ is\\\\\\\\n    30\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\[\\\\\\\\n    31\\\\\\\\t\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\mathcal T^{\\\\\\\\\\\\\\\\mathrm{ld}} = \\\\\\\\\\\\\\\\{\\\\\\\\\\\\\\\\mathsf{Point}, \\\\\\\\\\\\\\\\mathsf{ALine}, \\\\\\\\\\\\\\\\mathsf{DLine}\\\\\\\\\\\\\\\\}\\\\\\\\\\\\\\\\;,\\\\\\\\n    32\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\]\\\\\\\\n    33\\\\\\\\t\\\\\\\\tand the distribution over type pairs $(t_{\\\\\\\\\\\\\\\\mathrm A}, t_{\\\\\\\\\\\\\\\\mathrm B})$ is uniform over $\\\\\\\\\\\\\\\\mathcal T^{\\\\\\\\\\\\\\\\mathrm{ld}} \\\\\\\\\\\\\\\\times \\\\\\\\\\\\\\\\mathcal T^{\\\\\\\\\\\\\\\\mathrm{ld}}$. The ambient space is the direct sum $V = V_X \\\\\\\\\\\\\\\\oplus V_I \\\\\\\\\\\\\\\\oplus V_V$ of three register subspaces: the \\\\\\\\\\\\\\\\emph{point register} $V_X \\\\\\\\\\\\\\\\cong \\\\\\\\\\\\\\\\F_q^m$, the \\\\\\\\\\\\\\\\emph{coordinate register} $V_I \\\\\\\\\\\\\\\\cong \\\\\\\\\\\\\\\\F_q$, and the \\\\\\\\\\\\\\\\emph{direction register} $V_V \\\\\\\\\\\\\\\\cong \\\\\\\\\\\\\\\\F_q^m$. Elements of $V$ are identified with triples $(u,s,v) \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\F_q^m \\\\\\\\\\\\\\\\times \\\\\\\\\\\\\\\\F_q \\\\\\\\\\\\\\\\times \\\\\\\\\\\\\\\\F_q^m$. The question distribution and the win predicate of $\\\\\\\\\\\\\\\\mathfrak{G}^{\\\\\\\\\\\\\\\\mathrm{ld}}$ are specified in Definitions~\\\\\\\\\\\\\\\\ref{def:ld-question-distribution} and~\\\\\\\\\\\\\\\\ref{def:ld-win-predicate} below.\\\\\\\\n    34\\\\\\\\t\\\\\\\\\\\\\\\\end{definition}\\\\\\\\n    35\\\\\\\\t\\\\\\\\n    36\\\\\\\\t\\\\\\\\\\\\\\\\begin{definition}[Question distribution of the classical low individual degree game]\\\\\\\\\\\\\\\\label{def:ld-question-distribution}\\\\\\\\n    37\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:ld-game, def:cl-func, def:cl-dist, lem:cl-concat, def:cl-canonical, def:line-representative}\\\\\\\\n    38\\\\\\\\t\\\\\\\\tLet $\\\\\\\\\\\\\\\\mathsf{ldparams} = (q,m,d,k)$ be as in Definition~\\\\\\\\\\\\\\\\ref{def:ld-game}. Define $L_{\\\\\\\\\\\\\\\\mathsf{Point}}$ to be the $1$-level CL function on $V$ that projects onto $V_X$: for every $(u,s,v) \\\\\\\\\\\\\\\\in V$,\\\\\\\\n    39\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\begin{equation}\\\\\\\\n    40\\\\\\\\t\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\label{eq:cl-ptf}\\\\\\\\n    41\\\\\\\\t\\\\\\\\t\\\\\\\\tL_{\\\\\\\\\\\\\\\\mathsf{Point}}(u,s,v) = (u,0,0)\\\\\\\\\\\\\\\\;.\\\\\\\\n    42\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\end{equation}\\\\\\\\n    43\\\\\\\\t\\\\\\\\tFor $s \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\F_q$, let $\\\\\\\\\\\\\\\\chi(s)$ be the unique integer such that\\\\\\\\n    44\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\begin{equation}\\\\\\\\n    45\\\\\\\\t\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\label{eq:chi-func}\\\\\\\\n    46\\\\\\\\t\\\\\\\\t\\\\\\\\ts = (\\\\\\\\\\\\\\\\chi(s)-1)\\\\\\\\\\\\\\\\,\\\\\\\\\\\\\\\\frac{q}{m} + r\\\\\\\\n    47\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\end{equation}\\\\\\\\n    48\\\\\\\\t\\\\\\\\tfor some $0 \\\\\\\\\\\\\\\\le r < q/m$, where $s$ is interpreted as an integer in $\\\\\\\\\\\\\\\\{0,1,\\\\\\\\\\\\\\\\ldots,q-1\\\\\\\\\\\\\\\\}$ under the identification of $\\\\\\\\\\\\\\\\F_q$ with binary strings fixed in Chapter~\\\\\\\\\\\\\\\\ref{chap:qpbt-algebra}. Since $m$ divides $q$, when $s$ is uniformly distributed on $\\\\\\\\\\\\\\\\F_q$ the index $\\\\\\\\\\\\\\\\chi(s)$ is uniformly distributed on $\\\\\\\\\\\\\\\\{1,2,\\\\\\\\\\\\\\\\ldots,m\\\\\\\\\\\\\\\\}$. Define $L_{\\\\\\\\\\\\\\\\mathsf{ALine}}$ by\\\\\\\\n    49\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\begin{equation}\\\\\\\\n    50\\\\\\\\t\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\label{eq:cl-alnf}\\\\\\\\n    51\\\\\\\\t\\\\\\\\t\\\\\\\\tL_{\\\\\\\\\\\\\\\\mathsf{ALine}}(u,s,v) = \\\\\\\\\\\\\\\\bigl(L^{\\\\\\\\\\\\\\\\mathrm{Ln}}_{e_i}(u),\\\\\\\\\\\\\\\\, s,\\\\\\\\\\\\\\\\, 0\\\\\\\\\\\\\\\\bigr)\\\\\\\\\\\\\\\\quad\\\\\\\\\\\\\\\\text{for all } (u,s,v) \\\\\\\\\\\\\\\\in V\\\\\\\\\\\\\\\\;,\\\\\\\\n    52\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\end{equation}\\\\\\\\n    53\\\\\\\\t\\\\\\\\twhere $i = \\\\\\\\\\\\\\\\chi(s)$ and $L^{\\\\\\\\\\\\\\\\mathrm{Ln}}_v$ denotes the canonical linear map with one-dimensional kernel spanned by $v$, used to compute canonical representatives of lines (Definition~\\\\\\\\\\\\\\\\ref{def:line-representative}). The function $L_{\\\\\\\\\\\\\\\\mathsf{ALine}}$ is the concatenation (in the sense of Lemma~\\\\\\\\\\\\\\\\ref{lem:cl-concat}) of the $1$-level CL function projecting $V_I \\\\\\\\\\\\\\\\oplus V_V$ onto $V_I$ with the family of $1$-level CL functions $\\\\\\\\\\\\\\\\{L^{\\\\\\\\\\\\\\\\mathrm{Ln}}_{e_i}\\\\\\\\\\\\\\\\}$ on $V_X$ indexed by $i \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\{1,\\\\\\\\\\\\\\\\ldots,m\\\\\\\\\\\\\\\\}$; thus $L_{\\\\\\\\\\\\\\\\mathsf{ALine}}$ is a $2$-level CL function. Define $L_{\\\\\\\\\\\\\\\\mathsf{DLine}}$ by\\\\\\\\n    54\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\begin{equation}\\\\\\\\n    55\\\\\\\\t\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\label{eq:cl-dlnf}\\\\\\\\n    56\\\\\\\\t\\\\\\\\t\\\\\\\\tL_{\\\\\\\\\\\\\\\\mathsf{DLine}}(u,s,v) = \\\\\\\\\\\\\\\\bigl(L^{\\\\\\\\\\\\\\\\mathrm{Ln}}_{\\\\\\\\\\\\\\\\pi_{i-1}(v)}(u),\\\\\\\\\\\\\\\\, s,\\\\\\\\\\\\\\\\, \\\\\\\\\\\\\\\\pi_{i-1}(v)\\\\\\\\\\\\\\\\bigr)\\\\\\\\\\\\\\\\;,\\\\\\\\n    57\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\end{equation}\\\\\\\\n    58\\\\\\\\t\\\\\\\\twhere $i = \\\\\\\\\\\\\\\\chi(s)$ and $\\\\\\\\\\\\\\\\pi_{i-1}$ zeroes out the first $i-1$ coordinates of its input. The function $L_{\\\\\\\\\\\\\\\\mathsf{DLine}}$ is the concatenation of (i) the identity on $V_I$, (ii) for each $i$ the $1$-level CL function $v \\\\\\\\\\\\\\\\mapsto \\\\\\\\\\\\\\\\pi_{i-1}(v)$ on $V_V$, and (iii) for each pair $(s,v') \\\\\\\\\\\\\\\\in V_I \\\\\\\\\\\\\\\\oplus V_V$ the $1$-level CL function $L^{\\\\\\\\\\\\\\\\mathrm{Ln}}_{v'}$ on $V_X$; thus $L_{\\\\\\\\\\\\\\\\mathsf{DLine}}$ is a $3$-level CL function.\\\\\\\\n    59\\\\\\\\t\\\\\\\\n    60\\\\\\\\t\\\\\\\\tThe question distribution of $\\\\\\\\\\\\\\\\mathfrak{G}^{\\\\\\\\\\\\\\\\mathrm{ld}}$ is the typed CL distribution obtained as follows: sample a type pair $(t_{\\\\\\\\\\\\\\\\mathrm A}, t_{\\\\\\\\\\\\\\\\mathrm B})$ uniformly from $\\\\\\\\\\\\\\\\mathcal T^{\\\\\\\\\\\\\\\\mathrm{ld}} \\\\\\\\\\\\\\\\times \\\\\\\\\\\\\\\\mathcal T^{\\\\\\\\\\\\\\\\mathrm{ld}}$, sample $z = (u,s,v)$ uniformly from $V$, and send each player $w \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\{\\\\\\\\\\\\\\\\mathrm A,\\\\\\\\\\\\\\\\mathrm B\\\\\\\\\\\\\\\\}$ the question $(t_w, L_{t_w}(z))$.\\\\\\\\n    61\\\\\\\\t\\\\\\\\\\\\\\\\end{definition}\\\\\\\\n    62\\\\\\\\t\\\\\\\\n    63\\\\\\\\t\\\\\\\\\\\\\\\\begin{lemma}[Level of the axis-parallel line map]\\\\\\\\\\\\\\\\label{lem:ld-aline-level}\\\\\\\\n    64\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\lean{MIPStarRE.QPBT.isCondLinear_ldALineCL}\\\\\\\\n    65\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\leanok\\\\\\\\n    66\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:ld-question-distribution, def:cl-func}\\\\\\\\n    67\\\\\\\\t\\\\\\\\tFix $\\\\\\\\\\\\\\\\mathsf{ldparams} = (q,m,d,k)$ as in Definition~\\\\\\\\\\\\\\\\ref{def:ld-game}. The map $L_{\\\\\\\\\\\\\\\\mathsf{ALine}}$ of Equation~\\\\\\\\\\\\\\\\eqref{eq:cl-alnf} is a $2$-level conditionally linear function on $V$.\\\\\\\\n    68\\\\\\\\t\\\\\\\\\\\\\\\\end{lemma}\\\\\\\\n    69\\\\\\\\t\\\\\\\\\\\\\\\\begin{proof}\\\\\\\\n    70\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\leanok\\\\\\\\n    71\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:cl-func, def:register-subspace, def:ld-question-distribution, def:line-representative}\\\\\\\\n    72\\\\\\\\t\\\\\\\\tThe following data exhibit $L_{\\\\\\\\\\\\\\\\mathsf{ALine}}$ as a $2$-level conditionally linear function. Its first level is the projection of $V$ onto the coordinate register $V_I$, which is linear. For a first-level value with coordinate component $s$, its second level is the linear map $L^{\\\\\\\\\\\\\\\\mathrm{Ln}}_{e_i}$ with $i = \\\\\\\\\\\\\\\\chi(s)$, acting on the point register $V_X$. The registers $V_I$ and $V_X$ are disjoint, so the second level is supported on a register subspace disjoint from the first, and summing the two contributions gives $\\\\\\\\\\\\\\\\bigl(L^{\\\\\\\\\\\\\\\\mathrm{Ln}}_{e_i}(u),\\\\\\\\\\\\\\\\, s,\\\\\\\\\\\\\\\\, 0\\\\\\\\\\\\\\\\bigr)$, which is $L_{\\\\\\\\\\\\\\\\mathsf{ALine}}(u,s,v)$ by Equation~\\\\\\\\\\\\\\\\eqref{eq:cl-alnf}.\\\\\\\\n    73\\\\\\\\t\\\\\\\\\\\\\\\\end{proof}\\\\\\\\n    74\\\\\\\\t\\\\\\\\n    75\\\\\\\\t\\\\\\\\\\\\\\\\begin{lemma}[Level of the diagonal line map]\\\\\\\\\\\\\\\\label{lem:ld-dline-level}\\\\\\\\n    76\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\lean{MIPStarRE.QPBT.isCondLinear_ldDLineCL}\\\\\\\\n    77\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\leanok\\\\\\\\n    78\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:ld-question-distribution, def:cl-func}\\\\\\\\n    79\\\\\\\\t\\\\\\\\tFix $\\\\\\\\\\\\\\\\mathsf{ldparams} = (q,m,d,k)$ as in Definition~\\\\\\\\\\\\\\\\ref{def:ld-game}. The map $L_{\\\\\\\\\\\\\\\\mathsf{DLine}}$ of Equation~\\\\\\\\\\\\\\\\eqref{eq:cl-dlnf} is a $3$-level conditionally linear function on $V$.\\\\\\\\n    80\\\\\\\\t\\\\\\\\\\\\\\\\end{lemma}\\\\\\\\n    81\\\\\\\\t\\\\\\\\\\\\\\\\begin{proof}\\\\\\\\n    82\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\leanok\\\\\\\\n    83\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:cl-func, def:register-subspace, def:ld-question-distribution, def:line-representative}\\\\\\\\n    84\\\\\\\\t\\\\\\\\tThe following data exhibit $L_{\\\\\\\\\\\\\\\\mathsf{DLine}}$ as a $3$-level conditionally linear function. Its first level is the projection of $V$ onto the coordinate register $V_I$. For a first-level value with coordinate component $s$, its second level is the linear map $v \\\\\\\\\\\\\\\\mapsto \\\\\\\\\\\\\\\\pi_{i-1}(v)$ with $i = \\\\\\\\\\\\\\\\chi(s)$ on the direction register $V_V$. For a second-level value with direction component $v'$, its third level is the linear map $L^{\\\\\\\\\\\\\\\\mathrm{Ln}}_{v'}$ on the point register $V_X$. The registers $V_I$, $V_V$ and $V_X$ are pairwise disjoint, so each level is supported on a register subspace disjoint from the preceding ones, and summing the three contributions gives $\\\\\\\\\\\\\\\\bigl(L^{\\\\\\\\\\\\\\\\mathrm{Ln}}_{\\\\\\\\\\\\\\\\pi_{i-1}(v)}(u),\\\\\\\\\\\\\\\\, s,\\\\\\\\\\\\\\\\, \\\\\\\\\\\\\\\\pi_{i-1}(v)\\\\\\\\\\\\\\\\bigr)$, which is $L_{\\\\\\\\\\\\\\\\mathsf{DLine}}(u,s,v)$ by Equation~\\\\\\\\\\\\\\\\eqref{eq:cl-dlnf}.\\\\\\\\n    85\\\\\\\\t\\\\\\\\\\\\\\\\end{proof}\\\\\\\\n    86\\\\\\\\t\\\\\\\\n    87\\\\\\\\t\\\\\\\\\\\\\\\\begin{lemma}[The low-degree question distribution is a typed CL distribution]\\\\\\\\\\\\\\\\label{lem:ld-question-typed-cl}\\\\\\\\n    88\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\lean{MIPStarRE.QPBT.ldQuestionDistribution_eq_typedCL}\\\\\\\\n    89\\\\\\\\t\\\\\\\\t% No completion mark: the linked declaration proves the distribution identity only, not the typed-family assertion. See the last paragraph of the statement; the open family assertion is tracked by issue 180.\\\\\\\\n    90\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:ld-question-distribution, def:typed-cl-distributions, def:graph-distribution, lem:ld-aline-level, lem:ld-dline-level}\\\\\\\\n    91\\\\\\\\t\\\\\\\\tFix $\\\\\\\\\\\\\\\\mathsf{ldparams} = (q,m,d,k)$ as in Definition~\\\\\\\\\\\\\\\\ref{def:ld-game}, let $L = \\\\\\\\\\\\\\\\{L_t\\\\\\\\\\\\\\\\}_{t \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\mathcal T^{\\\\\\\\\\\\\\\\mathrm{ld}}}$ be the family of Definition~\\\\\\\\\\\\\\\\ref{def:ld-question-distribution}, and let $G^{\\\\\\\\\\\\\\\\mathrm{ld}}$ be the graph on $\\\\\\\\\\\\\\\\mathcal T^{\\\\\\\\\\\\\\\\mathrm{ld}}$ all of whose unordered pairs, self-loops included, are edges. Then the question distribution of $\\\\\\\\\\\\\\\\mathfrak{G}^{\\\\\\\\\\\\\\\\mathrm{ld}}$ is the $(\\\\\\\\\\\\\\\\mathcal T^{\\\\\\\\\\\\\\\\mathrm{ld}}, G^{\\\\\\\\\\\\\\\\mathrm{ld}})$-typed conditionally linear distribution $\\\\\\\\\\\\\\\\mu^{G^{\\\\\\\\\\\\\\\\mathrm{ld}}}_{L,\\\\\\\\\\\\\\\\,L}$ of Definition~\\\\\\\\\\\\\\\\ref{def:typed-cl-distributions}. The linked declaration proves the distribution identity: the question distribution of $\\\\\\\\\\\\\\\\mathfrak{G}^{\\\\\\\\\\\\\\\\mathrm{ld}}$ equals the distribution that the construction of Definition~\\\\\\\\\\\\\\\\ref{def:typed-cl-distributions} produces from the pair $(L, L)$ and the graph $G^{\\\\\\\\\\\\\\\\mathrm{ld}}$, a construction that is available for an arbitrary family of maps. It does not prove that $L$ is a $\\\\\\\\\\\\\\\\mathcal T^{\\\\\\\\\\\\\\\\mathrm{ld}}$-typed family of conditionally linear functions of one common level, which is what makes the right-hand side a typed conditionally linear distribution in the sense of Definition~\\\\\\\\\\\\\\\\ref{def:typed-cl-distributions}: Lemmas~\\\\\\\\\\\\\\\\ref{lem:ld-aline-level} and~\\\\\\\\\\\\\\\\ref{lem:ld-dline-level} give the levels of $L_{\\\\\\\\\\\\\\\\mathsf{ALine}}$ and $L_{\\\\\\\\\\\\\\\\mathsf{DLine}}$, while the level of $L_{\\\\\\\\\\\\\\\\mathsf{Point}}$ and the passage of the three maps to a common level are not formalized. That family assertion is open and is tracked as issue~\\\\\\\\\\\\\\\\#180, so the statement and the proof below carry no completion mark.\\\\\\\\n    92\\\\\\\\t\\\\\\\\\\\\\\\\end{lemma}\\\\\\\\n    93\\\\\\\\t\\\\\\\\\\\\\\\\begin{proof}\\\\\\\\n    94\\\\\\\\t\\\\\\\\t% No completion mark: the Lean proof establishes the distribution identity only; the typed-family hypotheses on L are open and tracked by issue 180.\\\\\\\\n    95\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:typed-cl-distributions, def:graph-distribution, def:cl-dist}\\\\\\\\n    96\\\\\\\\t\\\\\\\\tEvery unordered pair of types is an edge of $G^{\\\\\\\\\\\\\\\\mathrm{ld}}$, so the graph distribution $\\\\\\\\\\\\\\\\mu_{G^{\\\\\\\\\\\\\\\\mathrm{ld}}}$ of Definition~\\\\\\\\\\\\\\\\ref{def:graph-distribution} is the uniform distribution on $\\\\\\\\\\\\\\\\mathcal T^{\\\\\\\\\\\\\\\\mathrm{ld}} \\\\\\\\\\\\\\\\times \\\\\\\\\\\\\\\\mathcal T^{\\\\\\\\\\\\\\\\mathrm{ld}}$. For each ordered type pair $(t_{\\\\\\\\\\\\\\\\mathrm A}, t_{\\\\\\\\\\\\\\\\mathrm B})$ the CL distribution $\\\\\\\\\\\\\\\\mu_{L_{t_{\\\\\\\\\\\\\\\\mathrm A}},\\\\\\\\\\\\\\\\, L_{t_{\\\\\\\\\\\\\\\\mathrm B}}}$ is the push-forward of the uniform distribution on $V$ along $z \\\\\\\\\\\\\\\\mapsto \\\\\\\\\\\\\\\\bigl(L_{t_{\\\\\\\\\\\\\\\\mathrm A}}(z), L_{t_{\\\\\\\\\\\\\\\\mathrm B}}(z)\\\\\\\\\\\\\\\\bigr)$. Binding the uniform type pair to these push-forwards and tagging each content with its type is exactly the two-stage sampling procedure of Definition~\\\\\\\\\\\\\\\\ref{def:ld-question-distribution}. This establishes the distribution identity; the typed-family hypotheses on $L$ are not established here.\\\\\\\\n    97\\\\\\\\t\\\\\\\\\\\\\\\\end{proof}\\\\\\\\n    98\\\\\\\\t\\\\\\\\n    99\\\\\\\\tThe next two lemmas show that the CL functions $L_{\\\\\\\\\\\\\\\\mathsf{Point}}$, $L_{\\\\\\\\\\\\\\\\mathsf{ALine}}$, $L_{\\\\\\\\\\\\\\\\mathsf{DLine}}$ give rise to the axis-parallel and diagonal line-versus-point distributions.\\\\\\\\n   100\\\\\\\\tWe label the coordinates by $r\\\\\\\\\\\\\\\\in\\\\\\\\\\\\\\\\{0,\\\\\\\\\\\\\\\\ldots,m-1\\\\\\\\\\\\\\\\}$, with label $r$\\\\\\\\n   101\\\\\\\\trepresenting the paper's coordinate $r+1$.\\\\\\\\n   102\\\\\\\\t\\\\\\\\n   103\\\\\\\\t\\\\\\\\\\\\\\\\begin{lemma}\\\\\\\\\\\\\\\\label{lem:alnf}\\\\\\\\n   104\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\lean{MIPStarRE.QPBT.aLinePointDist_point_marginal_uniform, MIPStarRE.QPBT.aLinePointDist_mem_line}\\\\\\\\n   105\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\leanok\\\\\\\\n   106\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:ld-question-distribution, def:line}\\\\\\\\n   107\\\\\\\\t\\\\\\\\tConsider the pair $(\\\\\\\\\\\\\\\\ell, u)$ sampled in the following way: first, sample the tuple $\\\\\\\\\\\\\\\\bigl((u_0,s,0),(u,0,0)\\\\\\\\\\\\\\\\bigr)$ from the CL distribution $\\\\\\\\\\\\\\\\mu_{L_{\\\\\\\\\\\\\\\\mathsf{ALine}}, L_{\\\\\\\\\\\\\\\\mathsf{Point}}}$, and let $\\\\\\\\\\\\\\\\ell = \\\\\\\\\\\\\\\\ell(u_0, e_i)$ where $i = \\\\\\\\\\\\\\\\chi(s)$. Then $u$ is a uniformly random point in $\\\\\\\\\\\\\\\\F_q^m$, and $\\\\\\\\\\\\\\\\ell$ is a line that goes through $u$ and is parallel to a uniformly random axis $i \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\{1,2,\\\\\\\\\\\\\\\\ldots,m\\\\\\\\\\\\\\\\}$.\\\\\\\\n   108\\\\\\\\t\\\\\\\\\\\\\\\\end{lemma}\\\\\\\\n   109\\\\\\\\t\\\\\\\\\\\\\\\\begin{proof}\\\\\\\\n   110\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\leanok\\\\\\\\n   111\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:cl-dist, def:ld-question-distribution, def:line-representative, lem:line-rep-incidence}\\\\\\\\n   112\\\\\\\\t\\\\\\\\tBy Definition~\\\\\\\\\\\\\\\\ref{def:cl-dist} the distribution $\\\\\\\\\\\\\\\\mu_{L_{\\\\\\\\\\\\\\\\mathsf{ALine}}, L_{\\\\\\\\\\\\\\\\mathsf{Point}}}$ is the push-forward of the uniform distribution on $V$ along $z \\\\\\\\\\\\\\\\mapsto \\\\\\\\\\\\\\\\bigl(L_{\\\\\\\\\\\\\\\\mathsf{ALine}}(z), L_{\\\\\\\\\\\\\\\\mathsf{Point}}(z)\\\\\\\\\\\\\\\\bigr)$, so each marginal below is the push-forward of the uniform distribution on $V$ along the composite of that map with the corresponding coordinate. The point marginal is the image of the uniform distribution on $V$ under $(u,s,v) \\\\\\\\\\\\\\\\mapsto u$, hence uniform on $\\\\\\\\\\\\\\\\F_q^m$. The axis marginal is its image under $(u,s,v) \\\\\\\\\\\\\\\\mapsto \\\\\\\\\\\\\\\\chi(s)$; since $m$ divides $q$, every fibre of $\\\\\\\\\\\\\\\\chi$ has exactly $q/m$ elements, so $i = \\\\\\\\\\\\\\\\chi(s)$ is uniform on $\\\\\\\\\\\\\\\\{1,2,\\\\\\\\\\\\\\\\ldots,m\\\\\\\\\\\\\\\\}$ and $(u_0,s)$ specifies a uniformly random axis-parallel line $\\\\\\\\\\\\\\\\ell(u_0,e_i)$. Finally the base point recorded in the sample is $u_0 = L^{\\\\\\\\\\\\\\\\mathrm{Ln}}_{e_i}(u)$, which is fixed by $L^{\\\\\\\\\\\\\\\\mathrm{Ln}}_{e_i}$ (Definition~\\\\\\\\\\\\\\\\ref{def:line-representative}) and satisfies $u \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\ell(u_0,e_i)$ by Lemma~\\\\\\\\\\\\\\\\ref{lem:line-rep-incidence}.\\\\\\\\n   113\\\\\\\\t\\\\\\\\\\\\\\\\end{proof}\\\\\\\\n   114\\\\\\\\t\\\\\\\\n   115\\\\\\\\t\\\\\\\\\\\\\\\\begin{lemma}\\\\\\\\\\\\\\\\label{lem:dlnf}\\\\\\\\n   116\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\lean{MIPStarRE.QPBT.dLinePointDist_point_marginal_uniform, MIPStarRE.QPBT.dLinePointDist_mem_line, MIPStarRE.QPBT.dLinePointDist_prefix_zero}\\\\\\\\n   117\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\leanok\\\\\\\\n   118\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:ld-question-distribution, def:line}\\\\\\\\n   119\\\\\\\\t\\\\\\\\tConsider the pair $(\\\\\\\\\\\\\\\\ell, u)$ sampled in the following way: first, sample the tuple $\\\\\\\\\\\\\\\\bigl((u_0,s,v),(u,0,0)\\\\\\\\\\\\\\\\bigr)$ from the CL distribution $\\\\\\\\\\\\\\\\mu_{L_{\\\\\\\\\\\\\\\\mathsf{DLine}}, L_{\\\\\\\\\\\\\\\\mathsf{Point}}}$, and let $\\\\\\\\\\\\\\\\ell = \\\\\\\\\\\\\\\\ell(u_0, v)$ where $i = \\\\\\\\\\\\\\\\chi(s)$. Then $u$ is a uniformly random point in $\\\\\\\\\\\\\\\\F_q^m$, and $\\\\\\\\\\\\\\\\ell$ is a random diagonal line that goes through $u$ and shares its first $i-1$ coordinates with $u$, for uniformly random $i \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\{1,2,\\\\\\\\\\\\\\\\ldots,m\\\\\\\\\\\\\\\\}$.\\\\\\\\n   120\\\\\\\\t\\\\\\\\\\\\\\\\end{lemma}\\\\\\\\n   121\\\\\\\\t\\\\\\\\\\\\\\\\begin{proof}\\\\\\\\n   122\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\leanok\\\\\\\\n   123\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:cl-dist, def:ld-question-distribution, def:line-representative, lem:line-rep-incidence}\\\\\\\\n   124\\\\\\\\t\\\\\\\\tThe three steps are those of the proof of Lemma~\\\\\\\\\\\\\\\\ref{lem:alnf}, and none of them depends on that lemma. The two marginals are again push-forwards of the uniform distribution on $V$ along coordinates of $z \\\\\\\\\\\\\\\\mapsto \\\\\\\\\\\\\\\\bigl(L_{\\\\\\\\\\\\\\\\mathsf{DLine}}(z), L_{\\\\\\\\\\\\\\\\mathsf{Point}}(z)\\\\\\\\\\\\\\\\bigr)$, by Definition~\\\\\\\\\\\\\\\\ref{def:cl-dist}: the point marginal is uniform on $\\\\\\\\\\\\\\\\F_q^m$, and $i = \\\\\\\\\\\\\\\\chi(s)$ is uniform on $\\\\\\\\\\\\\\\\{1,2,\\\\\\\\\\\\\\\\ldots,m\\\\\\\\\\\\\\\\}$ because every fibre of $\\\\\\\\\\\\\\\\chi$ has $q/m$ elements. The direction component of the sampled tuple is $v' = \\\\\\\\\\\\\\\\pi_{i-1}(v)$, whose first $i-1$ coordinates vanish and which is unchanged by a further application of $\\\\\\\\\\\\\\\\pi_{i-1}$. Finally $u_0 = L^{\\\\\\\\\\\\\\\\mathrm{Ln}}_{v'}(u)$ is fixed by $L^{\\\\\\\\\\\\\\\\mathrm{Ln}}_{v'}$ (Definition~\\\\\\\\\\\\\\\\ref{def:line-representative}) and satisfies $u \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\ell(u_0,v')$ by Lemma~\\\\\\\\\\\\\\\\ref{lem:line-rep-incidence}.\\\\\\\\n   125\\\\\\\\t\\\\\\\\\\\\\\\\end{proof}\\\\\\\\n   126\\\\\\\\t\\\\\\\\n   127\\\\\\\\t\\\\\\\\\\\\\\\\begin{definition}[Line-point distributions]\\\\\\\\\\\\\\\\label{def:line-point-dist}\\\\\\\\n   128\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\lean{MIPStarRE.QPBT.LineKind, MIPStarRE.QPBT.LineDesc}\\\\\\\\n   129\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\lean{MIPStarRE.QPBT.aLinePointDist, MIPStarRE.QPBT.dLinePointDist}\\\\\\\\n   130\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\lean{MIPStarRE.QPBT.linePointDist}\\\\\\\\n   131\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\lean{MIPStarRE.QPBT.aLinePointDist_isProbability}\\\\\\\\n   132\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\lean{MIPStarRE.QPBT.dLinePointDist_isProbability}\\\\\\\\n   133\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\lean{MIPStarRE.QPBT.linePointDist_isProbability}\\\\\\\\n   134\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\leanok\\\\\\\\n   135\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:ld-question-distribution, lem:alnf, lem:dlnf}\\\\\\\\n   136\\\\\\\\t\\\\\\\\tThe \\\\\\\\\\\\\\\\emph{axis line-point distribution} $D_{\\\\\\\\\\\\\\\\mathsf{ALine}}$ is the distribution $\\\\\\\\\\\\\\\\mu_{L_{\\\\\\\\\\\\\\\\mathsf{ALine}}, L_{\\\\\\\\\\\\\\\\mathsf{Point}}}$ over pairs $(\\\\\\\\\\\\\\\\ell = (u_0,e_i),\\\\\\\\\\\\\\\\, u)$, where we omit the $0$ components for simplicity. The \\\\\\\\\\\\\\\\emph{diagonal line-point distribution} $D_{\\\\\\\\\\\\\\\\mathsf{DLine}}$ is the distribution $\\\\\\\\\\\\\\\\mu_{L_{\\\\\\\\\\\\\\\\mathsf{DLine}}, L_{\\\\\\\\\\\\\\\\mathsf{Point}}}$ over pairs $(\\\\\\\\\\\\\\\\ell = (u_0,s,v),\\\\\\\\\\\\\\\\, u)$. The \\\\\\\\\\\\\\\\emph{line-point distribution} $D_{\\\\\\\\\\\\\\\\mathsf{Line}}$ is the equal mixture of the two: with probability $\\\\\\\\\\\\\\\\tfrac12$ output a sample from $D_{\\\\\\\\\\\\\\\\mathsf{ALine}}$, and with probability $\\\\\\\\\\\\\\\\tfrac12$ output a sample from $D_{\\\\\\\\\\\\\\\\mathsf{DLine}}$.\\\\\\\\n   137\\\\\\\\t\\\\\\\\\\\\\\\\end{definition}\\\\\\\\n   138\\\\\\\\t\\\\\\\\n   139\\\\\\\\t\\\\\\\\\\\\\\\\begin{definition}[Win predicate of the classical low individual degree game]\\\\\\\\\\\\\\\\label{def:ld-win-predicate}\\\\\\\\n   140\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:ld-game, def:ld-question-distribution, def:line, def:polyfunc}\\\\\\\\n   141\\\\\\\\t\\\\\\\\tFix $\\\\\\\\\\\\\\\\mathsf{ldparams} = (q,m,d,k)$. Answers in the game $\\\\\\\\\\\\\\\\mathfrak{G}^{\\\\\\\\\\\\\\\\mathrm{ld}}_{\\\\\\\\\\\\\\\\mathsf{ldparams}}$ take the following forms, depending on the question type; answers not of the prescribed form are rejected.\\\\\\\\n   142\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\begin{itemize}\\\\\\\\n   143\\\\\\\\t\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\item Type $\\\\\\\\\\\\\\\\mathsf{Point}$, question content $u \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\F_q^m$: the answer is an element of $\\\\\\\\\\\\\\\\F_q^k$.\\\\\\\\n   144\\\\\\\\t\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\item Type $\\\\\\\\\\\\\\\\mathsf{ALine}$, question content $(u_0,s) \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\F_q^m \\\\\\\\\\\\\\\\times \\\\\\\\\\\\\\\\F_q$, specifying the axis-parallel line $\\\\\\\\\\\\\\\\ell(u_0,e_i)$ with $i = \\\\\\\\\\\\\\\\chi(s)$: the answer is a $k$-tuple $(f_1,\\\\\\\\\\\\\\\\ldots,f_k)$ of univariate polynomials $f_j\\\\\\\\\\\\\\\\colon \\\\\\\\\\\\\\\\F_q \\\\\\\\\\\\\\\\to \\\\\\\\\\\\\\\\F_q$ of degree at most $d$, each given by its $d+1$ coefficients.\\\\\\\\n   145\\\\\\\\t\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\item Type $\\\\\\\\\\\\\\\\mathsf{DLine}$, question content $(u_0,s,v) \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\F_q^m \\\\\\\\\\\\\\\\times \\\\\\\\\\\\\\\\F_q \\\\\\\\\\\\\\\\times \\\\\\\\\\\\\\\\F_q^m$, specifying the diagonal line $\\\\\\\\\\\\\\\\ell(u_0,v')$ with $v' = \\\\\\\\\\\\\\\\pi_{i-1}(v)$ and $i = \\\\\\\\\\\\\\\\chi(s)$: the answer is a $k$-tuple of univariate polynomials of degree at most $md$.\\\\\\\\n   146\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\end{itemize}\\\\\\\\n   147\\\\\\\\t\\\\\\\\tThe win predicate $D^{\\\\\\\\\\\\\\\\mathrm{ld}} = D^{\\\\\\\\\\\\\\\\mathrm{ld}}_{\\\\\\\\\\\\\\\\mathsf{ldparams}}$ is the function of the tuple $(t_{\\\\\\\\\\\\\\\\mathrm A}, x_{\\\\\\\\\\\\\\\\mathrm A}, t_{\\\\\\\\\\\\\\\\mathrm B}, x_{\\\\\\\\\\\\\\\\mathrm B}, a_{\\\\\\\\\\\\\\\\mathrm A}, a_{\\\\\\\\\\\\\\\\mathrm B})$ determined by the following clauses, evaluated for $w \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\{\\\\\\\\\\\\\\\\mathrm A,\\\\\\\\\\\\\\\\mathrm B\\\\\\\\\\\\\\\\}$; in all cases where no action is indicated, the predicate accepts.\\\\\\\\n   148\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\begin{enumerate}\\\\\\\\n   149\\\\\\\\t\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\item (\\\\\\\\\\\\\\\\textbf{Consistency test}) If $t_{\\\\\\\\\\\\\\\\mathrm A} = t_{\\\\\\\\\\\\\\\\mathrm B}$, accept if and only if $a_{\\\\\\\\\\\\\\\\mathrm A} = a_{\\\\\\\\\\\\\\\\mathrm B}$.\\\\\\\\n   150\\\\\\\\t\\\\\\\\t\\\\\\\\t% The source phrases both clauses with \\\\\\\\\\\\\\\"the\\\\\\\\\\\\\\\" t such that x = u_0 + tv; that phrase\\\\\\\\n   151\\\\\\\\t\\\\\\\\t\\\\\\\\t% does not determine t on diagonal questions with direction v' = 0, which the\\\\\\\\n   152\\\\\\\\t\\\\\\\\t\\\\\\\\t% question distribution samples with positive probability. The universal\\\\\\\\n   153\\\\\\\\t\\\\\\\\t\\\\\\\\t% quantification over t used here is the local correction; see the remark below.\\\\\\\\n   154\\\\\\\\t\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\item (\\\\\\\\\\\\\\\\textbf{Axis-parallel line-versus-point test}) If $t_w = \\\\\\\\\\\\\\\\mathsf{ALine}$ and $t_{\\\\\\\\\\\\\\\\overline w} = \\\\\\\\\\\\\\\\mathsf{Point}$, accept if and only if $f_j(t) = (a_{\\\\\\\\\\\\\\\\overline w})_j$ for all $j \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\{1,2,\\\\\\\\\\\\\\\\ldots,k\\\\\\\\\\\\\\\\}$ and all $t \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\F_q$ such that $x_{\\\\\\\\\\\\\\\\overline w} = u_0 + t e_i$, where $i = \\\\\\\\\\\\\\\\chi(s)$.\\\\\\\\n   155\\\\\\\\t\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\item (\\\\\\\\\\\\\\\\textbf{Diagonal line-versus-point test}) If $t_w = \\\\\\\\\\\\\\\\mathsf{DLine}$ and $t_{\\\\\\\\\\\\\\\\overline w} = \\\\\\\\\\\\\\\\mathsf{Point}$, accept if and only if $f_j(t) = (a_{\\\\\\\\\\\\\\\\overline w})_j$ for all $j \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\{1,2,\\\\\\\\\\\\\\\\ldots,k\\\\\\\\\\\\\\\\}$ and all $t \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\F_q$ such that $x_{\\\\\\\\\\\\\\\\overline w} = u_0 + t v'$, where $v' = \\\\\\\\\\\\\\\\pi_{i-1}(v)$ and $i = \\\\\\\\\\\\\\\\chi(s)$.\\\\\\\\n   156\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\end{enumerate}\\\\\\\\n   157\\\\\\\\t\\\\\\\\tThe game $\\\\\\\\\\\\\\\\mathfrak{G}^{\\\\\\\\\\\\\\\\mathrm{ld}}_{\\\\\\\\\\\\\\\\mathsf{ldparams}}$ is the typed game with type set $\\\\\\\\\\\\\\\\mathcal T^{\\\\\\\\\\\\\\\\mathrm{ld}}$, the question distribution of Definition~\\\\\\\\\\\\\\\\ref{def:ld-question-distribution}, and win predicate $D^{\\\\\\\\\\\\\\\\mathrm{ld}}_{\\\\\\\\\\\\\\\\mathsf{ldparams}}$.\\\\\\\\n   158\\\\\\\\t\\\\\\\\\\\\\\\\end{definition}\\\\\\\\n   159\\\\\\\\t\\\\\\\\n   160\\\\\\\\t\\\\\\\\\\\\\\\\begin{remark}[Diagonal questions with zero direction]\\\\\\\\\\\\\\\\label{rem:ld-win-zero-direction}\\\\\\\\n   161\\\\\\\\t\\\\\\\\tThe source states the two line-versus-point clauses with ``the'' $t \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\F_q$ such that $x_{\\\\\\\\\\\\\\\\overline w} = u_0 + t v$. When the direction is nonzero and $x_{\\\\\\\\\\\\\\\\overline w}$ lies on the line, exactly one such $t$ exists and the formulation above agrees with the source. But zero directions occur: Definition~\\\\\\\\\\\\\\\\ref{def:line} explicitly permits them, and the question distribution of Definition~\\\\\\\\\\\\\\\\ref{def:ld-question-distribution} produces $\\\\\\\\\\\\\\\\mathsf{DLine}$ questions with $v' = \\\\\\\\\\\\\\\\pi_{i-1}(v) = 0$ with positive probability, namely whenever the last $m - i + 1$ coordinates of $v$ vanish. In that case $\\\\\\\\\\\\\\\\ell(u_0, 0) = \\\\\\\\\\\\\\\\{u_0\\\\\\\\\\\\\\\\}$, every $t \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\F_q$ satisfies $x_{\\\\\\\\\\\\\\\\overline w} = u_0 + t v'$ when $x_{\\\\\\\\\\\\\\\\overline w} = u_0$, and the source clause does not determine acceptance for a nonconstant answer polynomial. The universal quantification over $t$ adopted in Definition~\\\\\\\\\\\\\\\\ref{def:ld-win-predicate} makes the predicate a well-defined function of its arguments; it accepts vacuously when no such $t$ exists, a case the question distribution never produces. Completeness is unaffected: the restriction of a polynomial $g$ to the singleton line $\\\\\\\\\\\\\\\\ell(u_0,0)$, expressed through the parameterization $t \\\\\\\\\\\\\\\\mapsto u_0 + t \\\\\\\\\\\\\\\\cdot 0$, is the constant polynomial with value $g(u_0)$, which passes the check for every $t$. Soundness is likewise unaffected: zero directions occur with probability at most $2/(mq)$, so any acceptance convention on this event changes success probabilities by at most that amount; the game-correspondence obligation enumerated in the proof of Theorem~\\\\\\\\\\\\\\\\ref{lem:ld-soundness} accounts for this event explicitly, and an error of this shape is absorbed into the universal constants of $\\\\\\\\\\\\\\\\delta_{\\\\\\\\\\\\\\\\mathrm{ld}}$.\\\\\\\\n   162\\\\\\\\t\\\\\\\\\\\\\\\\end{remark}\\\\\\\\n   163\\\\\\\\t\\\\\\\\n   164\\\\\\\\tThe soundness properties of the low individual degree game are expressed in terms of the following class of measurements.\\\\\\\\n   165\\\\\\\\t\\\\\\\\n   166\\\\\\\\t\\\\\\\\\\\\\\\\begin{definition}[Low-degree polynomial measurements]\\\\\\\\\\\\\\\\label{def:ld-meas}\\\\\\\\n   167\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\lean{MIPStarRE.QPBT.PolyIndex, MIPStarRE.QPBT.PolyMeas, MIPStarRE.QPBT.PolyMeasFamily, MIPStarRE.QPBT.PolyMeasTuple}\\\\\\\\n   168\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\leanok\\\\\\\\n   169\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:polyfunc, def:polymeasurements, def:polynomials-degree}\\\\\\\\n   170\\\\\\\\t\\\\\\\\tLet $\\\\\\\\\\\\\\\\polymeas{m}{q}{d}$ denote the set of POVM measurements indexed by $\\\\\\\\\\\\\\\\polyfunc{m}{q}{d}$, the polynomial representatives of individual degree at most $d$ in each variable; this is the notion of Definition~\\\\\\\\\\\\\\\\ref{def:polymeasurements}, and the argument order $(m,q,d)$ follows that definition (the paper orders the arguments as $(m,d,q)$). By Definition~\\\\\\\\\\\\\\\\ref{def:polynomials-degree}, evaluation identifies these representatives with the corresponding polynomial functions $g\\\\\\\\\\\\\\\\colon \\\\\\\\\\\\\\\\F_q^m \\\\\\\\\\\\\\\\to \\\\\\\\\\\\\\\\F_q$, bijectively whenever $d \\\\\\\\\\\\\\\\le q-1$; at the canonical parameters (Definition~\\\\\\\\\\\\\\\\ref{def:introparams}, where $d = 1 \\\\\\\\\\\\\\\\le q-1$) the identification is bijective; the general statements of this chapter quantify over all admissible tuples and are read through the representative convention. More generally, for an integer $k$ and tuples $m = (m_1,\\\\\\\\\\\\\\\\ldots,m_k)$, $q = (q_1,\\\\\\\\\\\\\\\\ldots,q_k)$, $d = (d_1,\\\\\\\\\\\\\\\\ldots,d_k)$, let $\\\\\\\\\\\\\\\\mathrm{PolyMeas}(m,q,d,k)$ denote the set of measurements $G = \\\\\\\\\\\\\\\\{G_{g_1,\\\\\\\\\\\\\\\\ldots,g_k}\\\\\\\\\\\\\\\\}$ such that for each $i \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\{1,\\\\\\\\\\\\\\\\ldots,k\\\\\\\\\\\\\\\\}$, the outcome index $g_i$ is a polynomial $g_i\\\\\\\\\\\\\\\\colon \\\\\\\\\\\\\\\\F_{q_i}^{m_i} \\\\\\\\\\\\\\\\to \\\\\\\\\\\\\\\\F_{q_i}$ of individual degree at most $d_i$.\\\\\\\\n   171\\\\\\\\t\\\\\\\\tThe tuple components are labelled by $r\\\\\\\\\\\\\\\\in\\\\\\\\\\\\\\\\{0,\\\\\\\\\\\\\\\\ldots,k-1\\\\\\\\\\\\\\\\}$, with\\\\\\\\n   172\\\\\\\\t\\\\\\\\tlabel $r$ representing the paper's component $r+1$.\\\\\\\\n   173\\\\\\\\t\\\\\\\\\\\\\\\\end{definition}\\\\\\\\n   174\\\\\\\\t\\\\\\\\n   175\\\\\\\\tQuantum soundness of a version of the classical low-degree test for polynomials of low \\\\\\\\\\\\\\\\emph{total} degree was claimed by Natarajan and Vidick, building on an analysis of a three-prover version of the test by Vidick; there is a known gap in the soundness analysis of that test, and it is not used here. Instead, the construction relies on the low \\\\\\\\\\\\\\\\emph{individual} degree test, whose quantum soundness is proved in~\\\\\\\\\\\\\\\\cite{Ji2020LowIndividualDegree} and generalized in~\\\\\\\\\\\\\\\\cite{Ji2021Quantum}. The statement below is the form most directly useful in what follows.\\\\\\\\n   176\\\\\\\\t\\\\\\\\n   177\\\\\\\\t% The paper states this result in a theorem environment with the label lem:ld-soundness.\\\\\\\\n   178\\\\\\\\t% We keep both the environment and the label verbatim for cross-reference fidelity.\\\\\\\\n   179\\\\\\\\t\\\\\\\\\\\\\\\\begin{theorem}[Quantum soundness of the simultaneous classical low individual degree test]\\\\\\\\\\\\\\\\label{lem:ld-soundness}\\\\\\\\n   180\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\lean{MIPStarRE.QPBT.deltaLd, MIPStarRE.QPBT.exists_ld_soundness}\\\\\\\\n   181\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\leanok\\\\\\\\n   182\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\uses{def:ld-game, def:ld-question-distribution, def:ld-win-predicate, def:ld-meas, def:projective-strategy-general, def:tensor-product-value, def:consistency, def:bracket}\\\\\\\\n   183\\\\\\\\t\\\\\\\\tThere exists a function\\\\\\\\n   184\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\[\\\\\\\\n   185\\\\\\\\t\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\delta_{\\\\\\\\\\\\\\\\mathrm{ld}}(\\\\\\\\\\\\\\\\eps, q, m, d, k) = a\\\\\\\\\\\\\\\\,(dmk)^a \\\\\\\\\\\\\\\\bigl(\\\\\\\\\\\\\\\\eps^b + q^{-b} + 2^{-bmd}\\\\\\\\\\\\\\\\bigr)\\\\\\\\n   186\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\]\\\\\\\\n   187\\\\\\\\t\\\\\\\\tfor universal constants $a \\\\\\\\\\\\\\\\ge 1$ and $0 < b \\\\\\\\\\\\\\\\le 1$ such that the following holds. For all $\\\\\\\\\\\\\\\\eps > 0$ and every parameter tuple $\\\\\\\\\\\\\\\\mathsf{ldparams} = (q,m,d,k)$ as in Definition~\\\\\\\\\\\\\\\\ref{def:ld-game} (so $m, d, k \\\\\\\\\\\\\\\\ge 1$, $q$ is an admissible field size, and $m$ divides $q$), and for all projective strategies $(\\\\\\\\\\\\\\\\psi, A, B)$ that succeed with probability at least $1-\\\\\\\\\\\\\\\\eps$ in the game $\\\\\\\\\\\\\\\\mathfrak{G}^{\\\\\\\\\\\\\\\\mathrm{ld}}_{\\\\\\\\\\\\\\\\mathsf{ldparams}}$, there exist measurements\\\\\\\\n   188\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\[\\\\\\\\n   189\\\\\\\\t\\\\\\\\t\\\\\\\\tG^w \\\\\\\\\\\\\\\\in \\\\\\\\\\\\\\\\mathrm{PolyMeas}(m,q,d,k)\\\\\\\\n   190\\\\\\\\t\\\\\\\\t\\\\\\\\\\\\\\\\]\\\\\\\\n    30\\\\\\\\t\\\\\\\\n    31\\\\\\\\t/-- Numerical parameters for the low-degree game.  The ambient coefficient\\\\\\\\n    32\\\\\\\\tspace uses the once-and-for-all model `fixedFieldModel P.q P.hq`, rather than a\\\\\\\\n    33\\\\\\\\tmodel supplied by each parameter record.  This is the Lean carrier for\\\\\\\\n    34\\\\\\\\t`def:ld-game` in\\\\\\\\n    35\\\\\\\\t`blueprint/src/chapter/ch13_qpbt_test.tex:17-156`, with paper origin\\\\\\\\n    36\\\\\\\\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`.\\\\\\\\n    37\\\\\\\\t-/\\\\\\\\n    38\\\\\\\\tstructure LdParams where\\\\\\\\n    39\\\\\\\\t  q : ℕ\\\\\\\\n    40\\\\\\\\t  m : ℕ\\\\\\\\n    41\\\\\\\\t  d : ℕ\\\\\\\\n    42\\\\\\\\t  k : ℕ\\\\\\\\n    43\\\\\\\\t  hm : 1 ≤ m\\\\\\\\n    44\\\\\\\\t  hd : 1 ≤ d\\\\\\\\n    45\\\\\\\\t  hk : 1 ≤ k\\\\\\\\n    46\\\\\\\\t  hq : IsAdmissibleSize q\\\\\\\\n    47\\\\\\\\t  hdvd : m ∣ q\\\\\\\\n    48\\\\\\\\t\\\\\\\\n    49\\\\\\\\t/-- The positive dimension in `LdParams` supplies the finite coordinate type\\\\\\\\n    50\\\\\\\\tused by the uniform axis and prefix-index marginals. -/\\\\\\\\n    51\\\\\\\\tinstance (L : LdParams) : Nonempty (Fin L.m) :=\\\\\\\\n    52\\\\\\\\t  ⟨⟨0, lt_of_lt_of_le Nat.zero_lt_one L.hm⟩⟩\\\\\\\\n    53\\\\\\\\t\\\\\\\\n    54\\\\\\\\t/-- The fixed model accessor for an `LdParams` record.  It is a compatibility\\\\\\\\n    55\\\\\\\\tview of the global `fixedFieldModel` selector, not an independently quantified\\\\\\\\n    56\\\\\\\\tparameter.  Blueprint `ch13_qpbt_test.tex:17-32`; paper origin\\\\\\\\n    57\\\\\\\\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`.\\\\\\\\n    58\\\\\\\\t-/\\\\\\\\n    59\\\\\\\\tnoncomputable def LdParams.model (P : LdParams) : FixedFieldModel P.q :=\\\\\\\\n    60\\\\\\\\t  fixedFieldModel P.q P.hq\\\\\\\\n    61\\\\\\\\t\\\\\\\\n    62\\\\\\\\t/-- The scalar carrier selected by an `LdParams` record; this is the fixed\\\\\\\\n    63\\\\\\\\tfield carrier in `def:ld-game`, selected globally by `LdParams.model`.\\\\\\\\n    64\\\\\\\\tBlueprint `ch13_qpbt_test.tex:17-32`, paper origin\\\\\\\\n    65\\\\\\\\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`.\\\\\\\\n    66\\\\\\\\t-/\\\\\\\\n    67\\\\\\\\tabbrev ScalarQ (P : LdParams) := (P.model).K\\\\\\\\n    68\\\\\\\\t\\\\\\\\n    69\\\\\\\\t/-- The three low-degree question types of `def:ld-game`, blueprint\\\\\\\\n    70\\\\\\\\t`blueprint/src/chapter/ch13_qpbt_test.tex:17-32`, paper origin\\\\\\\\n    71\\\\\\\\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`.\\\\\\\\n    72\\\\\\\\t-/\\\\\\\\n    73\\\\\\\\tinductive LdType where\\\\\\\\n    74\\\\\\\\t  | point\\\\\\\\n    75\\\\\\\\t  | aline\\\\\\\\n    76\\\\\\\\t  | dline\\\\\\\\n    77\\\\\\\\t  deriving DecidableEq, Repr, Inhabited, Fintype\\\\\\\\n    78\\\\\\\\t\\\\\\\\n    79\\\\\\\\t/-- The register index used by the low-degree game (`def:ld-game`, blueprint\\\\\\\\n    80\\\\\\\\t`ch13_qpbt_test.tex:17-32`; paper origin\\\\\\\\n    81\\\\\\\\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`).\\\\\\\\n    82\\\\\\\\t-/\\\\\\\\n    83\\\\\\\\tabbrev LdIndex (P : LdParams) := (Fin P.m ⊕ Unit) ⊕ Fin P.m\\\\\\\\n    84\\\\\\\\t\\\\\\\\n    85\\\\\\\\t/-- The full ambient low-degree coefficient space (`def:ld-game`, blueprint\\\\\\\\n    86\\\\\\\\t`ch13_qpbt_test.tex:17-32`; paper origin\\\\\\\\n    87\\\\\\\\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`).\\\\\\\\n    88\\\\\\\\t-/\\\\\\\\n    89\\\\\\\\tabbrev LdSpace (P : LdParams) := LdIndex P → ScalarQ P\\\\\\\\n    90\\\\\\\\t\\\\\\\\n    91\\\\\\\\t/-- The point coordinates of an ambient low-degree vector in\\\\\\\\n    92\\\\\\\\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`.\\\\\\\\n    93\\\\\\\\t-/\\\\\\\\n    94\\\\\\\\tdef LdSpace.point {P : LdParams} (z : LdSpace P) : Fin P.m → ScalarQ P :=\\\\\\\\n    95\\\\\\\\t  fun i => z (.inl (.inl i))\\\\\\\\n    96\\\\\\\\t\\\\\\\\n    97\\\\\\\\t/-- The shared scalar coordinate of an ambient low-degree vector in\\\\\\\\n    98\\\\\\\\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`.\\\\\\\\n    99\\\\\\\\t-/\\\\\\\\n   100\\\\\\\\tdef LdSpace.seed {P : LdParams} (z : LdSpace P) : ScalarQ P :=\\\\\\\\n   101\\\\\\\\t  z (.inl (.inr ()) )\\\\\\\\n   102\\\\\\\\t\\\\\\\\n   103\\\\\\\\t/-- The direction coordinates of an ambient low-degree vector in\\\\\\\\n   104\\\\\\\\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`.\\\\\\\\n   105\\\\\\\\t-/\\\\\\\\n   106\\\\\\\\tdef LdSpace.direction {P : LdParams} (z : LdSpace P) : Fin P.m → ScalarQ P :=\\\\\\\\n   107\\\\\\\\t  fun i => z (.inr i)\\\\\\\\n   108\\\\\\\\t\\\\\\\\n   109\\\\\\\\t/-- The integer-coordinate map `χ` from the fixed field representation.  This\\\\\\\\n   110\\\\\\\\tis `eq:chi-func` in `def:ld-question-distribution`, blueprint\\\\\\\\n   111\\\\\\\\t`blueprint/src/chapter/ch13_qpbt_test.tex:34-59`, paper origin\\\\\\\\n   112\\\\\\\\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`.\\\\\\\\n   113\\\\\\\\t-/\\\\\\\\n   114\\\\\\\\tnoncomputable def chiIndex (P : LdParams) (s : ScalarQ P) : Fin P.m := by\\\\\\\\n   115\\\\\\\\t  letI : NeZero P.m := ⟨by\\\\\\\\n   116\\\\\\\\t    exact Nat.ne_of_gt (lt_of_lt_of_le Nat.zero_lt_one P.hm)⟩\\\\\\\\n   117\\\\\\\\t  exact Fin.ofNat P.m ((binaryRepresentation P.model s).val / (P.q / P.m))\\\\\\\\n   118\\\\\\\\t\\\\\\\\n   119\\\\\\\\t/-- The projection used in the diagonal-line map zeroes coordinates before the\\\\\\\\n   120\\\\\\\\tchosen index and retains the suffix of the direction vector.  This is the\\\\\\\\n   121\\\\\\\\tprefix restriction in `def:ld-question-distribution`, blueprint\\\\\\\\n   122\\\\\\\\t`blueprint/src/chapter/ch13_qpbt_test.tex:34-59`, paper origin\\\\\\\\n   123\\\\\\\\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`.\\\\\\\\n   124\\\\\\\\t-/\\\\\\\\n   125\\\\\\\\tdef prefixProjection {P : LdParams} (i : Fin P.m) (v : Fin P.m → ScalarQ P) :\\\\\\\\n   126\\\\\\\\t    Fin P.m → ScalarQ P :=\\\\\\\\n   127\\\\\\\\t  fun j => if j.val < i.val then 0 else v j\\\\\\\\n   128\\\\\\\\t\\\\\\\\n   129\\\\\\\\t/-- The point CL map, retaining the point block and clearing the auxiliary\\\\\\\\n   130\\\\\\\\tblocks.  It is the map `L_point` of `def:ld-question-distribution`, blueprint\\\\\\\\n   131\\\\\\\\t`blueprint/src/chapter/ch13_qpbt_test.tex:34-59`, paper origin\\\\\\\\n   132\\\\\\\\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`.\\\\\\\\n   133\\\\\\\\t-/\\\\\\\\n   134\\\\\\\\tdef ldPointCL (P : LdParams) (z : LdSpace P) : LdSpace P :=\\\\\\\\n   135\\\\\\\\t  fun i => match i with\\\\\\\\n   136\\\\\\\\t  | .inl (.inl j) => z (.inl (.inl j))\\\\\\\\n   137\\\\\\\\t  | .inl (.inr _) => 0\\\\\\\\n   138\\\\\\\\t  | .inr _ => 0\\\\\\\\n   139\\\\\\\\t\\\\\\\\n   140\\\\\\\\t/-- The affine-line CL map.  The direction block is put through the canonical\\\\\\\\n   141\\\\\\\\tline representative map from `def:line-representative`, while the point block\\\\\\\\n   142\\\\\\\\tis retained (blueprint `blueprint/src/chapter/ch13_qpbt_test.tex:34-59`; paper\\\\\\\\n   143\\\\\\\\torigin `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`).\\\\\\\\n   144\\\\\\\\t-/\\\\\\\\n   145\\\\\\\\tnoncomputable def ldALineCL (P : LdParams) (z : LdSpace P) : LdSpace P :=\\\\\\\\n   146\\\\\\\\t  let i := chiIndex P (z.seed)\\\\\\\\n   147\\\\\\\\t  let rep := lineRepMap (coordinateDirection i)\\\\\\\\n   148\\\\\\\\t  fun i => match i with\\\\\\\\n   149\\\\\\\\t  | .inl (.inl j) => (rep (z.point)) j\\\\\\\\n   150\\\\\\\\t  | .inl (.inr _) => z (.inl (.inr ()))\\\\\\\\n   151\\\\\\\\t  | .inr _ => 0\\\\\\\\n   152\\\\\\\\t\\\\\\\\n   153\\\\\\\\t/-- The diagonal-line CL map, using the same canonical representative interface\\\\\\\\n   154\\\\\\\\tfor the direction block.  This is the `L_DLine` clause of\\\\\\\\n   155\\\\\\\\t`def:ld-question-distribution` (blueprint\\\\\\\\n   156\\\\\\\\t`blueprint/src/chapter/ch13_qpbt_test.tex:34-59`; paper origin\\\\\\\\n   157\\\\\\\\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`).\\\\\\\\n   158\\\\\\\\t-/\\\\\\\\n   159\\\\\\\\tnoncomputable def ldDLineCL (P : LdParams) (z : LdSpace P) : LdSpace P :=\\\\\\\\n   160\\\\\\\\t  let i := chiIndex P (z.seed)\\\\\\\\n   161\\\\\\\\t  let direction := prefixProjection i (z.direction)\\\\\\\\n   162\\\\\\\\t  let rep := lineRepMap direction\\\\\\\\n   163\\\\\\\\t  fun i => match i with\\\\\\\\n   164\\\\\\\\t  | .inl (.inl j) => (rep (z.point)) j\\\\\\\\n   165\\\\\\\\t  | .inl (.inr _) => z (.inl (.inr ()))\\\\\\\\n   166\\\\\\\\t  | .inr j => direction j\\\\\\\\n   167\\\\\\\\t\\\\\\\\n   168\\\\\\\\t/-- Dispatch the three low-degree CL maps by question type.  This is the typed\\\\\\\\n   169\\\\\\\\tconstruction in `def:ld-question-distribution`, blueprint\\\\\\\\n   170\\\\\\\\t`blueprint/src/chapter/ch13_qpbt_test.tex:34-59`, paper origin\\\\\\\\n   171\\\\\\\\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`.\\\\\\\\n   172\\\\\\\\t-/\\\\\\\\n   173\\\\\\\\tnoncomputable def ldCL (P : LdParams) : LdType → LdSpace P → LdSpace P\\\\\\\\n   174\\\\\\\\t  | .point => ldPointCL P\\\\\\\\n   175\\\\\\\\t  | .aline => ldALineCL P\\\\\\\\n   176\\\\\\\\t  | .dline => ldDLineCL P\\\\\\\\n   177\\\\\\\\t\\\\\\\\n   178\\\\\\\\t/-- Formalization-only auxiliary: the register carrying the shared scalar\\\\\\\\n   179\\\\\\\\tcoordinate of the ambient low-degree space.  It is the first register in the\\\\\\\\n   180\\\\\\\\tconcatenation exhibiting the conditional-linearity levels asserted in\\\\\\\\n   600\\\\\\\\t/-- The diagonal line/point relation in `def:ld-win-predicate`, blueprint\\\\\\\\n   601\\\\\\\\t`ch13_qpbt_test.tex:137-156`, paper origin\\\\\\\\n   602\\\\\\\\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`.\\\\\\\\n   603\\\\\\\\t-/\\\\\\\\n   604\\\\\\\\tdef dlinePointCondition (P : LdParams) (line point : LdSpace P)\\\\\\\\n   605\\\\\\\\t    (f : Fin P.k → Fin (P.m * P.d + 1) → ScalarQ P)\\\\\\\\n   606\\\\\\\\t    (a : Fin P.k → ScalarQ P) : Prop :=\\\\\\\\n   607\\\\\\\\t  ∀ t : ScalarQ P,\\\\\\\\n   608\\\\\\\\t    point.point = line.point + t • line.direction →\\\\\\\\n   609\\\\\\\\t      ∀ j : Fin P.k, evalCoefficient (f j) t = a j\\\\\\\\n   610\\\\\\\\t\\\\\\\\n   611\\\\\\\\t/-- The low-degree consistency predicate, rejecting answers of the wrong\\\\\\\\n   612\\\\\\\\tconstructor shape.  This is `def:ld-win-predicate` in\\\\\\\\n   613\\\\\\\\t`blueprint/src/chapter/ch13_qpbt_test.tex:137-156`, paper origin\\\\\\\\n   614\\\\\\\\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`.\\\\\\\\n   615\\\\\\\\t-/\\\\\\\\n   616\\\\\\\\tnoncomputable def ldWinPredicate (P : LdParams) :\\\\\\\\n   617\\\\\\\\t    LdQuestion P → LdQuestion P → LdAnswer P → LdAnswer P → Bool :=\\\\\\\\n   618\\\\\\\\t  open Classical in\\\\\\\\n   619\\\\\\\\t  fun (tA, xA) (tB, xB) a b =>\\\\\\\\n   620\\\\\\\\t      if validLdAnswer tA a && validLdAnswer tB b then\\\\\\\\n   621\\\\\\\\t        match tA, tB, a, b with\\\\\\\\n   622\\\\\\\\t        | .point, .point, .pointVals u, .pointVals v => decide (u = v)\\\\\\\\n   623\\\\\\\\t        | .aline, .point, .alinePolys f, .pointVals u =>\\\\\\\\n   624\\\\\\\\t            decide (alinePointCondition P xA xB f u)\\\\\\\\n   625\\\\\\\\t        | .point, .aline, .pointVals u, .alinePolys f =>\\\\\\\\n   626\\\\\\\\t            decide (alinePointCondition P xB xA f u)\\\\\\\\n   627\\\\\\\\t        | .dline, .point, .dlinePolys f, .pointVals u =>\\\\\\\\n   628\\\\\\\\t            decide (dlinePointCondition P xA xB f u)\\\\\\\\n   629\\\\\\\\t        | .point, .dline, .pointVals u, .dlinePolys f =>\\\\\\\\n   630\\\\\\\\t            decide (dlinePointCondition P xB xA f u)\\\\\\\\n   631\\\\\\\\t        | .aline, .aline, .alinePolys f, .alinePolys g => decide (f = g)\\\\\\\\n   632\\\\\\\\t        | .dline, .dline, .dlinePolys f, .dlinePolys g => decide (f = g)\\\\\\\\n   633\\\\\\\\t        | _, _, _, _ => true\\\\\\\\n   634\\\\\\\\t      else false\\\\\\\\n   635\\\\\\\\t\\\\\\\\n   636\\\\\\\\t/-- The low-degree game packaged as a `Game`.  This is `def:ld-game` in\\\\\\\\n   637\\\\\\\\t`blueprint/src/chapter/ch13_qpbt_test.tex:17-156`, paper origin\\\\\\\\n   638\\\\\\\\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:31-391`.\\\\\\\\n   639\\\\\\\\t-/\\\\\\\\n   640\\\\\\\\tnoncomputable def ldGame (P : LdParams) : Game where\\\\\\\\n   641\\\\\\\\t  QuestionA := LdQuestion P\\\\\\\\n   642\\\\\\\\t  QuestionB := LdQuestion P\\\\\\\\n   643\\\\\\\\t  AnswerA := LdAnswer P\\\\\\\\n   644\\\\\\\\t  AnswerB := LdAnswer P\\\\\\\\n   645\\\\\\\\t  μ := ldQuestionDistribution P\\\\\\\\n   646\\\\\\\\t  μ_prob := by\\\\\\\\n   647\\\\\\\\t    exact Distribution.IsProbability.map\\\\\\\\n   648\\\\\\\\t      (uniformDistribution_isProbability ((LdType × LdType) × LdSpace P)) _\\\\\\\\n   649\\\\\\\\t  decide := ldWinPredicate P\\\\\\\\n   650\\\\\\\\t\\\\\\\\n   651\\\\\\\\tend\\\\\\\\n   652\\\\\\\\t\\\\\\\\n   653\\\\\\\\tend MIPStarRE.QPBT\\\\\\\\nMIPStarRE/QPBT/Combining/DirectLowDegree/Transport/SeedFiberValue.lean:90:private def ldAcceptedMass (L : LdParams) (S : Strategy (ldGame L))\\\\\\\\nMIPStarRE/QPBT/Combining/DirectLowDegree/Transport/SeedFiberValue.lean:105:    (S : Strategy (ldGame L)) (tA tB : LdType)\\\\\\\\nMIPStarRE/QPBT/Combining/DirectLowDegree/Transport/SeedFiberValue.lean:225:theorem ldStrategyToDirect_value_eq (L : LdParams) (S : Strategy (ldGame L)) :\\\\\\\\nMIPStarRE/QPBT/Test/LowDegreeGameTheorems.lean:454:        ∀ S : Strategy (ldGame L), S.IsProjective → 1 - ε ≤ S.value →\\\\\\\\nMIPStarRE/QPBT/Combining/DirectLowDegree/Transport/Consiste