gy (directLdGame D))\\\\n   437\\\\t    (hS : S.IsProjective) (r : Fin D.k) :\\\\n   438\\\\t    letI := D.toLDTFieldModel\\\\n   439\\\\t    ProjStrat D.toLDTParameters S.ιA S.ιB := by\\\\n   440\\\\t  letI := D.toLDTFieldModel\\\\n   441\\\\t  exact {\\\\n   442\\\\t    state := strategyQuantumState S\\\\n   443\\\\t    isNormalized := strategyQuantumState_isNormalized S\\\\n   444\\\\t    pointMeasurementA := directCoordinatePointMeasurement D r S.A hS.1\\\\n   445\\\\t    axisParallelMeasurementA := directCoordinateAxisMeasurement D r S.A hS.1\\\\n   446\\\\t    axisParallelReparamInvariantA :=\\\\n   447\\\\t      directCoordinateAxisMeasurement_reparam D r S.A hS.1\\\\n   448\\\\t    diagonalMeasurementA := directCoordinateDiagonalMeasurement D r S.A hS.1\\\\n   449\\\\t    diagonalReparamInvariantA :=\\\\n   450\\\\t      directCoordinateDiagonalMeasurement_reparam D r S.A hS.1\\\\n   451\\\\t    pointMeasurementB := directCoordinatePointMeasurement D r S.B hS.2\\\\n   452\\\\t    axisParallelMeasurementB := directCoordinateAxisMeasurement D r S.B hS.2\\\\n   453\\\\t    axisParallelReparamInvariantB :=\\\\n   454\\\\t      directCoordinateAxisMeasurement_reparam D r S.B hS.2\\\\n   455\\\\t    diagonalMeasurementB := directCoordinateDiagonalMeasurement D r S.B hS.2\\\\n   456\\\\t    diagonalReparamInvariantB :=\\\\n   457\\\\t      directCoordinateDiagonalMeasurement_reparam D r S.B hS.2\\\\n   458\\\\t  }\\\\n   459\\\\t\\\\n   460\\\\t/-- Point Born weights of the coordinate strategy are exactly the sums over\\\\n   461\\\\tthe corresponding direct-answer readout fibers. -/\\\\n   462\\\\ttheorem directCoordinateProjStrat_point_bornWeight\\\\n   463\\\\t    (D : DirectLdParams) (S : Strategy (directLdGame D))\\\\n   464\\\\t    (hS : S.IsProjective) (r : Fin D.k)\\\\n   465\\\\t    (u v : Point D.toLDTParameters)\\\\n   466\\\\t    (a b : Fq D.toLDTParameters) :\\\\n   467\\\\t    letI := D.toLDTFieldModel\\\\n   468\\\\t    ev (directCoordinateProjStrat D S hS r).state\\\\n   469\\\\t        (opTensor\\\\n   470\\\\t          (((directCoordinateProjStrat D S hS r).pointMeasurementA u).outcome a)\\\\n   471\\\\t          (((directCoordinateProjStrat D S hS r).pointMeasurementB v).outcome b)) =\\\\n   472\\\\t      ∑ directA ∈ Finset.univ.filter (fun answer =>\\\\n   473\\\\t          directPointAnswerReadout D r answer = a),\\\\n   474\\\\t        ∑ directB ∈ Finset.univ.filter (fun answer =>\\\\n   475\\\\t            directPointAnswerReadout D r answer = b),\\\\n   476\\\\t          outcomeWeight S (directPointQuestionOf D u)\\\\n   477\\\\t            (directPointQuestionOf D v) directA directB := by\\\\n   478\\\\t  letI := D.toLDTFieldModel\\\\n   479\\\\t  change ev (strategyQuantumState S)\\\\n   480\\\\t      (opTensor\\\\n   481\\\\t        ((ProjMeas.postprocess\\\\n   482\\\\t          (matrixMeasurementToLDTProjMeas\\\\n   483\\\\t            (S.A (directPointQuestionOf D u))\\\\n   484\\\\t            (hS.1 (directPointQuestionOf D u)))\\\\n   485\\\\t          (directPointAnswerReadout D r)).outcome a)\\\\n   486\\\\t        ((ProjMeas.postprocess\\\\n   487\\\\t          (matrixMeasurementToLDTProjMeas\\\\n   488\\\\t            (S.B (directPointQuestionOf D v))\\\\n   489\\\\t            (hS.2 (directPointQuestionOf D v)))\\\\n   490\\\\t          (directPointAnswerReadout D r)).outcome b)) = _\\\\n   190\\\\t  (directPointEquiv D).symm\\\\n   191\\\\t\\\\n   192\\\\t/-- The direct canonical axis question represented by a mature axis line.\\\\n   193\\\\tThe mature coordinate index is reversed together with the point\\\\n   194\\\\tcoordinates. -/\\\\n   195\\\\tnoncomputable def directAxisQuestionOf (D : DirectLdParams)\\\\n   196\\\\t    (line : AxisParallelLine D.toLDTParameters) : DirectLdQuestion D :=\\\\n   197\\\\t  let u := ldtPointToDirect D line.base\\\\n   198\\\\t  let i : Fin D.m := Fin.rev line.direction\\\\n   199\\\\t  let v : Fin D.m → DirectScalarQ D := coordinateDirection i\\\\n   200\\\\t  (.aline, ⟨lineRepMap v u, i, 0⟩)\\\\n   201\\\\t\\\\n   202\\\\t/-- The direct canonical diagonal question represented by a mature diagonal\\\\n   203\\\\tline.  The decoded direction is kept and the direct index is its leading\\\\n   204\\\\tindex, so the question is the canonical direct question of the direct sample\\\\n   205\\\\tformed by the decoded base, the leading index, and the decoded direction\\\\n   206\\\\t(`directDiagonalQuestionOf_eq_directLdMap`). -/\\\\n   207\\\\tnoncomputable def directDiagonalQuestionOf (D : DirectLdParams)\\\\n   208\\\\t    (line : DiagonalLine D.toLDTParameters) : DirectLdQuestion D :=\\\\n   209\\\\t  let u := ldtPointToDirect D line.base\\\\n   210\\\\t  let v := ldtPointToDirect D line.direction\\\\n   211\\\\t  (.dline, ⟨lineRepMap v u, directDiagonalIndexOf D v, v⟩)\\\\n   212\\\\t\\\\n   213\\\\t/-- The direct point question represented by a mature LDT point. -/\\\\n   214\\\\tnoncomputable def directPointQuestionOf (D : DirectLdParams)\\\\n   215\\\\t    (u : Point D.toLDTParameters) : DirectLdQuestion D :=\\\\n   216\\\\t  directLdPointQuestionOf D (ldtPointToDirect D u)\\\\n   217\\\\t\\\\n   218\\\\t/-- Every transported diagonal question is the canonical direct question of\\\\n   219\\\\tthe direct sample carrying the leading index, hence lies in the support of\\\\n   220\\\\tthe direct diagonal sampler. -/\\\\n   221\\\\ttheorem directDiagonalQuestionOf_eq_directLdMap (D : DirectLdParams)\\\\n   222\\\\t    (line : DiagonalLine D.toLDTParameters) :\\\\n   223\\\\t    directDiagonalQuestionOf D line =\\\\n   224\\\\t      (.dline, directLdMap D .dline\\\\n   225\\\\t        ⟨ldtPointToDirect D line.base,\\\\n   226\\\\t          directDiagonalIndexOf D (ldtPointToDirect D line.direction),\\\\n   227\\\\t          ldtPointToDirect D line.direction⟩) := by\\\\n   228\\\\t  unfold directDiagonalQuestionOf directLdMap\\\\n   229\\\\t  simp only [directPrefixProjection_directDiagonalIndexOf]\\\\n   230\\\\t\\\\n   231\\\\t/-- The mature diagonal line represented by a direct sample: the encoded\\\\n   232\\\\tpoint and the encoded direction. -/\\\\n   233\\\\tdef matureDiagonalLineOf (D : DirectLdParams) (sample : DirectLdSpace D) :\\\\n   234\\\\t    DiagonalLine D.toLDTParameters :=\\\\n   235\\\\t  { base := directPointEquiv D sample.point\\\\n   236\\\\t    direction := directPointEquiv D sample.direction }\\\\n   237\\\\t\\\\n   238\\\\t/-- Round trip on generic direct samples: when the sampled direction is\\\\n   239\\\\tnonzero at the sampled index, the mature line of the canonical direct\\\\n   240\\\\tdiagonal question transports back to that question, index included. -/\\\\n   241\\\\ttheorem directDiagonalQuestionOf_matureDiagonalLineOf (D : DirectLdParams)\\\\n   242\\\\t    (sample : DirectLdSpace D)\\\\n   243\\\\t    (hgeneric : sample.direction sample.index ≠ 0) :\\\\n   244\\\\t    directDiagonalQuestionOf D\\\\n   245\\\\t        (matureDiagonalLineOf D (directLdMap D .dline sample)) =\\\\n   246\\\\t      (.dline, directLdMap D .dline sample) := by\\\\n   247\\\\t  cases sample with\\\\n   248\\\\t  | mk point index direction =>\\\\n   249\\\\t      unfold directDiagonalQuestionOf matureDiagonalLineOf directLdMap\\\\n   250\\\\t      simp only [ldtPointToDirect, Equiv.symm_apply_apply, lineRepMap_apply_self,\\\\n   251\\\\t        directDiagonalIndexOf_prefixProjection D index direction hgeneric]\\\\n   252\\\\t\\\\n   253\\\\t/-- A mature `j`-restricted diagonal direction decodes to a direct direction\\\\n   254\\\\tvanishing before index `Fin.rev j`: the suffix restriction of the mature\\\\n   255\\\\ttest is the prefix restriction of the direct game. -/\\\\n   256\\\\ttheorem ldtPointToDirect_extendRestrictedDirection_prefix_zero\\\\n   257\\\\t    (D : DirectLdParams) (j : Fin D.m)\\\\n   258\\\\t    (free : Fin (j.val + 1) → Fq D.toLDTParameters) :\\\\n   259\\\\t    letI := D.toLDTFieldModel\\\\n   260\\\\t    ∀ c : Fin D.m, c.val < (Fin.rev j).val